export default "\\n\\n    Steps every 30 seconds: 5 -> 10 -> 15 -> 20 -> 25 -> 30 -> 35 users.\\n    Each step holds for exactly 30 seconds to measure steady-state performance.\\n    \\\"\\\"\\\"\\n\\n    def tick(self):\\n        run_time = self.get_run_time()\\n\\n        # Define the step progression with 30-second intervals\\n        steps = [\\n            (30, 5),  # 0-30s: 5 users\\n            (60, 10),  # 30-60s: 10 users\\n            (90, 15),  # 60-90s: 15 users\\n            (120, 20),  # 90-120s: 20 users\\n            (150, 25),  # 120-150s: 25 users\\n            (180, 30),  # 150-180s: 30 users\\n            (210, 35),  # 180-210s: 35 users\\n            (240, 40),  # 210-240s: 40 users\\n            (270, 45),  # 240-270s: 45 users\\n            (300, 50),  # 270-300s: 50 users\\n        ]\\n\\n        # Find current step\\n        for time_limit, user_count in steps:\\n            if run_time < time_limit:\\n                return user_count, 10  # Fast spawn rate for quick transitions\\n\\n        return None  # End test after 300 seconds\\n\\n\\n# Environment-scoped metrics tracking\\n_env_bags = {}\\n\\n\\n@events.test_start.add_listener\\ndef on_test_start(environment, **_kwargs):\\n    \\\"\\\"\\\"Initialize per-environment metrics tracking.\\\"\\\"\\\"\\n    # Set up enhanced error logging\\n    setup_error_logging()\\n\\n    _env_bags[environment] = {\\n        \\\"slow_10s\\\": 0,\\n        \\\"slow_20s\\\": 0,\\n    }\\n\\n\\n@events.request.add_listener\\ndef on_request(request_type, name, response_time, response_length, exception, context, **kwargs):  # noqa: ARG001\\n    \\\"\\\"\\\"Track slow requests using Locust's built-in timing.\\\"\\\"\\\"\\n    # response_time is in milliseconds from Locust\\n    bag = _env_bags.get(context.get(\\\"environment\\\") if context else None)\\n    if bag is None:\\n        # fallback: try the single environment we likely have\\n        if len(_env_bags) == 1:\\n            bag = next(iter(_env_bags.values()))\\n        else:\\n            return\\n\\n    if exception is None:  # Only count successful requests for timing\\n        if response_time > 10_000:  # 10 seconds in ms\\n            bag[\\\"slow_10s\\\"] += 1\\n        if response_time > 20_000:  # 20 seconds in ms\\n            bag[\\\"slow_20s\\\"] += 1\\n\\n\\n@events.test_stop.add_listener\\ndef on_test_stop(environment, **_kwargs):\\n    \\\"\\\"\\\"Print comprehensive test summary with performance grading.\\\"\\\"\\\"\\n    stats = environment.stats.total\\n    if stats.num_requests == 0:\\n        return\\n\\n    # Get percentiles and basic stats\\n    p50 = stats.get_response_time_percentile(0.50) or 0\\n    p95 = stats.get_response_time_percentile(0.95) or 0\\n    p99 = stats.get_response_time_percentile(0.99) or 0\\n    fail_ratio = stats.fail_ratio\\n    current_rps = getattr(stats, \\\"current_rps\\\", 0.0)\\n\\n    # Get slow request counts\\n    bag = _env_bags.get(environment, {\\\"slow_10s\\\": 0, \\\"slow_20s\\\": 0})\\n\\n    # Performance grading based on production criteria\\n    grade = \\\"A\\\"\\n    issues = []\\n\\n    if fail_ratio > 0.01:\\n        grade = \\\"B\\\"\\n        issues.append(f\\\"fail {fail_ratio:.1%}\\\")\\n    if fail_ratio > 0.05:\\n        grade = \\\"C\\\"\\n    if p95 > 10_000:\\n        grade = max(grade, \\\"D\\\")\\n        issues.append(f\\\"p95 {p95 / 1000:.1f}s\\\")\\n    if p95 > 20_000:\\n        grade = \\\"F\\\"\\n        issues.append(f\\\"p95 {p95 / 1000:.1f}s\\\")\\n\\n    print(f\\\"\\\\n{'=' * 60}\\\")\\n    print(f\\\"LANGFLOW API LOAD TEST RESULTS - GRADE: {grade}\\\")\\n    print(f\\\"{'=' * 60}\\\")\\n    print(f\\\"Requests: {stats.num_requests:,} | Failures: {stats.num_failures:,} ({fail_ratio:.1%})\\\")\\n    print(f\\\"Response Times: p50={p50 / 1000:.2f}s p95={p95 / 1000:.2f}s p99={p99 / 1000:.2f}s\\\")\\n    print(f\\\"RPS: {current_rps:.1f} | Slow requests: >10s={bag['slow_10s']} >20s={bag['slow_20s']}\\\")\\n\\n    if issues:\\n        print(f\\\"Issues: {', '.join(issues)}\\\")\\n\\n    # Production readiness assessment\\n    if grade in [\\\"A\\\", \\\"B\\\"]:\\n        print(\\\"\u2705 PRODUCTION READY - Performance meets production standards\\\")\\n    elif grade == \\\"C\\\":\\n        print(\\\"\u26a0\ufe0f  CAUTION - Acceptable but monitor closely in production\\\")\\n    else:\\n        print(\\\"\u274c NOT PRODUCTION READY - Significant performance issues detected\\\")\\n\\n    print(f\\\"{'=' * 60}\\\\n\\\")\\n\\n    # Save detailed error information\\n    save_error_summary()\\n\\n    # Capture Langflow logs\\n    capture_langflow_logs()\\n\\n    # Set exit code for CI/CD\\n    if fail_ratio > 0.01:\\n        environment.process_exit_code = 1\\n\\n    # Cleanup\\n    _env_bags.pop(environment, None)\\n\\n\\nclass BaseLangflowUser(FastHttpUser):\\n    \\\"\\\"\\\"Base class for all Langflow API load testing user types.\\\"\\\"\\\"\\n\\n    abstract = True\\n    REQUEST_TIMEOUT = float(os.getenv(\\\"REQUEST_TIMEOUT\\\", \\\"30.0\\\"))\\n\\n    # Use the host provided by environment variable or default\\n    host = os.getenv(\\\"LANGFLOW_HOST\\\", \\\"http://localhost:7860\\\")\\n\\n    def on_start(self):\\n        \\\"\\\"\\\"Called when a user starts before any task is scheduled.\\\"\\\"\\\"\\n        # Get credentials from environment variables\\n        self.api_key = os.getenv(\\\"API_KEY\\\")\\n        self.flow_id = os.getenv(\\\"FLOW_ID\\\")\\n\\n        if not self.api_key:\\n            raise ValueError(\\\"API_KEY environment variable is required. Run setup_langflow_test.py first.\\\")\\n\\n        if not self.flow_id:\\n            raise ValueError(\\\"FLOW_ID environment variable is required. Run setup_langflow_test.py first.\\\")\\n\\n        self.session_id = f\\\"locust_{self.__class__.__name__}_{id(self)}_{int(time.time())}\\\"\\n        self.request_count = 0\\n\\n        # Test connection and auth\\n        with self.client.get(\\\"/health\\\", catch_response=True) as response:\\n            if response.status_code != 200:\\n                raise ConnectionError(f\\\"Health check failed: {response.status_code}\\\")\\n\\n    def make_request(self, message_type=\\\"simple\\\", tag_suffix=\\\"\\\"):\\n        \\\"\\\"\\\"Make a request with proper error handling and timing.\\\"\\\"\\\"\\n        message = TEST_MESSAGES.get(message_type, TEST_MESSAGES[\\\"simple\\\"])\\n\\n        # Langflow API payload structure\\n        payload = {\\n            \\\"input_value\\\": message,\\n            \\\"output_type\\\": \\\"chat\\\",\\n            \\\"input_type\\\": \\\"chat\\\",\\n            \\\"tweaks\\\": {},\\n        }\\n\\n        headers = {\\n            \\\"x-api-key\\\": self.api_key,\\n            \\\"Content-Type\\\": \\\"application/json\\\",\\n            \\\"Accept\\\": \\\"application/json\\\",\\n        }\\n\\n        self.request_count += 1\\n        endpoint = f\\\"/api/v1/run/{self.flow_id}?stream=false\\\"\\n        name = f\\\"{endpoint} [{message_type}{tag_suffix}]\\\"\\n\\n        try:\\n            with self.client.post(\\n                endpoint,\\n                json=payload,\\n                headers=headers,\\n                name=name,\\n                timeout=self.REQUEST_TIMEOUT,\\n                catch_response=True,\\n            ) as response:\\n                # Get response text for error logging\\n                try:\\n                    response_text = response.text\\n                except Exception:\\n                    response_text = \\\"Could not read response text\\\"\\n\\n                # Handle successful responses\\n                if response.status_code == 200:\\n                    try:\\n                        data = response.json()\\n                        # Langflow API success check - look for outputs\\n                        if data.get(\\\"outputs\\\"):\\n                            return response.success()\\n                        # Check for error messages in the response\\n                        error_msg = data.get(\\\"detail\\\", \\\"Unknown error\\\")\\n\\n                        # Log detailed error for successful HTTP but failed flow execution\\n                        log_detailed_error(\\n                            user_class=self.__class__.__name__,\\n                            method=\\\"POST\\\",\\n                            url=f\\\"{self.host}{endpoint}\\\",\\n                            status_code=response.status_code,\\n                            response_text=response_text,\\n                            request_data=payload,\\n                            exception=None,\\n                        )\\n\\n                        return response.failure(f\\\"Flow execution failed: {error_msg}\\\")\\n                    except json.JSONDecodeError as e:\\n                        log_detailed_error(\\n                            user_class=self.__class__.__name__,\\n                            method=\\\"POST\\\",\\n                            url=f\\\"{self.host}{endpoint}\\\",\\n                            status_code=response.status_code,\\n                            response_text=response_text,\\n                            request_data=payload,\\n                            exception=e,\\n                        )\\n                        return response.failure(\\\"Invalid JSON response\\\")\\n\\n                # Log all error responses with detailed information\\n                log_detailed_error(\\n                    user_class=self.__class__.__name__,\\n                    method=\\\"POST\\\",\\n                    url=f\\\"{self.host}{endpoint}\\\",\\n                    status_code=response.status_code,\\n                    response_text=response_text,\\n                    request_data=payload,\\n                    exception=None,\\n                )\\n\\n                # Handle specific error cases\\n                if response.status_code in (429, 503):\\n                    return response.failure(f\\\"Backpressure/capacity: {response.status_code}\\\")\\n                if response.status_code == 401:\\n                    return response.failure(\\\"Unauthorized - API key issue\\\")\\n                if response.status_code == 404:\\n                    return response.failure(\\\"Flow not found - check FLOW_ID\\\")\\n                if response.status_code >= 500:\\n                    return response.failure(f\\\"Server error {response.status_code}\\\")\\n\\n                return response.failure(f\\\"HTTP {response.status_code}\\\")\\n\\n        except Exception as e:\\n            # Get more detailed error information\\n            error_details = {\\n                \\\"error_type\\\": type(e).__name__,\\n                \\\"error_message\\\": str(e),\\n                \\\"is_timeout\\\": \\\"timeout\\\" in str(e).lower(),\\n                \\\"is_connection_error\\\": \\\"connection\\\" in str(e).lower(),\\n                \\\"is_dns_error\\\": \\\"name resolution\\\" in str(e).lower() or \\\"dns\\\" in str(e).lower(),\\n            }\\n\\n            # Log any exceptions that occur during the request\\n            log_detailed_error(\\n                user_class=self.__class__.__name__,\\n                method=\\\"POST\\\",\\n                url=f\\\"{self.host}{endpoint}\\\",\\n                status_code=0,  # Connection error\\n                response_text=f\\\"Connection Error: {error_details}\\\",\\n                request_data=payload,\\n                exception=str(e),\\n                traceback=traceback.format_exc(),\\n            )\\n            # Re-raise the exception so Locust can handle it properly\\n            raise\\n\\n\\nclass NormalUser(BaseLangflowUser):\\n    \\\"\\\"\\\"Normal user simulating typical API interactions.\\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = between(0.5, 2)  # Typical user think time\\n\\n    @task(80)\\n    def send_message(self):\\n        \\\"\\\"\\\"Main task: Send a message with weighted distribution.\\\"\\\"\\\"\\n        message_type = random.choices([w[0] for w in MESSAGE_WEIGHTS], weights=[w[1] for w in MESSAGE_WEIGHTS], k=1)[0]  # noqa: S311\\n        self.make_request(message_type=message_type)\\n\\n    @task(15)\\n    def send_burst(self):\\n        \\\"\\\"\\\"Send a burst of 3 small messages quickly.\\\"\\\"\\\"\\n        for i in range(3):\\n            self.make_request(message_type=\\\"minimal\\\", tag_suffix=f\\\"-burst{i}\\\")\\n            gevent.sleep(0.1)  # Small delay between burst requests\\n\\n    @task(5)\\n    def send_complex(self):\\n        \\\"\\\"\\\"Occasionally send complex requests that stress the system.\\\"\\\"\\\"\\n        self.make_request(message_type=\\\"complex\\\")\\n\\n\\nclass AggressiveUser(BaseLangflowUser):\\n    \\\"\\\"\\\"Aggressive user with minimal wait times.\\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = between(0.1, 0.3)  # Very aggressive\\n\\n    @task\\n    def rapid_fire(self):\\n        \\\"\\\"\\\"Send requests as fast as possible.\\\"\\\"\\\"\\n        self.make_request(message_type=\\\"simple\\\", tag_suffix=\\\"-rapid\\\")\\n\\n\\nclass SustainedLoadUser(BaseLangflowUser):\\n    \\\"\\\"\\\"Maintains exactly 1 request/second for steady load testing.\\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = constant_pacing(1)  # Exactly 1 request per second per user\\n\\n    @task\\n    def steady_load(self):\\n        \\\"\\\"\\\"Send requests at constant 1 RPS per user.\\\"\\\"\\\"\\n        self.make_request(message_type=\\\"medium\\\", tag_suffix=\\\"-steady\\\")\\n\\n\\nclass TailLatencyHunter(BaseLangflowUser):\\n    \\\"\\\"\\\"Mixed workload designed to expose tail latency issues.\\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = between(0.8, 1.5)\\n\\n    @task\\n    def hunt_tail_latency(self):\\n        \\\"\\\"\\\"Alternate between simple and complex requests to find tail latency.\\\"\\\"\\\"\\n        if random.random() < 0.7:  # noqa: S311\\n            self.make_request(message_type=\\\"simple\\\", tag_suffix=\\\"-tail\\\")\\n        else:\\n            self.make_request(message_type=\\\"large\\\", tag_suffix=\\\"-tail-heavy\\\")\\n\\n\\nclass ScalabilityTestUser(BaseLangflowUser):\\n    \\\"\\\"\\\"Tests for scalability limits.\\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = constant(1.0)  # Constant load to test scaling\\n\\n    @task\\n    def scalability_test(self):\\n        \\\"\\\"\\\"Send medium complexity requests to test scaling limits.\\\"\\\"\\\"\\n        self.make_request(message_type=\\\"medium\\\", tag_suffix=\\\"-scale\\\")\\n\\n\\nclass BurstUser(BaseLangflowUser):\\n    \\\"\\\"\\\"Sends bursts of requests to test connection pooling.\\\"\\\"\\\"\\n\\n    weight = 3\\n    wait_time = between(5, 10)  # Long wait between bursts\\n\\n    @task\\n    def burst_attack(self):\\n        \\\"\\\"\\\"Send a burst of 10 requests quickly to test connection handling.\\\"\\\"\\\"\\n        for i in range(10):\\n            self.make_request(message_type=\\\"minimal\\\", tag_suffix=f\\\"-burst{i}\\\")\\n            gevent.sleep(0.05)  # 50ms between requests in burst\\n\\n\\n# Legacy user class for backward compatibility\\nclass FlowRunUser(NormalUser):\\n    \\\"\\\"\\\"Legacy FlowRunUser - now inherits from NormalUser for backward compatibility.\\\"\\\"\\\"\\n\\n\\n# Auto-select shape based on environment variable\\n_shape_env = os.getenv(\\\"SHAPE\\\", \\\"\\\").lower()\\n_selected = None\\n\\nif _shape_env == \\\"stepramp\\\":\\n    _selected = StepRamp\\nelif _shape_env == \\\"ramp100\\\":\\n    _selected = RampToHundred\\n\\nif _selected:\\n    # Create a single exported shape class and remove others so Locust sees only one\\n    SelectedLoadTestShape = type(\\\"SelectedLoadTestShape\\\", (_selected,), {})\\n    globals()[\\\"SelectedLoadTestShape\\\"] = SelectedLoadTestShape\\n\\n    # Remove other shape classes so Locust auto-picks the selected one\\n    for _name, _obj in list(globals().items()):\\n        if (\\n            inspect.isclass(_obj)\\n            and issubclass(_obj, LoadTestShape)\\n            and _obj is not SelectedLoadTestShape\\n            and _obj is not LoadTestShape\\n        ):\\n            del globals()[_name]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/locust/langflow_run_load_test.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6194c2cf9a4d460c874710c473573def9d601ee6e6eaf37af5b194c024b12297\",\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Langflow Load Test Runner\\n\\nThis script provides an easy way to run Langflow load tests.\\nFor first-time setup, use setup_langflow_test.py to create test credentials.\\n\\nUsage:\\n    # First time setup (run once):\\n    python setup_langflow_test.py --interactive\\n\\n    # Then run load tests:\\n    python run_load_test.py --help\\n    python run_load_test.py --users 10 --duration 60\\n    python run_load_test.py --shape ramp100 --host http://localhost:7860\\n\\\"\\\"\\\"\\n\\nimport argparse\\nimport os\\nimport subprocess\\nimport sys\\nimport time\\nfrom pathlib import Path\\n\\n\\ndef run_command(cmd, check=True, capture_output=False):\\n    \\\"\\\"\\\"Run a shell command with proper error handling.\\\"\\\"\\\"\\n    print(f\\\"Running: {' '.join(cmd) if isinstance(cmd, list) else cmd}\\\")\\n    try:\\n        if capture_output:\\n            result = subprocess.run(cmd, shell=isinstance(cmd, str), capture_output=True, text=True, check=check)\\n            return result.stdout.strip()\\n        subprocess.run(cmd, shell=isinstance(cmd, str), check=check)\\n    except subprocess.CalledProcessError as e:\\n        print(f\\\"Command failed: {e}\\\")\\n        if capture_output and e.stdout:\\n            print(f\\\"STDOUT: {e.stdout}\\\")\\n        if capture_output and e.stderr:\\n            print(f\\\"STDERR: {e.stderr}\\\")\\n        if check:\\n            sys.exit(1)\\n\\n\\ndef check_langflow_running(host):\\n    \\\"\\\"\\\"Check if Langflow is already running.\\\"\\\"\\\"\\n    try:\\n        import httpx\\n\\n        with httpx.Client(timeout=5.0) as client:\\n            response = client.get(f\\\"{host}/health\\\")\\n            return response.status_code == 200\\n    except Exception:\\n        return False\\n\\n\\ndef test_single_request(host):\\n    \\\"\\\"\\\"Test a single flow request to ensure the setup works before load testing.\\\"\\\"\\\"\\n    import os\\n\\n    import httpx\\n\\n    api_key = os.getenv(\\\"API_KEY\\\")\\n    flow_id = os.getenv(\\\"FLOW_ID\\\")\\n\\n    if not api_key or not flow_id:\\n        print(\\\"\u26a0\ufe0f  Missing API_KEY or FLOW_ID for test request\\\")\\n        return False\\n\\n    print(\\\"\\\\n\ud83e\uddea Testing single request before load test...\\\")\\n    print(f\\\"   Flow ID: {flow_id}\\\")\\n    print(f\\\"   API Key: {api_key[:20]}...\\\")\\n\\n    # First, test basic connectivity\\n    print(\\\"   \ud83d\udd17 Testing basic connectivity...\\\")\\n    try:\\n        with httpx.Client(timeout=10.0) as client:\\n            health_response = client.get(f\\\"{host}/health\\\")\\n            if health_response.status_code == 200:\\n                print(\\\"   \u2705 Health check passed\\\")\\n            else:\\n                print(f\\\"   \u26a0\ufe0f  Health check failed: {health_response.status_code}\\\")\\n                return False\\n    except Exception as e:\\n        print(f\\\"   \u274c Connectivity test failed: {e}\\\")\\n        print(f\\\"      Error type: {type(e).__name__}\\\")\\n        return False\\n\\n    # Now test the actual flow request\\n    print(\\\"   \ud83c\udfaf Testing flow request...\\\")\\n    try:\\n        url = f\\\"{host}/api/v1/run/{flow_id}?stream=false\\\"\\n        payload = {\\n            \\\"input_value\\\": \\\"Hello, this is a test message\\\",\\n            \\\"output_type\\\": \\\"chat\\\",\\n            \\\"input_type\\\": \\\"chat\\\",\\n            \\\"tweaks\\\": {},\\n        }\\n        headers = {\\\"x-api-key\\\": api_key, \\\"Content-Type\\\": \\\"application/json\\\"}\\n\\n        with httpx.Client(timeout=30.0) as client:\\n            response = client.post(url, json=payload, headers=headers)\\n\\n            print(f\\\"   \ud83d\udce1 Response status: {response.status_code}\\\")\\n\\n            if response.status_code == 200:\\n                try:\\n                    data = response.json()\\n                    if data.get(\\\"outputs\\\"):\\n                        print(\\\"   \u2705 Test request successful - flow is working!\\\")\\n                        return True\\n                    print(f\\\"   \u26a0\ufe0f  Flow executed but no outputs returned: {data}\\\")\\n                    return False\\n                except Exception as e:\\n                    print(f\\\"   \u26a0\ufe0f  Invalid JSON response: {e}\\\")\\n                    return False\\n            else:\\n                print(f\\\"   \u274c Test request failed: {response.status_code}\\\")\\n                print(f\\\"   Response: {response.text[:200]}...\\\")\\n                return False\\n\\n    except Exception as e:\\n        print(f\\\"   \u274c Test request error: {e}\\\")\\n        return False\\n\\n\\ndef wait_for_langflow(host, timeout=60):\\n    \\\"\\\"\\\"Wait for Langflow to be ready.\\\"\\\"\\\"\\n    print(f\\\"Waiting for Langflow to be ready at {host}...\\\")\\n    start_time = time.time()\\n\\n    while time.time() - start_time < timeout:\\n        if check_langflow_running(host):\\n            print(\\\"\u2705 Langflow is ready!\\\")\\n            return True\\n        time.sleep(2)\\n\\n    print(f\\\"\u274c Langflow did not start within {timeout} seconds\\\")\\n    return False\\n\\n\\ndef start_langflow(host, port):\\n    \\\"\\\"\\\"Start Langflow server if not already running.\\\"\\\"\\\"\\n    if check_langflow_running(host):\\n        print(f\\\"\u2705 Langflow is already running at {host}\\\")\\n        return None\\n\\n    print(f\\\"Starting Langflow server on port {port}...\\\")\\n\\n    # Start Langflow in the background\\n    cmd = [\\n        sys.executable,\\n        \\\"-m\\\",\\n        \\\"langflow\\\",\\n        \\\"run\\\",\\n        \\\"--host\\\",\\n        \\\"0.0.0.0\\\",\\n        \\\"--port\\\",\\n        str(port),\\n        \\\"--auto-login\\\",\\n        \\\"--log-level\\\",\\n        \\\"warning\\\",\\n    ]\\n\\n    process = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)\\n\\n    # Wait for it to be ready\\n    if wait_for_langflow(host, timeout=60):\\n        return process\\n    process.terminate()\\n    return None\\n\\n\\ndef run_locust_test(args):\\n    \\\"\\\"\\\"Run the Locust load test.\\\"\\\"\\\"\\n    locust_file = Path(__file__).parent / \\\"langflow_locustfile.py\\\"\\n\\n    # Check for required environment variables\\n    if not os.getenv(\\\"API_KEY\\\"):\\n        print(\\\"\u274c API_KEY environment variable not found!\\\")\\n        print(\\\"Run langflow_setup_test.py first to create test credentials.\\\")\\n        sys.exit(1)\\n\\n    if not os.getenv(\\\"FLOW_ID\\\"):\\n        print(\\\"\u274c FLOW_ID environment variable not found!\\\")\\n        print(\\\"Run langflow_setup_test.py first to create test credentials.\\\")\\n        sys.exit(1)\\n\\n    cmd = [\\n        \\\"locust\\\",\\n        \\\"-f\\\",\\n        str(locust_file),\\n        \\\"--host\\\",\\n        args.host,\\n    ]\\n\\n    # Add shape if specified\\n    env = os.environ.copy()\\n    if args.shape:\\n        env[\\\"SHAPE\\\"] = args.shape\\n\\n    # Add other environment variables\\n    env[\\\"LANGFLOW_HOST\\\"] = args.host\\n\\n    if args.headless:\\n        cmd.extend(\\n            [\\n                \\\"--headless\\\",\\n                \\\"--users\\\",\\n                str(args.users),\\n                \\\"--spawn-rate\\\",\\n                str(args.spawn_rate),\\n                \\\"--run-time\\\",\\n                f\\\"{args.duration}s\\\",\\n            ]\\n        )\\n\\n    if args.csv:\\n        cmd.extend([\\\"--csv\\\", args.csv])\\n\\n    if args.html:\\n        cmd.extend([\\\"--html\\\", args.html])\\n\\n    print(f\\\"\\\\n{'=' * 60}\\\")\\n    print(\\\"STARTING LOAD TEST\\\")\\n    print(f\\\"{'=' * 60}\\\")\\n    print(f\\\"Command: {' '.join(cmd)}\\\")\\n    print(f\\\"Host: {args.host}\\\")\\n    print(f\\\"Users: {args.users}\\\")\\n    print(f\\\"Duration: {args.duration}s\\\")\\n    print(f\\\"Shape: {args.shape or 'default'}\\\")\\n    print(f\\\"API Key: {env.get('API_KEY', 'N/A')[:20]}...\\\")\\n    print(f\\\"Flow ID: {env.get('FLOW_ID', 'N/A')}\\\")\\n    if args.html:\\n        print(f\\\"HTML Report: {args.html}\\\")\\n    if args.csv:\\n        print(f\\\"CSV Reports: {args.csv}_*.csv\\\")\\n    print(f\\\"{'=' * 60}\\\\n\\\")\\n\\n    subprocess.run(cmd, check=False, env=env)\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(\\n        description=\\\"Run Langflow load tests with automatic setup\\\",\\n        formatter_class=argparse.RawDescriptionHelpFormatter,\\n        epilog=\\\"\\\"\\\"\\nExamples:\\n  # Run with web UI (interactive)\\n  python run_load_test.py\\n\\n  # Run headless test with 50 users for 2 minutes\\n  python run_load_test.py --headless --users 50 --duration 120\\n\\n  # Run with specific load shape\\n  python run_load_test.py --shape ramp100 --headless --users 100 --duration 180\\n\\n  # Run against existing Langflow instance\\n  python run_load_test.py --host http://localhost:8000 --no-start-langflow\\n\\n  # Save results to CSV\\n  python run_load_test.py --headless --csv results --users 25 --duration 60\\n        \\\"\\\"\\\",\\n    )\\n\\n    # Langflow options\\n    parser.add_argument(\\n        \\\"--host\\\",\\n        default=\\\"http://localhost:7860\\\",\\n        help=\\\"Langflow host URL (default: http://localhost:7860, use https:// for remote instances)\\\",\\n    )\\n    parser.add_argument(\\\"--port\\\", type=int, default=7860, help=\\\"Port to start Langflow on (default: 7860)\\\")\\n    parser.add_argument(\\n        \\\"--no-start-langflow\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Don't start Langflow automatically (assume it's already running)\\\",\\n    )\\n\\n    # Load test options\\n    parser.add_argument(\\\"--headless\\\", action=\\\"store_true\\\", help=\\\"Run in headless mode (no web UI)\\\")\\n    parser.add_argument(\\\"--users\\\", type=int, default=50, help=\\\"Number of concurrent users (default: 20)\\\")\\n    parser.add_argument(\\n        \\\"--spawn-rate\\\", type=int, default=2, help=\\\"Rate to spawn users at (users per second, default: 2)\\\"\\n    )\\n    parser.add_argument(\\\"--duration\\\", type=int, default=60, help=\\\"Test duration in seconds (default: 60)\\\")\\n    parser.add_argument(\\\"--shape\\\", choices=[\\\"ramp100\\\", \\\"stepramp\\\"], help=\\\"Load test shape to use\\\")\\n    parser.add_argument(\\\"--csv\\\", help=\\\"Save results to CSV files with this prefix\\\")\\n    parser.add_argument(\\\"--html\\\", help=\\\"Generate HTML report with this filename (e.g., report.html)\\\")\\n\\n    args = parser.parse_args()\\n\\n    # Check dependencies\\n    try:\\n        import httpx\\n        import locust\\n    except ImportError as e:\\n        print(f\\\"\u274c Missing dependency: {e}\\\")\\n        print(\\\"Install with: pip install locust httpx\\\")\\n        sys.exit(1)\\n\\n    langflow_process = None\\n\\n    try:\\n        # Start Langflow if needed\\n        if not args.no_start_langflow:\\n            if args.host.startswith(\\\"https://\\\") or not args.host.startswith(\\\"http://localhost\\\"):\\n                print(f\\\"\u26a0\ufe0f  Remote host detected: {args.host}\\\")\\n                print(\\\"   For remote instances, use --no-start-langflow flag\\\")\\n                print(\\\"   Example: --host https://your-remote-instance.com --no-start-langflow\\\")\\n                sys.exit(1)\\n\\n            langflow_process = start_langflow(args.host, args.port)\\n            if not langflow_process:\\n                print(\\\"\u274c Failed to start Langflow\\\")\\n                sys.exit(1)\\n        # Just check if it's running\\n        elif not check_langflow_running(args.host):\\n            print(f\\\"\u274c Langflow is not running at {args.host}\\\")\\n            if args.host.startswith(\\\"https://\\\"):\\n                print(\\\"   Make sure your remote Langflow instance is accessible\\\")\\n            else:\\n                print(\\\"Either start Langflow manually or remove --no-start-langflow flag\\\")\\n            sys.exit(1)\\n        else:\\n            print(f\\\"\ud83d\udd17 Using existing Langflow instance at {args.host}\\\")\\n            if args.host.startswith(\\\"https://\\\"):\\n                print(\\\"   \u2705 Remote instance mode\\\")\\n\\n        # Test a single request before running the full load test\\n        if not test_single_request(args.host):\\n            print(\\\"\u274c Single request test failed. Aborting load test.\\\")\\n            sys.exit(1)\\n\\n        # Run the load test\\n        run_locust_test(args)\\n\\n    except KeyboardInterrupt:\\n        print(\\\"\\\\n\u26a0\ufe0f  Test interrupted by user\\\")\\n    except Exception as e:\\n        print(f\\\"\u274c Error: {e}\\\")\\n        sys.exit(1)\\n    finally:\\n        # Clean up Langflow process\\n        if langflow_process:\\n            print(\\\"\\\\nStopping Langflow server...\\\")\\n            langflow_process.terminate()\\n            try:\\n                langflow_process.wait(timeout=10)\\n            except subprocess.TimeoutExpired:\\n                langflow_process.kill()\\n            print(\\\"\u2705 Langflow server stopped\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/locust/langflow_setup_test.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c98a434c2be011ea26849b077f6cd1643fe4efffa4a4bd5d85ded7e2eaffe7b4\",\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Langflow Load Test Setup CLI\\n\\nThis script sets up a complete Langflow test environment by:\\n1. Starting Langflow (optional)\\n2. Creating a test user account\\n3. Authenticating and getting JWT tokens\\n4. Creating API keys\\n5. Loading a real starter project flow\\n6. Providing credentials for load testing\\n\\nUsage:\\n    python setup_langflow_test.py --help\\n    python setup_langflow_test.py --interactive\\n    python setup_langflow_test.py --flow \\\"Basic Prompting\\\"\\n    python setup_langflow_test.py --list-flows\\n\\\"\\\"\\\"\\n\\nimport argparse\\nimport asyncio\\nimport json\\nimport os\\nimport sys\\nimport time\\n\\n\\nasync def authenticate_setup_client(client) -> tuple[str, str, str]:\\n    \\\"\\\"\\\"Return an access token using explicit credentials or AUTO_LOGIN.\\\"\\\"\\\"\\n    configured_username = os.environ.get(\\\"LANGFLOW_SUPERUSER\\\", \\\"\\\")\\n    password = os.environ.get(\\\"LANGFLOW_SUPERUSER_PASSWORD\\\", \\\"\\\")\\n\\n    if configured_username and not password:\\n        raise RuntimeError(\\\"Set LANGFLOW_SUPERUSER_PASSWORD when LANGFLOW_SUPERUSER is set, or unset both.\\\")\\n\\n    if password:\\n        username = configured_username or \\\"langflow\\\"\\n        login_response = await client.post(\\n            \\\"/api/v1/login\\\",\\n            data={\\\"username\\\": username, \\\"password\\\": password},\\n            headers={\\\"Content-Type\\\": \\\"application/x-www-form-urlencoded\\\"},\\n        )\\n        if login_response.status_code != 200:\\n            raise RuntimeError(f\\\"Login failed: {login_response.status_code} - {login_response.text}\\\")\\n        return login_response.json()[\\\"access_token\\\"], username, \\\"<redacted>\\\"\\n\\n    auto_login_response = await client.get(\\\"/api/v1/auto_login\\\")\\n    if auto_login_response.status_code != 200:\\n        raise RuntimeError(\\n            \\\"Authentication failed. Set LANGFLOW_SUPERUSER_PASSWORD and optionally LANGFLOW_SUPERUSER, \\\"\\n            \\\"or enable LANGFLOW_AUTO_LOGIN.\\\"\\n        )\\n    return auto_login_response.json()[\\\"access_token\\\"], \\\"auto-login\\\", \\\"\\\"\\n\\n\\nasync def get_starter_projects_from_api(host: str, access_token: str) -> list[dict]:\\n    \\\"\\\"\\\"Get starter projects from Langflow API.\\\"\\\"\\\"\\n    import httpx\\n\\n    # Ensure proper URL formatting\\n    base_host = host.rstrip(\\\"/\\\")\\n    url = f\\\"{base_host}/api/v1/starter-projects/\\\"\\n    print(f\\\"   \ud83d\udd0d Fetching starter projects from: {url}\\\")\\n\\n    try:\\n        async with httpx.AsyncClient() as client:\\n            # Try with authentication first\\n            response = await client.get(\\n                url,\\n                headers={\\\"Authorization\\\": f\\\"Bearer {access_token}\\\"},\\n                timeout=30.0,\\n            )\\n\\n            print(f\\\"   \ud83d\udce1 Response status: {response.status_code}\\\")\\n\\n            # If auth fails, try without authentication (some endpoints might be public)\\n            if response.status_code == 401:\\n                print(\\\"   \ud83d\udd04 Trying without authentication...\\\")\\n                response = await client.get(url, timeout=30.0)\\n                print(f\\\"   \ud83d\udce1 Response status (no auth): {response.status_code}\\\")\\n\\n            if response.status_code != 200:\\n                print(f\\\"\u26a0\ufe0f  Failed to get starter projects: {response.status_code}\\\")\\n                print(f\\\"Response: {response.text}\\\")\\n                return []\\n\\n            # Check if response is empty\\n            if not response.text.strip():\\n                print(\\\"\u26a0\ufe0f  Empty response from starter projects endpoint\\\")\\n                return []\\n\\n            data = response.json()\\n            print(f\\\"   \u2705 Found {len(data)} starter projects\\\")\\n            return data\\n\\n    except Exception as e:\\n        print(f\\\"\u26a0\ufe0f  Error fetching starter projects: {e}\\\")\\n        if hasattr(e, \\\"response\\\"):\\n            print(f\\\"   Status code: {e.response.status_code}\\\")\\n            print(f\\\"   Response text: {e.response.text}\\\")\\n        return []\\n\\n\\nasync def list_available_flows(host: str, access_token: str) -> list[tuple[str, str, str]]:\\n    \\\"\\\"\\\"List all available starter project flows from Langflow API.\\n\\n    Args:\\n        host: Langflow host URL\\n        access_token: JWT access token for authentication\\n\\n    Returns:\\n        List of tuples: (flow_name, flow_name, description)\\n    \\\"\\\"\\\"\\n    projects = await get_starter_projects_from_api(host, access_token)\\n\\n    # Known starter project names and descriptions based on the source code\\n    known_projects = [\\n        (\\n            \\\"Basic Prompting\\\",\\n            \\\"Basic Prompting\\\",\\n            \\\"A simple chat interface with OpenAI that answers like a pirate \u2705 Great for load testing\\\",\\n        ),\\n        (\\n            \\\"Blog Writer\\\",\\n            \\\"Blog Writer\\\",\\n            \\\"Generate blog posts using web content as reference material \u2705 Good for load testing\\\",\\n        ),\\n        (\\n            \\\"Document Q&A\\\",\\n            \\\"Document Q&A\\\",\\n            \\\"Question and answer system for document content \u26a0\ufe0f  Requires file uploads - not ideal for load testing\\\",\\n        ),\\n        (\\\"Memory Chatbot\\\", \\\"Memory Chatbot\\\", \\\"Chatbot with conversation memory using context \u2705 Good for load testing\\\"),\\n        (\\n            \\\"Vector Store RAG\\\",\\n            \\\"Vector Store RAG\\\",\\n            \\\"Retrieval-Augmented Generation with vector storage \u26a0\ufe0f  May require setup - test first\\\",\\n        ),\\n    ]\\n\\n    # Return the known projects if we have the expected number\\n    if len(projects) == len(known_projects):\\n        return known_projects\\n\\n    # Fallback: generate names based on project count\\n    flows: list[tuple[str, str, str]] = []\\n    for i, project in enumerate(projects):\\n        if i < len(known_projects):\\n            flow_name, name, description = known_projects[i]\\n        else:\\n            flow_name = f\\\"Starter Project {i + 1}\\\"\\n            name = flow_name\\n            description = \\\"Starter project flow\\\"\\n\\n        flows.append((flow_name, name, description))\\n\\n    return flows\\n\\n\\nasync def get_flow_data_by_name(host: str, access_token: str, flow_name: str) -> dict | None:\\n    \\\"\\\"\\\"Get flow data for a specific starter project by name.\\n\\n    Args:\\n        host: Langflow host URL\\n        access_token: JWT access token for authentication\\n        flow_name: Name of the flow to retrieve\\n\\n    Returns:\\n        Flow data as dictionary, or None if not found\\n    \\\"\\\"\\\"\\n    projects = await get_starter_projects_from_api(host, access_token)\\n    flows = await list_available_flows(host, access_token)\\n\\n    # Find the project by name and get its index\\n    for i, (fname, name, _) in enumerate(flows):\\n        if name == flow_name:\\n            if i < len(projects):\\n                # Add the name and description to the project data\\n                project_data = projects[i].copy()\\n                project_data[\\\"name\\\"] = name\\n                project_data[\\\"description\\\"] = flows[i][2]\\n                return project_data\\n\\n    print(f\\\"\u26a0\ufe0f  Flow '{flow_name}' not found in starter projects\\\")\\n    return None\\n\\n\\nasync def select_flow_interactive(host: str, access_token: str) -> str | None:\\n    \\\"\\\"\\\"Interactive flow selection.\\\"\\\"\\\"\\n    flows = await list_available_flows(host, access_token)\\n\\n    if not flows:\\n        print(\\\"\u274c No starter project flows found!\\\")\\n        return None\\n\\n    print(f\\\"\\\\n{'=' * 80}\\\")\\n    print(\\\"AVAILABLE STARTER PROJECT FLOWS\\\")\\n    print(f\\\"{'=' * 80}\\\")\\n\\n    for i, (flow_name, name, description) in enumerate(flows, 1):\\n        print(f\\\"{i:2d}. {name}\\\")\\n        print(f\\\"    {description[:70]}{'...' if len(description) > 70 else ''}\\\")\\n        print()\\n\\n    while True:\\n        try:\\n            choice = input(f\\\"Select a flow (1-{len(flows)}) or 'q' to quit: \\\").strip()\\n            if choice.lower() == \\\"q\\\":\\n                return None\\n\\n            choice_num = int(choice)\\n            if 1 <= choice_num <= len(flows):\\n                selected_flow = flows[choice_num - 1]\\n                print(f\\\"\\\\n\u2705 Selected: {selected_flow[1]}\\\")\\n                return selected_flow[0]  # Return flow name\\n            print(f\\\"Please enter a number between 1 and {len(flows)}\\\")\\n        except ValueError:\\n            print(\\\"Please enter a valid number or 'q' to quit\\\")\\n        except KeyboardInterrupt:\\n            print(\\\"\\\\n\\\\nSetup cancelled by user\\\")\\n            return None\\n\\n\\nasync def setup_langflow_environment(host: str, flow_name: str | None = None, interactive: bool = False) -> dict:\\n    \\\"\\\"\\\"Set up complete Langflow environment with real starter project flows.\\\"\\\"\\\"\\n    try:\\n        import httpx\\n    except ImportError:\\n        print(\\\"\u274c Missing dependency: httpx\\\")\\n        print(\\\"Install with: pip install httpx\\\")\\n        sys.exit(1)\\n\\n    setup_state = {\\n        \\\"host\\\": host,\\n        \\\"username\\\": None,\\n        \\\"password\\\": None,\\n        \\\"user_id\\\": None,\\n        \\\"access_token\\\": None,\\n        \\\"api_key\\\": None,\\n        \\\"flow_id\\\": None,\\n        \\\"flow_name\\\": None,\\n        \\\"flow_data\\\": None,\\n    }\\n\\n    async with httpx.AsyncClient(base_url=host, timeout=60.0) as client:\\n        # Step 1: Health check\\n        print(f\\\"\\\\n1. Checking Langflow health at {host}...\\\")\\n        try:\\n            health_response = await client.get(\\\"/health\\\")\\n            if health_response.status_code != 200:\\n                raise Exception(f\\\"Health check failed: {health_response.status_code}\\\")\\n            print(\\\"   \u2705 Langflow is running and accessible\\\")\\n        except Exception as e:\\n            print(f\\\"   \u274c Health check failed: {e}\\\")\\n            raise\\n\\n        # Step 2: Authenticate with configured credentials or AUTO_LOGIN\\n        print(\\\"2. Authenticating...\\\")\\n\\n        try:\\n            access_token, username, password = await authenticate_setup_client(client)\\n            setup_state[\\\"access_token\\\"] = access_token\\n            setup_state[\\\"username\\\"] = username\\n            setup_state[\\\"password\\\"] = password\\n            print(\\\"   \u2705 Authentication successful\\\")\\n        except Exception as e:\\n            print(f\\\"   \u274c Authentication failed: {e}\\\")\\n            raise\\n\\n        # Step 3: Create API key\\n        print(\\\"3. Creating API key...\\\")\\n        headers = {\\\"Authorization\\\": f\\\"Bearer {setup_state['access_token']}\\\"}\\n\\n        try:\\n            api_key_data = {\\\"name\\\": f\\\"Load Test Key - {int(time.time())}\\\"}\\n            api_key_response = await client.post(\\\"/api/v1/api_key/\\\", json=api_key_data, headers=headers)\\n\\n            if api_key_response.status_code != 200:\\n                raise Exception(f\\\"API key creation failed: {api_key_response.status_code} - {api_key_response.text}\\\")\\n\\n            api_key_info = api_key_response.json()\\n            setup_state[\\\"api_key\\\"] = api_key_info[\\\"api_key\\\"]\\n            print(f\\\"   \u2705 API key created: {api_key_info['api_key'][:20]}...\\\")\\n        except Exception as e:\\n            print(f\\\"   \u274c API key creation failed: {e}\\\")\\n            raise\\n\\n        # Step 4: Select and load flow from API\\n        print(\\\"4. Selecting starter project flow...\\\")\\n\\n        # Flow selection logic\\n        selected_flow_name = None\\n        if interactive:\\n            selected_flow_name = await select_flow_interactive(host, setup_state[\\\"access_token\\\"])\\n            if not selected_flow_name:\\n                print(\\\"No flow selected. Exiting.\\\")\\n                sys.exit(0)\\n        elif flow_name:\\n            # Verify the flow exists in the API\\n            flows = await list_available_flows(host, setup_state[\\\"access_token\\\"])\\n            for fname, name, _ in flows:\\n                if name.lower() == flow_name.lower():\\n                    selected_flow_name = name\\n                    break\\n\\n            if not selected_flow_name:\\n                print(f\\\"\u274c Flow '{flow_name}' not found in starter projects!\\\")\\n                print(\\\"Available flows:\\\")\\n                for _, name, _ in flows:\\n                    print(f\\\"  - {name}\\\")\\n                sys.exit(1)\\n        else:\\n            # Default to Basic Prompting\\n            selected_flow_name = \\\"Basic Prompting\\\"\\n            print(\\\"   Using default flow: Basic Prompting\\\")\\n\\n        # Get flow data from API\\n        flow_data = await get_flow_data_by_name(host, setup_state[\\\"access_token\\\"], selected_flow_name)\\n        if not flow_data:\\n            print(f\\\"\u274c Could not load flow data for '{selected_flow_name}'\\\")\\n            sys.exit(1)\\n\\n        setup_state[\\\"flow_name\\\"] = flow_data.get(\\\"name\\\", selected_flow_name)\\n        setup_state[\\\"flow_data\\\"] = flow_data\\n\\n        print(f\\\"   \u2705 Selected flow: {setup_state['flow_name']}\\\")\\n        print(f\\\"   Description: {flow_data.get('description', 'No description')}\\\")\\n\\n        # Step 5: Upload the selected flow\\n        print(f\\\"5. Uploading flow: {setup_state['flow_name']}...\\\")\\n\\n        try:\\n            # Prepare flow data for upload\\n            # Remove the id to let Langflow generate a new one\\n            flow_upload_data = flow_data.copy()\\n            if \\\"id\\\" in flow_upload_data:\\n                del flow_upload_data[\\\"id\\\"]\\n\\n            # Ensure endpoint_name is unique and valid (only letters, numbers, hyphens, underscores)\\n            import re\\n\\n            sanitized_name = re.sub(r\\\"[^a-zA-Z0-9_-]\\\", \\\"_\\\", setup_state[\\\"flow_name\\\"].lower())\\n            flow_upload_data[\\\"endpoint_name\\\"] = f\\\"loadtest_{int(time.time())}_{sanitized_name}\\\"\\n\\n            flow_response = await client.post(\\\"/api/v1/flows/\\\", json=flow_upload_data, headers=headers)\\n\\n            if flow_response.status_code != 201:\\n                raise Exception(f\\\"Flow upload failed: {flow_response.status_code} - {flow_response.text}\\\")\\n\\n            flow_info = flow_response.json()\\n            setup_state[\\\"flow_id\\\"] = flow_info[\\\"id\\\"]\\n            print(\\\"   \u2705 Flow uploaded successfully\\\")\\n            print(f\\\"      Flow ID: {flow_info['id']}\\\")\\n            print(f\\\"      Endpoint: {flow_info.get('endpoint_name', 'N/A')}\\\")\\n        except Exception as e:\\n            print(f\\\"   \u274c Flow upload failed: {e}\\\")\\n            raise\\n\\n    return setup_state\\n\\n\\ndef print_setup_results(setup_state: dict):\\n    \\\"\\\"\\\"Print the setup results in a clear format.\\\"\\\"\\\"\\n    print(f\\\"\\\\n{'=' * 80}\\\")\\n    print(\\\"SETUP COMPLETE - LOAD TEST CREDENTIALS\\\")\\n    print(f\\\"{'=' * 80}\\\")\\n    print(f\\\"Host:        {setup_state['host']}\\\")\\n    print(f\\\"Username:    {setup_state['username']}\\\")\\n    print(f\\\"Password:    {setup_state['password']}\\\")\\n    print(f\\\"User ID:     {setup_state.get('user_id', 'N/A')}\\\")\\n    print(f\\\"JWT Token:   {setup_state['access_token'][:50]}...\\\" if setup_state[\\\"access_token\\\"] else \\\"N/A\\\")\\n    print(f\\\"API Key:     {setup_state['api_key']}\\\")\\n    print(f\\\"Flow ID:     {setup_state['flow_id']}\\\")\\n    print(f\\\"Flow Name:   {setup_state['flow_name']}\\\")\\n    print(f\\\"{'=' * 80}\\\")\\n\\n    print(\\\"\\\\n\ud83d\udccb COPY THESE COMMANDS TO RUN LOAD TESTS:\\\")\\n    print(f\\\"{'=' * 80}\\\")\\n\\n    # Environment variables for easy copy-paste\\n    print(\\\"# Set environment variables:\\\")\\n    print(f\\\"export LANGFLOW_HOST='{setup_state['host']}'\\\")\\n    print(f\\\"export API_KEY='{setup_state['api_key']}'\\\")\\n    print(f\\\"export FLOW_ID='{setup_state['flow_id']}'\\\")\\n    print()\\n\\n    # Direct locust commands\\n    print(\\\"# Run load test with web UI:\\\")\\n    print(f\\\"locust -f locustfile.py --host {setup_state['host']}\\\")\\n    print()\\n\\n    print(\\\"# Run headless load test (50 users, 2 minutes):\\\")\\n    print(f\\\"locust -f locustfile.py --host {setup_state['host']} --headless --users 50 --spawn-rate 5 --run-time 120s\\\")\\n    print()\\n\\n    print(\\\"# Run with load shape:\\\")\\n    print(\\n        f\\\"SHAPE=ramp100 locust -f locustfile.py --host {setup_state['host']} --headless --users 100 --spawn-rate 5 --run-time 180s\\\"\\n    )\\n    print()\\n\\n    print(\\\"# Or use the runner script:\\\")\\n    print(\\n        f\\\"python run_load_test.py --host {setup_state['host']} --no-start-langflow --headless --users 25 --duration 120\\\"\\n    )\\n    print()\\n\\n    print(\\\"# Generate HTML report:\\\")\\n    print(\\n        f\\\"python run_load_test.py --host {setup_state['host']} --no-start-langflow --headless --users 50 --duration 180 --html report.html\\\"\\n    )\\n\\n    print(f\\\"\\\\n{'=' * 80}\\\")\\n\\n\\ndef save_credentials(setup_state: dict, output_file: str):\\n    \\\"\\\"\\\"Save credentials to a file for later use.\\\"\\\"\\\"\\n    credentials = {\\n        \\\"host\\\": setup_state[\\\"host\\\"],\\n        \\\"api_key\\\": setup_state[\\\"api_key\\\"],\\n        \\\"flow_id\\\": setup_state[\\\"flow_id\\\"],\\n        \\\"flow_name\\\": setup_state[\\\"flow_name\\\"],\\n        \\\"username\\\": setup_state[\\\"username\\\"],\\n        \\\"password\\\": setup_state[\\\"password\\\"],\\n        \\\"access_token\\\": setup_state[\\\"access_token\\\"],\\n        \\\"created_at\\\": time.time(),\\n    }\\n\\n    try:\\n        with open(output_file, \\\"w\\\") as f:\\n            json.dump(credentials, f, indent=2)\\n        print(f\\\"\\\\n\ud83d\udcbe Credentials saved to: {output_file}\\\")\\n    except Exception as e:\\n        print(f\\\"\u26a0\ufe0f  Could not save credentials: {e}\\\")\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(\\n        description=\\\"Set up Langflow load test environment with real starter project flows\\\",\\n        formatter_class=argparse.RawDescriptionHelpFormatter,\\n        epilog=\\\"\\\"\\\"\\nExamples:\\n  # Interactive flow selection\\n  python setup_langflow_test.py --interactive\\n\\n  # Use specific flow\\n  python setup_langflow_test.py --flow \\\"Memory Chatbot\\\"\\n\\n  # List available flows\\n  python setup_langflow_test.py --list-flows\\n\\n  # Setup with custom host\\n  python setup_langflow_test.py --host http://localhost:8000 --interactive\\n\\n  # Save credentials to file\\n  python setup_langflow_test.py --interactive --save-credentials test_creds.json\\n        \\\"\\\"\\\",\\n    )\\n\\n    parser.add_argument(\\n        \\\"--host\\\",\\n        default=\\\"http://localhost:7860\\\",\\n        help=\\\"Langflow host URL (default: http://localhost:7860, use https:// for remote instances)\\\",\\n    )\\n    parser.add_argument(\\\"--flow\\\", help=\\\"Name of the starter project flow to use\\\")\\n    parser.add_argument(\\\"--interactive\\\", action=\\\"store_true\\\", help=\\\"Interactive flow selection\\\")\\n    parser.add_argument(\\\"--list-flows\\\", action=\\\"store_true\\\", help=\\\"List available starter project flows and exit\\\")\\n    parser.add_argument(\\\"--save-credentials\\\", metavar=\\\"FILE\\\", help=\\\"Save credentials to a JSON file\\\")\\n\\n    args = parser.parse_args()\\n\\n    # List flows and exit\\n    if args.list_flows:\\n\\n        async def list_flows_only():\\n            try:\\n                import httpx\\n            except ImportError:\\n                print(\\\"\u274c Missing dependency: httpx\\\")\\n                print(\\\"Install with: pip install httpx\\\")\\n                sys.exit(1)\\n\\n            async with httpx.AsyncClient(base_url=args.host, timeout=30.0) as client:\\n                # Health check\\n                try:\\n                    health_response = await client.get(\\\"/health\\\")\\n                    if health_response.status_code != 200:\\n                        raise Exception(f\\\"Langflow not available at {args.host}\\\")\\n                except Exception as e:\\n                    print(f\\\"\u274c Cannot connect to Langflow at {args.host}: {e}\\\")\\n                    sys.exit(1)\\n\\n                # Authenticate to get access token\\n                try:\\n                    access_token, _, _ = await authenticate_setup_client(client)\\n\\n                except Exception as e:\\n                    print(f\\\"\u274c Authentication failed: {e}\\\")\\n                    print(\\n                        \\\"Set LANGFLOW_SUPERUSER_PASSWORD and optionally LANGFLOW_SUPERUSER, or enable LANGFLOW_AUTO_LOGIN.\\\"\\n                    )\\n                    sys.exit(1)\\n\\n                # Get flows from API\\n                flows = await list_available_flows(args.host, access_token)\\n                if not flows:\\n                    print(\\\"\u274c No starter project flows found!\\\")\\n                    sys.exit(1)\\n\\n                print(f\\\"\\\\n{'=' * 80}\\\")\\n                print(\\\"AVAILABLE STARTER PROJECT FLOWS\\\")\\n                print(f\\\"{'=' * 80}\\\")\\n\\n                for flow_name, name, description in flows:\\n                    print(f\\\"\ud83d\udcc4 {name}\\\")\\n                    print(f\\\"   Description: {description}\\\")\\n                    print()\\n\\n                print(f\\\"Total: {len(flows)} flows available\\\")\\n\\n        asyncio.run(list_flows_only())\\n        sys.exit(0)\\n\\n    # Validate arguments\\n    if not args.interactive and not args.flow:\\n        print(\\\"\u274c Either --interactive or --flow must be specified\\\")\\n        print(\\\"Use --help for more information\\\")\\n        sys.exit(1)\\n\\n    try:\\n        # Run the setup\\n        setup_state = asyncio.run(\\n            setup_langflow_environment(host=args.host, flow_name=args.flow, interactive=args.interactive)\\n        )\\n\\n        # Print results\\n        print_setup_results(setup_state)\\n\\n        # Save credentials if requested\\n        if args.save_credentials:\\n            save_credentials(setup_state, args.save_credentials)\\n\\n        print(\\\"\\\\n\ud83d\ude80 Environment setup complete! You can now run load tests.\\\")\\n\\n    except KeyboardInterrupt:\\n        print(\\\"\\\\n\\\\n\u26a0\ufe0f  Setup cancelled by user\\\")\\n        sys.exit(1)\\n    except Exception as e:\\n        print(f\\\"\\\\n\u274c Setup failed: {e}\\\")\\n        sys.exit(1)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/performance/test_flow_authz_prefilter_benchmark.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"71e69afb7f4f5483b76f7d1ff48c1f66b72f5cba3f60b563518fa1359942dc84\",\"content\":\"\\\"\\\"\\\"DB-backed 10k-flow regression benchmark for authorization list prefiltering.\\n\\nThis is intentionally a correctness benchmark, not a micro-benchmark contest:\\nthe SQL path is compared with a frozen broad-fetch/in-memory oracle and uses a\\ngenerous wall-clock ceiling so slower CI hosts do not flap.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom statistics import median\\nfrom time import perf_counter\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom langflow.services.authorization.listing import (\\n    resource_visible_in_scope,\\n    restrict_to_owned_or_visible_scope,\\n)\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom lfx.services.authorization.base import ResourceVisibilityScope\\nfrom sqlalchemy import case, func\\nfrom sqlmodel import Session, col, create_engine, select\\n\\nFLOW_COUNT = 10_000\\nPAGE_OFFSET = 25\\nPAGE_SIZE = 50\\n\\n\\ndef _elapsed(callable_):\\n    started = perf_counter()\\n    result = callable_()\\n    return perf_counter() - started, result\\n\\n\\n@pytest.mark.benchmark\\ndef test_flow_list_prefilter_matches_in_memory_oracle_at_ten_thousand_rows(tmp_path, record_property):\\n    \\\"\\\"\\\"SQL authorization runs before count/pagination and avoids broad materialization.\\\"\\\"\\\"\\n    owner_id = uuid4()\\n    other_user_id = uuid4()\\n    visible_workspace_id = uuid4()\\n    hidden_workspace_id = uuid4()\\n    visible_project_id = uuid4()\\n    visible_workspace_project_id = uuid4()\\n    hidden_project_id = uuid4()\\n    explicit_indexes = frozenset({3, 5, 7})\\n\\n    rows: list[dict[str, object]] = []\\n    explicit_ids: list[UUID] = []\\n    for index in range(FLOW_COUNT):\\n        flow_id = uuid4()\\n        if index in explicit_indexes:\\n            explicit_ids.append(flow_id)\\n        project_id = (\\n            visible_project_id\\n            if index % 80 == 2\\n            else visible_workspace_project_id\\n            if index % 50 == 1\\n            else hidden_project_id\\n        )\\n        rows.append(\\n            {\\n                \\\"id\\\": flow_id,\\n                \\\"name\\\": f\\\"flow-{index:05d}\\\",\\n                \\\"user_id\\\": owner_id if index % 100 == 0 else other_user_id,\\n                # Deliberately wrong for workspace-visible project rows: the\\n                # benchmark oracle must use Folder.workspace_id, not this\\n                # denormalized value.\\n                \\\"workspace_id\\\": hidden_workspace_id,\\n                \\\"folder_id\\\": project_id,\\n            }\\n        )\\n\\n    visibility = ResourceVisibilityScope(\\n        resource_ids=tuple(explicit_ids),\\n        workspace_ids=(visible_workspace_id,),\\n        project_ids=(visible_project_id,),\\n    )\\n    engine = create_engine(f\\\"sqlite:///{tmp_path / 'flow-prefilter.db'}\\\")\\n    Folder.__table__.create(engine)\\n    Flow.__table__.create(engine)\\n\\n    with engine.begin() as connection:\\n        connection.execute(\\n            Folder.__table__.insert(),\\n            [\\n                {\\\"id\\\": visible_project_id, \\\"name\\\": \\\"visible-project\\\", \\\"workspace_id\\\": hidden_workspace_id},\\n                {\\n                    \\\"id\\\": visible_workspace_project_id,\\n                    \\\"name\\\": \\\"visible-workspace-project\\\",\\n                    \\\"workspace_id\\\": visible_workspace_id,\\n                },\\n                {\\\"id\\\": hidden_project_id, \\\"name\\\": \\\"hidden-project\\\", \\\"workspace_id\\\": hidden_workspace_id},\\n            ],\\n        )\\n        connection.execute(Flow.__table__.insert(), rows)\\n\\n    with Session(engine) as session:\\n        # Frozen reference for the former shape: materialize every row, then\\n        # apply the owner override and structured visibility in Python.\\n        broad_seconds, broad_rows = _elapsed(lambda: session.exec(select(Flow)).all())\\n        oracle = [\\n            flow\\n            for flow in broad_rows\\n            if flow.user_id == owner_id\\n            or resource_visible_in_scope(\\n                resource_id=flow.id,\\n                workspace_id={\\n                    visible_project_id: hidden_workspace_id,\\n                    visible_workspace_project_id: visible_workspace_id,\\n                    hidden_project_id: hidden_workspace_id,\\n                }[flow.folder_id],\\n                project_id=flow.folder_id,\\n                visibility=visibility,\\n            )\\n        ]\\n\\n        filtered_stmt = restrict_to_owned_or_visible_scope(\\n            select(Flow).outerjoin(Folder, Folder.id == Flow.folder_id),\\n            id_column=Flow.id,\\n            owner_clause=Flow.user_id == owner_id,\\n            workspace_expression=case(\\n                (col(Flow.folder_id).is_not(None), Folder.workspace_id),\\n                else_=Flow.workspace_id,\\n            ),\\n            project_column=Flow.folder_id,\\n            visibility=visibility,\\n        )\\n        sql_timings: list[float] = []\\n        sql_rows = []\\n        for _ in range(3):\\n            elapsed, sql_rows = _elapsed(lambda: session.exec(filtered_stmt).all())\\n            sql_timings.append(elapsed)\\n\\n        sql_count = session.exec(select(func.count()).select_from(filtered_stmt.subquery())).one()\\n        ordered_stmt = filtered_stmt.order_by(Flow.name, Flow.id)\\n        sql_page = session.exec(ordered_stmt.offset(PAGE_OFFSET).limit(PAGE_SIZE)).all()\\n        oracle_page = sorted(oracle, key=lambda flow: (flow.name, flow.id))[PAGE_OFFSET : PAGE_OFFSET + PAGE_SIZE]\\n\\n    oracle_ids = {flow.id for flow in oracle}\\n    sql_ids = {flow.id for flow in sql_rows}\\n    assert sql_ids == oracle_ids\\n    assert sql_count == len(oracle)\\n    assert len(sql_rows) == len(oracle)\\n    assert [flow.id for flow in sql_page] == [flow.id for flow in oracle_page]\\n    assert len(broad_rows) == FLOW_COUNT\\n    assert len(sql_rows) < FLOW_COUNT // 10, \\\"prefilter should materialize only the authorized working set\\\"\\n\\n    median_sql_seconds = median(sql_timings)\\n    record_property(\\\"broad_fetch_seconds\\\", broad_seconds)\\n    record_property(\\\"sql_prefilter_median_seconds\\\", median_sql_seconds)\\n    record_property(\\\"broad_rows_materialized\\\", len(broad_rows))\\n    record_property(\\\"prefilter_rows_materialized\\\", len(sql_rows))\\n    assert median_sql_seconds < 2.0\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/api/test_flow_extraction.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"04512a3e465c512d8f5f7066c50088fdd4892c91e515f0452e3c1c0ec62a2a00\",\"content\":\"\\\"\\\"\\\"Tests for flow JSON extraction from markdown responses.\\\"\\\"\\\"\\n\\nimport json\\n\\nfrom langflow.agentic.helpers.code_extraction import extract_flow_json\\n\\n\\nclass TestExtractFlowJson:\\n    def test_extracts_flow_json_block(self):\\n        flow_data = {\\\"name\\\": \\\"Test\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n        text = f\\\"Here's the flow:\\\\n\\\\n```flow_json\\\\n{json.dumps(flow_data)}\\\\n```\\\\n\\\\nDone!\\\"\\n        result = extract_flow_json(text)\\n        assert result == flow_data\\n\\n    def test_returns_none_when_no_flow_block(self):\\n        text = \\\"Just a regular response with no flow data.\\\"\\n        assert extract_flow_json(text) is None\\n\\n    def test_returns_none_for_invalid_json(self):\\n        text = \\\"```flow_json\\\\n{invalid json}\\\\n```\\\"\\n        assert extract_flow_json(text) is None\\n\\n    def test_returns_none_for_python_code_block(self):\\n        text = \\\"```python\\\\nclass MyComponent(Component): pass\\\\n```\\\"\\n        assert extract_flow_json(text) is None\\n\\n    def test_extracts_from_mixed_content(self):\\n        flow_data = {\\\"name\\\": \\\"RAG\\\", \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"1\\\"}], \\\"edges\\\": []}}\\n        text = (\\n            \\\"I built a RAG pipeline for you.\\\\n\\\\n\\\"\\n            \\\"```python\\\\nprint('hello')\\\\n```\\\\n\\\\n\\\"\\n            f\\\"```flow_json\\\\n{json.dumps(flow_data)}\\\\n```\\\\n\\\\n\\\"\\n            \\\"Let me know if you need changes.\\\"\\n        )\\n        result = extract_flow_json(text)\\n        assert result == flow_data\\n\\n    def test_handles_pretty_printed_json(self):\\n        flow_data = {\\\"name\\\": \\\"Test\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n        pretty = json.dumps(flow_data, indent=2)\\n        text = f\\\"```flow_json\\\\n{pretty}\\\\n```\\\"\\n        result = extract_flow_json(text)\\n        assert result == flow_data\\n\\n    def test_case_insensitive(self):\\n        flow_data = {\\\"name\\\": \\\"Test\\\"}\\n        text = f\\\"```FLOW_JSON\\\\n{json.dumps(flow_data)}\\\\n```\\\"\\n        result = extract_flow_json(text)\\n        assert result == flow_data\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/flows/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f9e404ef5026ef7ffbc232445c6489826546a97d6e39c1fee77c68969beb7542\",\"content\":\"\\\"\\\"\\\"Tests for agentic flows.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/flows/test_agentic_model_config.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d88e408d8ab6b5000851d66db8f31ba110ebfd43c0240289ac7b59347515dc7c\",\"content\":\"\\\"\\\"\\\"Bug #1 (PR-12575): Gemini died with \\\"Unknown model class: ChatGoogleGenerativeAI\\\".\\n\\nThe agentic ``build_model_config`` hardcoded model-class names in a dict that\\ndrifted from the central model registry: Google Generative AI mapped to\\n``ChatGoogleGenerativeAI``, but the registry only knows\\n``ChatGoogleGenerativeAIFixed`` \u2014 so selecting any Gemini model and sending a\\nprompt died at the run with ``ValueError: Unknown model class:\\nChatGoogleGenerativeAI``. Groq / Azure OpenAI were latent variants of the same\\ngap (their class names were absent from the registry entirely).\\n\\nThese tests assert the EXACT failing contract: the model class\\n``build_model_config`` emits must be one the central registry can resolve.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom langflow.agentic.flows.model_config import build_model_config\\nfrom lfx.base.models.unified_models.class_registry import get_model_class\\n\\n\\ndef _model_class_is_resolvable(class_name: str) -> None:\\n    \\\"\\\"\\\"Fail only on the bug's exact error \u2014 ValueError('Unknown model class').\\n\\n    A missing optional provider package raises ImportError (with an install\\n    hint), which is a different, acceptable failure mode \u2014 not the registry gap\\n    this bug is about.\\n    \\\"\\\"\\\"\\n    try:\\n        get_model_class(class_name)\\n    except ValueError as exc:  # the exact bug: \\\"Unknown model class: ...\\\"\\n        pytest.fail(f\\\"model class not registered: {exc}\\\")\\n    except ImportError:\\n        pass\\n\\n\\nclass TestBuildModelConfigUsesRegisteredClassNames:\\n    def test_should_use_registered_class_when_provider_is_google(self):\\n        config = build_model_config(\\\"Google Generative AI\\\", \\\"gemini-2.5-pro\\\")\\n        # The stale alias \\\"ChatGoogleGenerativeAI\\\" is what broke Gemini.\\n        assert config[0][\\\"metadata\\\"][\\\"model_class\\\"] == \\\"ChatGoogleGenerativeAIFixed\\\"\\n\\n    def test_should_emit_a_resolvable_class_when_provider_is_google(self):\\n        # Exact error path: the run resolved the class via get_model_class,\\n        # which raised \\\"Unknown model class: ChatGoogleGenerativeAI\\\".\\n        config = build_model_config(\\\"Google Generative AI\\\", \\\"gemini-2.5-pro\\\")\\n        _model_class_is_resolvable(config[0][\\\"metadata\\\"][\\\"model_class\\\"])\\n\\n    @pytest.mark.parametrize(\\n        (\\\"provider\\\", \\\"expected\\\"),\\n        [(\\\"OpenAI\\\", \\\"ChatOpenAI\\\"), (\\\"Anthropic\\\", \\\"ChatAnthropic\\\")],\\n    )\\n    def test_should_keep_openai_and_anthropic_class_names(self, provider, expected):\\n        assert build_model_config(provider, \\\"m\\\")[0][\\\"metadata\\\"][\\\"model_class\\\"] == expected\\n\\n\\nclass TestBuildModelConfigUsesCorrectModelParamName:\\n    \\\"\\\"\\\"WatsonX died with 400 \\\"model <id> not found\\\" (GitHub #13735 follow-up).\\n\\n    ``build_model_config`` read the non-existent key ``model_name_param`` from\\n    ``get_provider_param_mapping`` (which only emits ``model_param``), so it fell\\n    back to \\\"model\\\" for every provider and explicitly set metadata[\\\"model_name_param\\\"]=\\\"model\\\".\\n    That truthy value defeats the #13684 fallback in get_llm, so for WatsonX it passes\\n    ``model=`` instead of ``model_id=`` \u2014 routing ChatWatsonx through the OpenAI-compatible\\n    AI Gateway (400 \\\"model not found\\\") instead of native ModelInference. OpenAI/Anthropic\\n    were unaffected because their ``model_param`` is already \\\"model\\\".\\n    \\\"\\\"\\\"\\n\\n    def test_should_use_model_id_param_when_provider_is_watsonx(self):\\n        config = build_model_config(\\\"IBM WatsonX\\\", \\\"mistral-large-2512\\\")\\n        assert config[0][\\\"metadata\\\"][\\\"model_name_param\\\"] == \\\"model_id\\\"\\n\\n    @pytest.mark.parametrize(\\\"provider\\\", [\\\"OpenAI\\\", \\\"Anthropic\\\"])\\n    def test_should_keep_model_param_for_openai_and_anthropic(self, provider):\\n        assert build_model_config(provider, \\\"m\\\")[0][\\\"metadata\\\"][\\\"model_name_param\\\"] == \\\"model\\\"\\n\\n\\nclass TestRegistryKnowsGroqAndAzure:\\n    \\\"\\\"\\\"Latent variant of Bug #1 \u2014 Groq / Azure class names must be registered.\\n\\n    Their class names were missing from the registry entirely, so selecting\\n    either provider raised \\\"Unknown model class\\\" the same way Gemini did.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\\"class_name\\\", [\\\"ChatGroq\\\", \\\"AzureChatOpenAI\\\"])\\n    def test_should_resolve_groq_and_azure_without_unknown_class_error(self, class_name):\\n        _model_class_is_resolvable(class_name)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/flows/test_assistant_agent_iteration_budget.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f3e5834ec9e8094fdedad1638c79853231e03559bae7b9c344b77ffe2c0311af\",\"content\":\"\\\"\\\"\\\"Pin the assistant agent iteration budget -- a COST decision, not a tuning knob.\\n\\nDecision (2026-07-09, user): the assistant agents' LangGraph budget is pinned at\\n``max_iterations = 30`` (recursion limit = 30*2+5 = 65), raised from the original\\ncomponent default of 15. Rationale: compound one-turn tasks (\\\"create a component,\\nbuild a flow with it, run it, and report\\\") legitimately need more than 15 steps and\\nwere dying with ``Recursion limit of 35 reached``. The trade-off -- a higher worst-case\\ntoken spend per attempt on hosted models -- was accepted deliberately, and a per-session\\n``/iterations N`` command lets a user tune it further (1-200) without editing the flows.\\n\\nThis test is a tripwire: any future change to the pinned budget must be a conscious\\ndecision that also updates ``ASSISTANT_ITERATION_BUDGET`` here.\\n\\nLE-2324 (2026-08-27): the pin is now the FALLBACK, not the ceiling. An operator sets\\n``LANGFLOW_ASSISTANT_ITERATIONS`` to move the default for a whole deployment, because\\n``/iterations N`` only tunes one browser session. The tripwire still guards the shipped\\ndefault, which is what a user gets out of the box.\\n\\\"\\\"\\\"\\n\\nimport json\\nfrom pathlib import Path\\n\\nFLOW_PATH = Path(__file__).parents[4] / \\\"base\\\" / \\\"langflow\\\" / \\\"agentic\\\" / \\\"flows\\\" / \\\"LangflowAssistant.json\\\"\\nPY_FLOW_PATH = Path(__file__).parents[4] / \\\"base\\\" / \\\"langflow\\\" / \\\"agentic\\\" / \\\"flows\\\" / \\\"flow_builder_assistant.py\\\"\\n\\nASSISTANT_ITERATION_BUDGET = 30\\n\\n\\ndef test_should_pin_json_agents_at_the_assistant_budget():\\n    data = json.loads(FLOW_PATH.read_text(encoding=\\\"utf-8\\\"))\\n    agents = [n[\\\"data\\\"] for n in data[\\\"data\\\"][\\\"nodes\\\"] if n.get(\\\"data\\\", {}).get(\\\"type\\\") == \\\"Agent\\\"]\\n\\n    assert agents, \\\"LangflowAssistant.json must contain Agent nodes\\\"\\n    for agent in agents:\\n        configured = agent[\\\"node\\\"][\\\"template\\\"][\\\"max_iterations\\\"][\\\"value\\\"]\\n        assert configured == ASSISTANT_ITERATION_BUDGET, (\\n            f\\\"Agent {agent.get('id')} has max_iterations={configured}, expected \\\"\\n            f\\\"{ASSISTANT_ITERATION_BUDGET}; changing the pinned budget is a cost decision -- \\\"\\n            \\\"update ASSISTANT_ITERATION_BUDGET and see the docstring\\\"\\n        )\\n\\n\\ndef test_builder_budget_comes_from_the_shared_constant():\\n    \\\"\\\"\\\"The builder's budget is get_graph(iterations_limit) + the shared default.\\n\\n    The Python builder flow never passes through inject_iterations_into_flow (that\\n    only rewrites JSON templates), so its budget arrives via get_graph and defaults\\n    to DEFAULT_ASSISTANT_ITERATIONS -- one source of truth, no numeric hardcode.\\n    \\\"\\\"\\\"\\n    import re\\n\\n    from langflow.agentic.services.flow_preparation import DEFAULT_ASSISTANT_ITERATIONS\\n\\n    assert DEFAULT_ASSISTANT_ITERATIONS == ASSISTANT_ITERATION_BUDGET, (\\n        \\\"the shared default drifted from the pinned cost decision -- \\\"\\n        \\\"update ASSISTANT_ITERATION_BUDGET and see the docstring\\\"\\n    )\\n    source = PY_FLOW_PATH.read_text(encoding=\\\"utf-8\\\")\\n    assert \\\"assistant_iterations_default\\\" in source, (\\n        \\\"flow_builder_assistant.py must default its Agent budget to the shared resolver \\\"\\n        \\\"(LANGFLOW_ASSISTANT_ITERATIONS, falling back to DEFAULT_ASSISTANT_ITERATIONS)\\\"\\n    )\\n    assert not re.search(r\\\"max_iterations\\\\D{0,20}\\\\d\\\", source), (\\n        \\\"flow_builder_assistant.py must not hardcode a numeric max_iterations -- \\\"\\n        \\\"the budget is DEFAULT_ASSISTANT_ITERATIONS plus the runtime iterations_limit override\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/flows/test_component_code_search_tool.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"376a5b0dd1a3097f8ff33f9e0d98d85e5ff3254a2068b47e6e6b5c5874942d40\",\"content\":\"\\\"\\\"\\\"GH #13618 \u2014 component_code_search tool silently reports an empty library.\\n\\nThe inline ``DataFrameKeywordSearch`` component in ``LangflowAssistant.json``\\ncombines three defects into a confidently wrong \\\"the component library is\\nempty\\\" answer:\\n\\n1. An unknown ``column`` returns an empty DataFrame instead of raising, so\\n   the agent cannot self-correct (the DataFrame has only ``file_path`` and\\n   ``text`` columns, but the model guesses ``name``/``code``).\\n2. The ``column`` tool arg never documents the valid column names.\\n3. ``number_candidates`` ships as 2, making enumeration questions\\n   unanswerable over a ~500-file index with no truncation signal.\\n\\nThese tests load the REAL inline code from the flow JSON (the same loader\\npath production uses) and pin the corrected behavior.\\n\\\"\\\"\\\"\\n\\nimport json\\nfrom pathlib import Path\\n\\nimport pandas as pd\\nimport pytest\\nfrom langflow.schema import DataFrame\\nfrom lfx.custom.eval import eval_custom_component_code\\n\\nFLOW_PATH = Path(__file__).parents[4] / \\\"base\\\" / \\\"langflow\\\" / \\\"agentic\\\" / \\\"flows\\\" / \\\"LangflowAssistant.json\\\"\\n\\nMIN_ENUMERATION_CANDIDATES = 10\\n\\n\\ndef _keyword_search_template() -> dict:\\n    data = json.loads(FLOW_PATH.read_text(encoding=\\\"utf-8\\\"))\\n    for node in data[\\\"data\\\"][\\\"nodes\\\"]:\\n        node_data = node.get(\\\"data\\\", {})\\n        if node_data.get(\\\"type\\\") == \\\"DataFrameKeywordSearch\\\":\\n            return node_data[\\\"node\\\"][\\\"template\\\"]\\n    msg = \\\"DataFrameKeywordSearch node not found in LangflowAssistant.json\\\"\\n    raise AssertionError(msg)\\n\\n\\ndef _component_instance():\\n    component_class = eval_custom_component_code(_keyword_search_template()[\\\"code\\\"][\\\"value\\\"])\\n    instance = component_class()\\n    instance.dataframe = DataFrame(\\n        pd.DataFrame(\\n            [\\n                {\\\"file_path\\\": \\\"openai.py\\\", \\\"text\\\": \\\"class OpenAIModel(Component): build()...\\\"},\\n                {\\\"file_path\\\": \\\"chat_input.py\\\", \\\"text\\\": \\\"class ChatInput(Component): build()...\\\"},\\n                {\\\"file_path\\\": \\\"agent.py\\\", \\\"text\\\": \\\"class Agent(Component): tools...\\\"},\\n            ]\\n        )\\n    )\\n    instance.match_type = \\\"any\\\"\\n    instance.case_sensitive = False\\n    instance.number_candidates = 10\\n    return instance\\n\\n\\nclass TestInvalidColumnHandling:\\n    @pytest.mark.parametrize(\\\"invalid_column\\\", [\\\"name\\\", \\\"code\\\"])\\n    def test_should_raise_value_error_when_column_does_not_exist(self, invalid_column):\\n        instance = _component_instance()\\n        instance.column = invalid_column\\n        instance.keywords = [\\\"component\\\"]\\n\\n        with pytest.raises(ValueError, match=\\\"file_path\\\") as exc_info:\\n            instance.search()\\n\\n        assert invalid_column in str(exc_info.value)\\n\\n    def test_should_return_matches_when_searching_valid_text_column(self):\\n        instance = _component_instance()\\n        instance.column = \\\"text\\\"\\n        instance.keywords = [\\\"class\\\", \\\"Component\\\"]\\n\\n        result = instance.search()\\n\\n        assert len(result) > 0\\n\\n\\nclass TestToolArgDocumentation:\\n    def test_should_document_valid_columns_in_column_tool_arg_info(self):\\n        template = _keyword_search_template()\\n        info = template[\\\"column\\\"][\\\"info\\\"]\\n\\n        assert \\\"file_path\\\" in info, f\\\"Tool arg info must name the valid columns, got: {info!r}\\\"\\n        assert \\\"text\\\" in info, f\\\"Tool arg info must name the valid columns, got: {info!r}\\\"\\n\\n\\nclass TestEnumerationCandidateCap:\\n    def test_should_ship_an_enumeration_friendly_candidate_cap(self):\\n        template = _keyword_search_template()\\n        configured = template[\\\"number_candidates\\\"][\\\"value\\\"]\\n\\n        assert configured >= MIN_ENUMERATION_CANDIDATES, (\\n            f\\\"number_candidates={configured} cannot answer enumeration questions over ~500 indexed files\\\"\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/flows/test_component_generator_tool_prompt.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d346bb7e44434f49dcc542702348809f045158e93bb33a55e357980fbff8e065\",\"content\":\"\\\"\\\"\\\"Regression guard for the component-generator agent's system prompt.\\n\\nThe component generator (the inner ``LangflowAssistant.json`` Agent that\\nproduces a single ``class MyComponent(Component): ...`` snippet) is the\\nONLY place that teaches the LLM how to write tool-friendly components.\\nIf the tool-compatibility section silently drops out, every component\\ngenerated for an agent regresses to the production failure observed\\n2026-05-27: the assistant generates a method like ``output()`` or\\n``process()``, the agent receives a tool with that uninformative name,\\nand the LLM never calls it.\\n\\nThese tests assert the SPECIFIC instructions are present so prompt\\nedits can't quietly undo the guidance. Behavior of the runtime fallback\\n(``_class_name_to_tool_name`` in ``component_tool.py``) is covered by\\nits own unit tests; this file only covers the prompt content.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom pathlib import Path\\n\\nimport pytest\\n\\nLANGFLOW_ASSISTANT_JSON = (\\n    Path(__file__).resolve().parent.parent.parent.parent.parent\\n    / \\\"base\\\"\\n    / \\\"langflow\\\"\\n    / \\\"agentic\\\"\\n    / \\\"flows\\\"\\n    / \\\"LangflowAssistant.json\\\"\\n)\\n# The COMPONENT GENERATOR agent (the inner one whose prompt embeds the\\n# Langflow Component API Reference). The PARENT agent has a different id\\n# and is covered by test_langflow_assistant_prompt.py.\\nCOMPONENT_GENERATOR_AGENT_MARKER = \\\"Langflow Component API Reference\\\"\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef generator_prompt() -> str:\\n    flow = json.loads(LANGFLOW_ASSISTANT_JSON.read_text(encoding=\\\"utf-8\\\"))\\n    for node in flow[\\\"data\\\"][\\\"nodes\\\"]:\\n        node_data = node.get(\\\"data\\\", {})\\n        if node_data.get(\\\"type\\\") != \\\"Agent\\\":\\n            continue\\n        sp = node_data.get(\\\"node\\\", {}).get(\\\"template\\\", {}).get(\\\"system_prompt\\\", {})\\n        if not isinstance(sp, dict):\\n            continue\\n        val = sp.get(\\\"value\\\", \\\"\\\") or \\\"\\\"\\n        if COMPONENT_GENERATOR_AGENT_MARKER in val:\\n            return val\\n    msg = \\\"Component generator agent (the one carrying the API Reference) not found in LangflowAssistant.json\\\"\\n    raise AssertionError(msg)\\n\\n\\nclass TestAgentToolCompatibilitySection:\\n    \\\"\\\"\\\"Prompt covers the three traits that make a generated component agent-callable.\\n\\n    Meaningful method name, descriptive ``description``, and explicit\\n    ``tool_mode=True`` on LLM-passed inputs.\\n    \\\"\\\"\\\"\\n\\n    def test_section_is_present(self, generator_prompt: str):\\n        assert \\\"Agent Tool Compatibility\\\" in generator_prompt, (\\n            \\\"The 'Agent Tool Compatibility' section must remain in the generator prompt \u2014 \\\"\\n            \\\"removing it regresses the production failure where the agent could not call the \\\"\\n            \\\"generated tool (method name was 'output'/'process').\\\"\\n        )\\n\\n    def test_warns_against_generic_method_names(self, generator_prompt: str):\\n        # Every generic name we ALSO catch at runtime in\\n        # _GENERIC_OUTPUT_METHOD_NAMES must be called out in the prompt.\\n        # If the prompt drops one, the LLM regresses to using it.\\n        for bad_name in (\\\"output\\\", \\\"process\\\", \\\"build_output\\\", \\\"run\\\", \\\"execute\\\"):\\n            assert bad_name in generator_prompt, f\\\"Prompt must explicitly call out generic method name {bad_name!r}\\\"\\n\\n    def test_shows_a_good_method_name_example(self, generator_prompt: str):\\n        # Concrete examples beat abstract advice for LLMs. The prompt must\\n        # show at least one action-verb-noun pattern so the LLM has a\\n        # template to copy.\\n        assert \\\"get_random_menu_item\\\" in generator_prompt or \\\"fetch_weather\\\" in generator_prompt, (\\n            \\\"Prompt must include at least one action-verb-noun example tool name; without a \\\"\\n            \\\"concrete pattern, the LLM regresses to generic names.\\\"\\n        )\\n\\n    def test_explains_description_is_the_tool_description(self, generator_prompt: str):\\n        # The component `description` doubles as the LLM-facing tool\\n        # description. The prompt must spell this out \u2014 otherwise the LLM\\n        # writes a one-liner like \\\"Returns an item.\\\" and the agent never\\n        # knows when to call it.\\n        prompt_lower = generator_prompt.lower()\\n        assert \\\"is the tool description\\\" in prompt_lower or \\\"tool description\\\" in prompt_lower, (\\n            \\\"Prompt must state that the component `description` IS the LLM-facing tool description.\\\"\\n        )\\n\\n    def test_explains_tool_mode_input_marker(self, generator_prompt: str):\\n        # `tool_mode=True` on inputs is what restricts the LLM-facing tool\\n        # schema to the arguments the agent should provide. Without it,\\n        # ALL component inputs (including API keys) end up in the schema \u2014\\n        # the LLM gets confused and hallucinates values.\\n        assert \\\"tool_mode=True\\\" in generator_prompt, \\\"Prompt must mention `tool_mode=True` on inputs\\\"\\n\\n    def test_includes_a_quick_checklist(self, generator_prompt: str):\\n        # A bulleted pre-emission checklist is the single most effective\\n        # nudge for LLMs in our prompt evals \u2014 keep it.\\n        assert \\\"checklist\\\" in generator_prompt.lower(), (\\n            \\\"Prompt must include a pre-emission checklist so the LLM self-verifies before emitting code.\\\"\\n        )\\n\\n    def test_forbids_reserved_output_name(self, generator_prompt: str):\\n        # The production failure that motivated the runtime defensive fix:\\n        # the LLM declared `Output(name=\\\"component_as_tool\\\", ...)`, which\\n        # collides with the synthetic sentinel and silently drops the\\n        # tool. The prompt MUST teach the LLM never to use this name.\\n        assert \\\"component_as_tool\\\" in generator_prompt, (\\n            \\\"Prompt must explicitly forbid the reserved output name `component_as_tool`.\\\"\\n        )\\n        assert \\\"reserved\\\" in generator_prompt.lower(), (\\n            \\\"Prompt must call the name `reserved` so the LLM understands the rule's force.\\\"\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/flows/test_flow_builder_assistant.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0b59ca93ac9dbd1cb600a7b0b343ea4ade16f944d3f99e18d8d72185ee8caa91\",\"content\":\"\\\"\\\"\\\"Integration tests for the flow builder assistant.\\n\\nTests intent classification for build_flow requests and the\\nflow builder assistant graph construction.\\n\\nTests marked with requires_api_key are skipped in CI unless\\nOPENAI_API_KEY is set.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom langflow.agentic.flows.flow_builder_assistant import FLOW_BUILDER_PROMPT, get_graph\\nfrom langflow.agentic.flows.translation_flow import TRANSLATION_PROMPT\\n\\nfrom tests.api_keys import has_api_key\\n\\n\\nclass TestFlowBuilderPrompt:\\n    def test_should_use_declared_configuration_constraints(self):\\n        assert \\\"exact, case-sensitive values\\\" in FLOW_BUILDER_PROMPT\\n        assert \\\"`combobox` allows free-text\\\" in FLOW_BUILDER_PROMPT\\n        assert \\\"within `range_spec` bounds\\\" in FLOW_BUILDER_PROMPT\\n        assert \\\"does not apply any of its parameter changes\\\" in FLOW_BUILDER_PROMPT\\n\\n    def test_should_mention_search_components_tool(self):\\n        assert \\\"search_components\\\" in FLOW_BUILDER_PROMPT\\n\\n    def test_should_mention_describe_component_tool(self):\\n        assert \\\"describe_component\\\" in FLOW_BUILDER_PROMPT\\n\\n    def test_should_mention_build_flow_tool(self):\\n        assert \\\"build_flow\\\" in FLOW_BUILDER_PROMPT\\n\\n    def test_should_mention_build_flow_for_new_flows(self):\\n        assert \\\"build_flow\\\" in FLOW_BUILDER_PROMPT\\n        assert \\\"spec\\\" in FLOW_BUILDER_PROMPT\\n\\n    def test_should_instruct_retry_on_failure(self):\\n        assert \\\"retry\\\" in FLOW_BUILDER_PROMPT.lower() or \\\"fix\\\" in FLOW_BUILDER_PROMPT.lower()\\n\\n    def test_should_instruct_search_before_building(self):\\n        assert \\\"search\\\" in FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"describe\\\" in FLOW_BUILDER_PROMPT.lower()\\n\\n    # Regression guards for wiring mistakes seen in production builds where\\n    # the agent left orphan model components, mis-wired memory to Tools, and\\n    # produced agents with empty system prompts.\\n    def test_should_forbid_orphan_components(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"orphan\\\" in prompt_lower or \\\"every component\\\" in prompt_lower, (\\n            \\\"Prompt must instruct the agent that every added component must be connected.\\\"\\n        )\\n\\n    def test_should_explain_tools_input_only_takes_tool_outputs(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"component_as_tool\\\" in prompt_lower, (\\n            \\\"Prompt must clarify that the Tools input requires `component_as_tool` outputs.\\\"\\n        )\\n\\n    def test_should_warn_about_agents_built_in_model(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"built-in model\\\" in prompt_lower, \\\"Prompt must mention the Agent has a built-in model.\\\"\\n        assert \\\"only\\\" in prompt_lower or \\\"unless\\\" in prompt_lower, (\\n            \\\"Prompt must say external models are opt-in (use 'only' or 'unless').\\\"\\n        )\\n\\n    def test_should_require_system_prompt_for_persona_use_cases(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"system_prompt\\\" in prompt_lower, (\\n            \\\"Prompt must instruct the agent to fill system_prompt for persona use cases.\\\"\\n        )\\n        assert \\\"persona\\\" in prompt_lower, \\\"Prompt must reference the persona use case explicitly.\\\"\\n\\n    def test_should_have_chatbot_or_assistant_example_with_system_prompt(self):\\n        # The example must show both the input wiring AND a populated system prompt.\\n        assert \\\"system_prompt\\\" in FLOW_BUILDER_PROMPT\\n        assert \\\"config:\\\" in FLOW_BUILDER_PROMPT, (\\n            \\\"Prompt examples must show how to set field values via the `config:` block.\\\"\\n        )\\n\\n    def test_should_teach_the_edit_continuation_contract(self):\\n        \\\"\\\"\\\"After an approved edit, the silent continuation turn must make the\\n        agent finish the original request (e.g. run) WITHOUT re-editing or\\n        re-planning. Drift between the protocol string and the prompt's\\n        recognizer phrase would break the whole 'execution stack'.\\n        \\\"\\\"\\\"  # noqa: D205\\n        from langflow.agentic.services.flow_types import EDIT_CONTINUATION_INPUT\\n\\n        # The prompt must quote enough of the protocol string for the agent\\n        # to recognize the signal (cross-consistency with the constant).\\n        recognizer = \\\"The proposed canvas edits were applied. Continue with the remaining steps\\\"\\n        assert recognizer in EDIT_CONTINUATION_INPUT\\n        assert recognizer in FLOW_BUILDER_PROMPT\\n\\n        lower = FLOW_BUILDER_PROMPT.lower()\\n        # It must instruct: don't re-edit / don't propose_plan on continuation.\\n        assert \\\"do not re-propose\\\" in lower or \\\"do not re-apply\\\" in lower\\n        # It must instruct: perform the originally-requested follow-up (run).\\n        assert \\\"run_flow\\\" in FLOW_BUILDER_PROMPT\\n        # It must instruct: brief confirmation + stop when edit was the whole ask.\\n        assert \\\"one-line confirmation\\\" in lower or \\\"confirm\\\" in lower\\n\\n    def test_should_require_a_model_on_any_agent_that_will_run(self):\\n        \\\"\\\"\\\"Production bug: built a flow with an Agent but no model \u2192\\n        run failed \\\"No model selected\\\". The prompt must make configuring\\n        the Agent's model mandatory before running.\\n        \\\"\\\"\\\"  # noqa: D205\\n        lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"no model selected\\\" in lower\\n        assert \\\"available language model\\\" in lower\\n        assert \\\"never run a flow whose agent has no model\\\" in lower\\n\\n    def test_should_run_in_same_turn_after_a_directly_applied_edit(self):\\n        \\\"\\\"\\\"Production bug: for \\\"change X and run\\\", the agent used\\n        configure_component (applies immediately, NO approval gate) but then\\n        deferred the run as if waiting for an approval that never comes.\\n        Only propose_field_edit is man-in-the-loop; direct-apply edit tools\\n        must be followed by run_flow in the SAME turn.\\n        \\\"\\\"\\\"  # noqa: D205\\n        lower = FLOW_BUILDER_PROMPT.lower()\\n        # The prompt must name the immediate-apply tools and tie them to a\\n        # same-turn run when the user also asked to run.\\n        assert \\\"configure_component\\\" in FLOW_BUILDER_PROMPT\\n        assert \\\"same turn\\\" in lower\\n        # It must call out that only propose_field_edit defers (the gate).\\n        assert \\\"propose_field_edit\\\" in FLOW_BUILDER_PROMPT\\n        # It must forbid the \\\"I'll run once the edits are applied\\\" stall for\\n        # the direct path.\\n        assert \\\"nothing to wait for\\\" in lower or \\\"do not defer\\\" in lower\\n\\n    def test_should_resolve_target_component_by_role_not_name(self):\\n        \\\"\\\"\\\"Production bug: \\\"mude o input\\\" \u2192 agent edited a custom tool\\n        component instead of the flow's ChatInput, so the run used the old\\n        value. The prompt must pin \\\"the input\\\" to ChatInput.input_value\\n        (resolved via connections), never a tool/custom component.\\n        \\\"\\\"\\\"  # noqa: D205\\n        lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"targeting the right component\\\" in lower\\n        # Must resolve deterministically via the dedicated tool, not by\\n        # eyeballing connections / matching names.\\n        assert \\\"describe_flow_io\\\" in FLOW_BUILDER_PROMPT\\n        assert \\\"value_field\\\" in FLOW_BUILDER_PROMPT\\n        # A tools-wired / custom component is explicitly NEVER the flow input.\\n        assert \\\"never\\\" in lower\\n        assert \\\"tool\\\" in lower\\n        # Ambiguity (more than one input) must be asked, not guessed.\\n        assert \\\"more than one input\\\" in lower\\n        assert \\\"ask the user\\\" in lower\\n\\n    def test_should_self_verify_run_reflects_the_edit(self):\\n        \\\"\\\"\\\"The agent must detect \\\"edited X but the run still shows the OLD\\n        value\\\" (it targeted the wrong component) and self-correct once,\\n        instead of reporting a contradictory success.\\n        \\\"\\\"\\\"  # noqa: D205\\n        lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"old value\\\" in lower\\n        assert \\\"self-correction\\\" in lower or \\\"run once more\\\" in lower\\n        # Must not present it as success when the change had no effect.\\n        assert \\\"do not report success\\\" in lower or \\\"wrong component\\\" in lower\\n\\n    def test_should_instruct_to_swap_model_via_configure_component(self):\\n        \\\"\\\"\\\"When the user says 'change the model to X', the agent must update\\n        the Agent's `model` field via configure_component instead of adding\\n        an external OpenAIModel/AnthropicModel component.\\n        \\\"\\\"\\\"  # noqa: D205\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        # Must mention the editing path explicitly.\\n        assert \\\"configure_component\\\" in prompt_lower\\n        assert \\\"change the model\\\" in prompt_lower or \\\"switch\\\" in prompt_lower, (\\n            \\\"Prompt must explicitly cover the 'change the model' user request.\\\"\\n        )\\n\\n    def test_should_show_model_field_value_structure(self):\\n        \\\"\\\"\\\"The agent needs the exact JSON shape for the Agent's model field\\n        value so it can call configure_component without guessing.\\n        \\\"\\\"\\\"  # noqa: D205\\n        # The structure is `[{\\\"provider\\\": \\\"...\\\", \\\"name\\\": \\\"...\\\"}]`.\\n        assert '\\\"provider\\\"' in FLOW_BUILDER_PROMPT, \\\"Prompt must show the `provider` key of the model field value.\\\"\\n        assert '\\\"name\\\"' in FLOW_BUILDER_PROMPT, \\\"Prompt must show the `name` key of the model field value.\\\"\\n\\n\\nclass TestFlowBuilderPromptBehaviorContract:\\n    \\\"\\\"\\\"WS-2 / RC-2 \u2014 prompt forbids the hallucination/confirmation anti-pattern.\\n\\n    Production (screenshots 2/6/7/8): the agent asked to confirm an action the\\n    user already requested, or claimed an action without calling the tool. It\\n    must also keep the reply in the user's language (report #7).\\n    \\\"\\\"\\\"\\n\\n    def test_should_forbid_asking_confirmation_for_already_requested_action(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"confirm\\\" in prompt_lower or \\\"confirmation\\\" in prompt_lower, (\\n            \\\"Prompt must address the 'asking to confirm an already-requested action' anti-pattern\\\"\\n        )\\n        assert \\\"never ask\\\" in prompt_lower or \\\"do not ask\\\" in prompt_lower or \\\"without asking\\\" in prompt_lower, (\\n            \\\"Prompt must explicitly forbid asking the user to confirm an action they already requested\\\"\\n        )\\n\\n    def test_should_forbid_claiming_action_without_calling_the_tool(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        forbids_claim = (\\n            \\\"never claim\\\" in prompt_lower or \\\"do not claim\\\" in prompt_lower or \\\"without actually\\\" in prompt_lower\\n        )\\n        assert forbids_claim, \\\"Prompt must forbid claiming an action was done without calling the tool that performs it\\\"\\n\\n    def test_should_instruct_reply_in_user_language(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"same language\\\" in prompt_lower or \\\"user's language\\\" in prompt_lower, (\\n            \\\"Prompt must instruct the agent to reply in the language the user wrote in (report #7)\\\"\\n        )\\n\\n\\nclass TestFlowBuilderPromptUserComponents:\\n    \\\"\\\"\\\"WS-3 / RC-3 \u2014 prompt tells the agent user-generated components are registered and searchable.\\n\\n    They are discoverable via search_components by class name, so the agent\\n    uses them in build_flow instead of refusing (\\\"custom components must be\\n    added manually outside the flow builder\\\" \u2014 screenshot 2).\\n    \\\"\\\"\\\"\\n\\n    def test_should_mention_user_generated_components_are_registered(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"search_components\\\" in prompt_lower\\n        assert (\\n            \\\"user-generated\\\" in prompt_lower\\n            or \\\"user-created\\\" in prompt_lower\\n            or \\\"previously generated component\\\" in prompt_lower\\n            or \\\"components you generated\\\" in prompt_lower\\n        ), \\\"Prompt must state that components the user generated this session are searchable by class name\\\"\\n\\n    def test_should_forbid_refusing_to_use_user_components_in_a_flow(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"manually\\\" in prompt_lower, (\\n            \\\"Prompt must explicitly counter the 'must be added manually outside the flow builder' refusal\\\"\\n        )\\n\\n\\nclass TestFlowBuilderPromptLegacyComponents:\\n    \\\"\\\"\\\"WS-5 / RC-5 \u2014 prompt tells the agent not to use legacy/beta components unless asked.\\\"\\\"\\\"\\n\\n    def test_should_warn_against_legacy_components(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"legacy\\\" in prompt_lower, (\\n            \\\"Prompt must instruct the agent not to add legacy/beta components unless explicitly requested\\\"\\n        )\\n\\n\\nclass TestFlowBuilderPromptLoopRecipe:\\n    \\\"\\\"\\\"The prompt's canonical loop spec must stay buildable against the LIVE registry.\\n\\n    loop_flow eval regression: the 0/3 failure came from a stale recipe \u2014 it\\n    named legacy components (`ParseData`, `MessagetoData`) that\\n    search_components hides, and did not cover the Message-consuming body\\n    head (Agent), so `L.item -> A.input_value` failed on type mismatch and\\n    the agent burned its recursion budget re-discovering components.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _canonical_loop_spec() -> str:\\n        section = FLOW_BUILDER_PROMPT.split(\\\"## Loops and branching\\\", 1)[1]\\n        block = section.split(\\\"```\\\", 2)\\n        assert len(block) >= 3, \\\"Loops section must contain a fenced canonical spec\\\"\\n        return \\\"name: Loop Recipe\\\\n\\\" + block[1].strip()\\n\\n    def test_loop_recipe_must_not_use_legacy_components(self):\\n        section = FLOW_BUILDER_PROMPT.split(\\\"## Loops and branching\\\", 1)[1].split(\\\"## \\\", 1)[0]\\n        assert \\\"ParseData\\\" not in section, \\\"legacy component in the loop recipe (hidden from search_components)\\\"\\n        assert \\\"MessagetoData\\\" not in section, \\\"legacy component in the loop recipe (hidden from search_components)\\\"\\n\\n    def test_loop_recipe_spec_builds_against_live_registry(self):\\n        from lfx.graph.flow_builder.builder import build_flow_from_spec\\n\\n        result = build_flow_from_spec(self._canonical_loop_spec())\\n        assert \\\"error\\\" not in result, f\\\"canonical loop recipe no longer builds: {result}\\\"\\n        edges = result[\\\"flow\\\"][\\\"data\\\"][\\\"edges\\\"]\\n        feedback = [\\n            e for e in edges if \\\"name\\\" in e[\\\"data\\\"][\\\"targetHandle\\\"] and \\\"fieldName\\\" not in e[\\\"data\\\"][\\\"targetHandle\\\"]\\n        ]\\n        assert feedback, \\\"canonical loop recipe must produce an output-shaped feedback edge\\\"\\n\\n    def test_loop_recipe_covers_the_message_consuming_body_head(self):\\n        section = FLOW_BUILDER_PROMPT.split(\\\"## Loops and branching\\\", 1)[1].split(\\\"## \\\", 1)[0]\\n        assert \\\"ParserComponent\\\" in section, \\\"recipe must show how a Data item reaches a Message input\\\"\\n        assert \\\"Agent\\\" in section, \\\"recipe must cover the loop-body-with-Agent request shape\\\"\\n\\n\\nclass TestFlowBuilderPromptProposePlan:\\n    \\\"\\\"\\\"propose_plan is OPTIONAL \u2014 used only for genuinely ambiguous or\\n    large/destructive whole-canvas replacements. Clear/specified requests\\n    (including multi-step ones) are executed directly, no plan gate. When a\\n    plan IS proposed the Continue/Dismiss loop still applies.\\n    \\\"\\\"\\\"  # noqa: D205\\n\\n    def test_should_mention_propose_plan_tool(self):\\n        assert \\\"propose_plan\\\" in FLOW_BUILDER_PROMPT, (\\n            \\\"Prompt must reference the propose_plan tool so the LLM knows to use it.\\\"\\n        )\\n\\n    def test_should_make_propose_plan_optional_not_mandatory(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        # The new contract: optional, reserved for ambiguous/destructive.\\n        assert \\\"optional\\\" in prompt_lower\\n        assert \\\"ambiguous\\\" in prompt_lower or \\\"destructive\\\" in prompt_lower\\n        # And it must NOT carry the old mandatory-first wording.\\n        assert \\\"always your first tool call\\\" not in prompt_lower\\n        assert \\\"mandatory in build mode\\\" not in prompt_lower\\n        # It must tell the agent to act directly for clear requests.\\n        assert \\\"directly\\\" in prompt_lower\\n\\n    def test_should_explain_user_continue_vs_dismiss_loop(self):\\n        # After propose_plan, the next user turn is either an approval signal or\\n        # refinement feedback. The agent needs to know how to act on each.\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"continue\\\" in prompt_lower or \\\"approve\\\" in prompt_lower, (\\n            \\\"Prompt must describe what to do when the user continues/approves the plan.\\\"\\n        )\\n        assert \\\"dismiss\\\" in prompt_lower or \\\"refine\\\" in prompt_lower or \\\"feedback\\\" in prompt_lower, (\\n            \\\"Prompt must describe what to do when the user dismisses/refines the plan.\\\"\\n        )\\n\\n\\nclass TestRunFlowToolWiring:\\n    \\\"\\\"\\\"The agent must be able to run the canvas flow and discuss the result.\\\"\\\"\\\"\\n\\n    async def test_toolkit_should_include_run_flow_tool(self):\\n        from langflow.agentic.flows.flow_builder_assistant import build_toolkit\\n\\n        tools = await build_toolkit()\\n        names = {getattr(t, \\\"name\\\", None) for t in tools}\\n        assert \\\"run_flow\\\" in names, f\\\"run_flow must be in the toolkit, got: {sorted(n for n in names if n)}\\\"\\n\\n    def test_prompt_should_document_run_flow(self):\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"run_flow\\\" in prompt_lower, \\\"Prompt must describe the run_flow tool\\\"\\n        assert \\\"run\\\" in prompt_lower, \\\"Prompt must mention running\\\"\\n        assert \\\"result\\\" in prompt_lower, \\\"Prompt must say run_flow returns the result for the agent to discuss\\\"\\n\\n    def test_prompt_should_say_run_is_not_a_build_no_plan_gate(self):\\n        \\\"\\\"\\\"A run calls run_flow directly \u2014 never propose_plan (the \\\"rode o flow \u2192 Generating plan\u2026\\\" bug).\\\"\\\"\\\"\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"not a build\\\" in prompt_lower or \\\"is not build\\\" in prompt_lower, (\\n            \\\"Prompt must state running the flow is NOT a build\\\"\\n        )\\n        # The run_flow guidance must forbid propose_plan for a pure run.\\n        assert \\\"propose_plan\\\" in prompt_lower\\n        assert \\\"run_flow\\\" in prompt_lower\\n\\n\\nclass TestProposePlanInToolkit:\\n    \\\"\\\"\\\"The propose_plan tool must be present in the agent's toolkit and be\\n    callable by name through the standard tool interface.\\n    \\\"\\\"\\\"  # noqa: D205\\n\\n    async def test_toolkit_should_include_propose_plan_tool(self):\\n        from langflow.agentic.flows.flow_builder_assistant import build_toolkit\\n\\n        tools = await build_toolkit()\\n        names = {getattr(t, \\\"name\\\", None) for t in tools}\\n\\n        assert \\\"propose_plan\\\" in names, f\\\"propose_plan must be in the toolkit, got: {sorted(n for n in names if n)}\\\"\\n\\n\\nclass TestTranslationPromptBuildFlow:\\n    def test_should_contain_build_flow_intent(self):\\n        assert \\\"build_flow\\\" in TRANSLATION_PROMPT\\n\\n    def test_should_have_build_flow_examples(self):\\n        assert \\\"build me a RAG pipeline\\\" in TRANSLATION_PROMPT\\n\\n    def test_should_have_simple_chat_flow_example(self):\\n        assert \\\"simple chat flow\\\" in TRANSLATION_PROMPT\\n\\n    def test_should_prefer_build_flow_when_ambiguous(self):\\n        assert \\\"prefer build_flow\\\" in TRANSLATION_PROMPT\\n\\n\\nclass TestGetGraph:\\n    async def test_should_create_graph_with_defaults(self):\\n        graph = await get_graph()\\n        assert graph is not None\\n\\n    async def test_should_accept_provider_and_model(self):\\n        graph = await get_graph(provider=\\\"OpenAI\\\", model_name=\\\"gpt-4o\\\")\\n        assert graph is not None\\n\\n    async def test_should_accept_api_key_var(self):\\n        graph = await get_graph(api_key_var=\\\"OPENAI_API_KEY\\\")  # pragma: allowlist secret\\n        assert graph is not None\\n\\n    async def test_second_call_should_not_crash(self):\\n        \\\"\\\"\\\"Regression: second get_graph call must not fail due to stale state.\\\"\\\"\\\"\\n        g1 = await get_graph(provider=\\\"OpenAI\\\", model_name=\\\"gpt-4o\\\")\\n        assert g1 is not None\\n        g2 = await get_graph(provider=\\\"OpenAI\\\", model_name=\\\"gpt-4o\\\")\\n        assert g2 is not None\\n\\n    async def test_different_providers_on_consecutive_calls(self):\\n        \\\"\\\"\\\"Consecutive calls with different providers must both succeed.\\\"\\\"\\\"\\n        g1 = await get_graph(provider=\\\"OpenAI\\\", model_name=\\\"gpt-4o\\\")\\n        assert g1 is not None\\n        g2 = await get_graph(provider=\\\"Anthropic\\\", model_name=\\\"claude-sonnet-4-6\\\")\\n        assert g2 is not None\\n\\n    async def test_flow_loader_reload_simulation(self):\\n        \\\"\\\"\\\"Simulate how flow_loader loads the module -- importlib reload.\\\"\\\"\\\"\\n        import importlib.util\\n        import sys\\n        from pathlib import Path\\n\\n        flow_path = (\\n            Path(__file__).resolve().parent.parent.parent.parent.parent\\n            / \\\"base\\\"\\n            / \\\"langflow\\\"\\n            / \\\"agentic\\\"\\n            / \\\"flows\\\"\\n            / \\\"flow_builder_assistant.py\\\"\\n        )\\n        assert flow_path.exists(), f\\\"Flow file not found: {flow_path}\\\"\\n\\n        async def _load_and_call(**kwargs):\\n            module_name = \\\"flow_builder_assistant_test\\\"\\n            spec = importlib.util.spec_from_file_location(module_name, flow_path)\\n            module = importlib.util.module_from_spec(spec)\\n            sys.modules[module_name] = module\\n            spec.loader.exec_module(module)\\n            try:\\n                return await module.get_graph(**kwargs)\\n            finally:\\n                del sys.modules[module_name]\\n\\n        # First load\\n        g1 = await _load_and_call(provider=\\\"OpenAI\\\", model_name=\\\"gpt-4o\\\")\\n        assert g1 is not None\\n\\n        # Second load -- this is where the 'dict' has no attribute 'replace' crash happened\\n        g2 = await _load_and_call(provider=\\\"Anthropic\\\", model_name=\\\"claude-sonnet-4-6\\\")\\n        assert g2 is not None\\n\\n    async def test_load_graph_for_execution_twice(self):\\n        \\\"\\\"\\\"Use the real flow_loader path -- the exact production code path.\\\"\\\"\\\"\\n        from langflow.agentic.services.helpers.flow_loader import load_graph_for_execution, resolve_flow_path\\n\\n        flow_path, flow_type = resolve_flow_path(\\\"flow_builder_assistant\\\")\\n\\n        g1 = await load_graph_for_execution(flow_path, flow_type, \\\"OpenAI\\\", \\\"gpt-4o\\\", \\\"OPENAI_API_KEY\\\")\\n        assert g1 is not None\\n\\n        g2 = await load_graph_for_execution(flow_path, flow_type, \\\"Anthropic\\\", \\\"claude-sonnet-4-6\\\", \\\"ANTHROPIC_API_KEY\\\")\\n        assert g2 is not None\\n\\n    async def test_load_graph_for_execution_with_replace_in_prompt(self):\\n        \\\"\\\"\\\"Regression: .replace() on FLOW_BUILDER_PROMPT must work on second load.\\n\\n        The production bug was: 'dict' object has no attribute 'replace'\\n        on the second call to get_graph(). This test ensures the prompt\\n        string is never mutated to a dict by the first call.\\n        \\\"\\\"\\\"\\n        from langflow.agentic.services.helpers.flow_loader import load_graph_for_execution, resolve_flow_path\\n\\n        flow_path, flow_type = resolve_flow_path(\\\"flow_builder_assistant\\\")\\n\\n        # Load twice in quick succession with different params\\n        for i in range(3):\\n            graph = await load_graph_for_execution(flow_path, flow_type, \\\"OpenAI\\\", \\\"gpt-4o\\\", \\\"OPENAI_API_KEY\\\")\\n            assert graph is not None, f\\\"Failed on iteration {i}\\\"\\n\\n\\nclass TestFilesystemToolsInToolkit:\\n    \\\"\\\"\\\"B3 \u2014 the agent gets the FileSystemTool's 5 tools, wrapped to emit events.\\n\\n    These tests exercise the wrapped tools directly (bypassing the LLM): given\\n    the user's `manage_files` intent, the same agent must be able to write\\n    files. The wrapper emits ``file_written`` only on successful writes.\\n    \\\"\\\"\\\"\\n\\n    async def test_toolkit_should_include_filesystem_tools(self):\\n        from langflow.agentic.flows.flow_builder_assistant import build_toolkit\\n\\n        tools = await build_toolkit()\\n        names = {getattr(t, \\\"name\\\", None) for t in tools}\\n\\n        assert {\\\"read_file\\\", \\\"write_file\\\", \\\"edit_file\\\", \\\"glob_search\\\", \\\"grep_search\\\"}.issubset(names), (\\n            f\\\"FileSystem tools must be present in the toolkit, got: {names}\\\"\\n        )\\n\\n    async def test_toolkit_should_keep_existing_canvas_tools(self):\\n        \\\"\\\"\\\"Regression \u2014 adding filesystem tools must not drop the existing toolkit.\\\"\\\"\\\"\\n        from langflow.agentic.flows.flow_builder_assistant import build_toolkit\\n\\n        tools = await build_toolkit()\\n        names = {getattr(t, \\\"name\\\", None) for t in tools}\\n\\n        assert {\\n            \\\"search_components\\\",\\n            \\\"describe_component\\\",\\n            \\\"get_field_value\\\",\\n            \\\"add_component\\\",\\n            \\\"build_flow\\\",\\n        }.issubset(names)\\n\\n    async def test_write_file_through_toolkit_should_emit_file_written_event(self, tmp_path, monkeypatch):\\n        from langflow.agentic.flows.flow_builder_assistant import build_toolkit\\n        from langflow.agentic.services.file_events import drain_file_events, reset_file_events\\n\\n        monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n        reset_file_events()\\n\\n        tools = await build_toolkit()\\n        write_tool = next(t for t in tools if t.name == \\\"write_file\\\")\\n\\n        result_json = write_tool.func(path=\\\"DOCS.md\\\", content=\\\"# Hello\\\")\\n        import json\\n\\n        result = json.loads(result_json)\\n        assert result.get(\\\"status\\\") in {\\\"created\\\", \\\"updated\\\"}, result\\n\\n        events = drain_file_events()\\n        assert len(events) == 1\\n        assert events[0][\\\"action\\\"] == \\\"write_file\\\"\\n        assert events[0][\\\"path\\\"] == \\\"DOCS.md\\\"\\n        assert events[0][\\\"size\\\"] == len(b\\\"# Hello\\\")\\n\\n    async def test_edit_file_through_toolkit_should_emit_file_written_event(self, tmp_path, monkeypatch):\\n        from langflow.agentic.flows.flow_builder_assistant import build_toolkit\\n        from langflow.agentic.services.file_events import drain_file_events, reset_file_events\\n\\n        monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n        reset_file_events()\\n\\n        tools = await build_toolkit()\\n        write_tool = next(t for t in tools if t.name == \\\"write_file\\\")\\n        edit_tool = next(t for t in tools if t.name == \\\"edit_file\\\")\\n\\n        # Arrange \u2014 write then drain the write event so only the edit event is observed.\\n        write_tool.func(path=\\\"DOCS.md\\\", content=\\\"hello world\\\")\\n        drain_file_events()\\n\\n        # Act\\n        edit_tool.func(path=\\\"DOCS.md\\\", old_string=\\\"hello\\\", new_string=\\\"hi\\\")\\n\\n        # Assert\\n        events = drain_file_events()\\n        assert len(events) == 1\\n        assert events[0][\\\"action\\\"] == \\\"edit_file\\\"\\n\\n    async def test_write_file_event_path_should_not_leak_base_dir(self, tmp_path, monkeypatch):\\n        from langflow.agentic.flows.flow_builder_assistant import build_toolkit\\n        from langflow.agentic.services.file_events import drain_file_events, reset_file_events\\n\\n        monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n        reset_file_events()\\n\\n        tools = await build_toolkit()\\n        write_tool = next(t for t in tools if t.name == \\\"write_file\\\")\\n        write_tool.func(path=\\\"DOCS.md\\\", content=\\\"x\\\")\\n\\n        [event] = drain_file_events()\\n        path = event[\\\"path\\\"]\\n        assert not path.startswith(\\\"/\\\"), f\\\"BASE_DIR leak: {path!r}\\\"\\n        assert not path.startswith(\\\"\\\\\\\\\\\"), f\\\"BASE_DIR leak (Windows): {path!r}\\\"\\n        assert not (len(path) >= 2 and path[1] == \\\":\\\"), f\\\"Drive-letter leak: {path!r}\\\"\\n        assert str(tmp_path) not in path, f\\\"Full sandbox path leak: {path!r}\\\"\\n\\n    async def test_failed_write_should_not_emit_event(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Path traversal is refused by FileSystemTool \u2014 no event must follow.\\\"\\\"\\\"\\n        from langflow.agentic.flows.flow_builder_assistant import build_toolkit\\n        from langflow.agentic.services.file_events import drain_file_events, reset_file_events\\n\\n        monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n        reset_file_events()\\n\\n        tools = await build_toolkit()\\n        write_tool = next(t for t in tools if t.name == \\\"write_file\\\")\\n        import json\\n\\n        result = json.loads(write_tool.func(path=\\\"../escape.md\\\", content=\\\"x\\\"))\\n        assert \\\"error\\\" in result\\n\\n        assert drain_file_events() == []\\n\\n    async def test_read_file_should_not_emit_event(self, tmp_path, monkeypatch):\\n        from langflow.agentic.flows.flow_builder_assistant import build_toolkit\\n        from langflow.agentic.services.file_events import drain_file_events, reset_file_events\\n\\n        monkeypatch.setenv(\\\"LANGFLOW_FS_TOOL_BASE_DIR\\\", str(tmp_path))\\n        reset_file_events()\\n\\n        tools = await build_toolkit()\\n        write_tool = next(t for t in tools if t.name == \\\"write_file\\\")\\n        read_tool = next(t for t in tools if t.name == \\\"read_file\\\")\\n\\n        write_tool.func(path=\\\"DOCS.md\\\", content=\\\"content\\\")\\n        drain_file_events()  # discard write event\\n\\n        read_tool.func(path=\\\"DOCS.md\\\")\\n        assert drain_file_events() == []\\n\\n\\nclass TestFlowBuilderPromptFilesystem:\\n    \\\"\\\"\\\"B3 \u2014 the prompt mentions the filesystem tools so the agent uses them.\\\"\\\"\\\"\\n\\n    def test_prompt_should_mention_write_file(self):\\n        from langflow.agentic.flows.flow_builder_assistant import FLOW_BUILDER_PROMPT\\n\\n        assert \\\"write_file\\\" in FLOW_BUILDER_PROMPT, (\\n            \\\"Prompt must describe write_file so the LLM knows it can persist documentation files\\\"\\n        )\\n\\n    def test_prompt_should_mention_sandbox(self):\\n        from langflow.agentic.flows.flow_builder_assistant import FLOW_BUILDER_PROMPT\\n\\n        prompt_lower = FLOW_BUILDER_PROMPT.lower()\\n        assert \\\"sandbox\\\" in prompt_lower or \\\"workspace\\\" in prompt_lower, (\\n            \\\"Prompt should clarify that paths are sandbox-relative so the LLM doesn't use absolute paths\\\"\\n        )\\n\\n\\n@pytest.mark.skipif(\\n    not has_api_key(\\\"OPENAI_API_KEY\\\"),\\n    reason=\\\"OPENAI_API_KEY required for intent classification test\\\",\\n)\\n@pytest.mark.api_key_required\\nclass TestIntentClassificationBuildFlow:\\n    \\\"\\\"\\\"Test that the intent classifier correctly identifies build_flow requests.\\n\\n    These tests call the real OpenAI API through the translation flow.\\n    \\\"\\\"\\\"\\n\\n    async def test_simple_chat_flow_classified_as_build_flow(self):\\n        from langflow.agentic.services.helpers.intent_classification import classify_intent\\n\\n        result = await classify_intent(\\n            text=\\\"simple chat flow\\\",\\n            global_variables={},\\n            provider=\\\"OpenAI\\\",\\n            model_name=\\\"gpt-4o-mini\\\",\\n            api_key_var=\\\"OPENAI_API_KEY\\\",\\n        )\\n        assert result.intent == \\\"build_flow\\\", f\\\"Expected build_flow, got {result.intent}\\\"\\n\\n    async def test_build_rag_pipeline_classified_as_build_flow(self):\\n        from langflow.agentic.services.helpers.intent_classification import classify_intent\\n\\n        result = await classify_intent(\\n            text=\\\"build me a RAG pipeline\\\",\\n            global_variables={},\\n            provider=\\\"OpenAI\\\",\\n            model_name=\\\"gpt-4o-mini\\\",\\n            api_key_var=\\\"OPENAI_API_KEY\\\",\\n        )\\n        assert result.intent == \\\"build_flow\\\", f\\\"Expected build_flow, got {result.intent}\\\"\\n\\n    async def test_can_you_build_a_flow_classified_as_build_flow(self):\\n        from langflow.agentic.services.helpers.intent_classification import classify_intent\\n\\n        result = await classify_intent(\\n            text=\\\"can you build a flow for me?\\\",\\n            global_variables={},\\n            provider=\\\"OpenAI\\\",\\n            model_name=\\\"gpt-4o-mini\\\",\\n            api_key_var=\\\"OPENAI_API_KEY\\\",\\n        )\\n        assert result.intent == \\\"build_flow\\\", f\\\"Expected build_flow, got {result.intent}\\\"\\n\\n    async def test_create_component_not_classified_as_build_flow(self):\\n        from langflow.agentic.services.helpers.intent_classification import classify_intent\\n\\n        result = await classify_intent(\\n            text=\\\"create a component that calls an API\\\",\\n            global_variables={},\\n            provider=\\\"OpenAI\\\",\\n            model_name=\\\"gpt-4o-mini\\\",\\n            api_key_var=\\\"OPENAI_API_KEY\\\",\\n        )\\n        assert result.intent == \\\"generate_component\\\", f\\\"Expected generate_component, got {result.intent}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/flows/test_flow_builder_assistant_force_isolation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d198ae8c95df01170df3c22653b3437bd06e517da2b3f259fb91e12bfb169c8d\",\"content\":\"\\\"\\\"\\\"B1 \u2014 build_toolkit must bind user_id + force_isolation on the FS component.\\n\\nThe agent's write_file / edit_file tools are produced by\\n``FileSystemToolComponent._get_tools()`` inside ``build_toolkit``. Without\\nexplicit binding the standalone component has no user_id and falls back to\\nthe shared root under ``AUTO_LOGIN=True`` \u2014 but the /agentic/files endpoint\\n(B1) now forces per-user isolation, so the agent must mirror it or its\\nwrites become unreadable from the endpoint.\\n\\nThis test asserts the toolkit-build-time binding: when ``current_user_id``\\nis bound to the request, the fs component used to mint the tools has\\n``_user_id`` set AND ``_force_isolation = True``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom langflow.agentic.flows import flow_builder_assistant as fba\\nfrom langflow.agentic.services.user_components_context import (\\n    reset_current_user_id,\\n    set_current_user_id,\\n)\\n\\n\\nclass _StubStructuredTool:\\n    \\\"\\\"\\\"Minimal stand-in returned by the patched FS toolkit.\\n\\n    Carries the attributes ``wrap_file_tool_with_event`` reads\\n    (``name``, ``func``, ``coroutine``, ``args_schema``) so the wrapping\\n    branch in build_toolkit doesn't crash mid-test.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, name: str) -> None:\\n        self.name = name\\n        self.description = \\\"\\\"\\n        self.func = lambda *_a, **_k: {\\\"status\\\": \\\"ok\\\"}\\n        self.coroutine = None\\n        self.args_schema = None\\n\\n\\nclass _CapturingFSComponent:\\n    \\\"\\\"\\\"Capture the per-call state for assertion.\\n\\n    Mimics the small subset of FileSystemToolComponent the toolkit builder\\n    actually touches.\\n    \\\"\\\"\\\"\\n\\n    instances: list[_CapturingFSComponent] = []\\n\\n    def __init__(self) -> None:\\n        self._user_id: str | None = None\\n        self._force_isolation: bool = False\\n        self._get_tools_called_with: dict | None = None\\n        _CapturingFSComponent.instances.append(self)\\n\\n    async def _get_tools(self) -> list:\\n        # Snapshot the binding state AT THE MOMENT _get_tools is called,\\n        # because that's when bound_user_id is captured for the lifetime of\\n        # the tools.\\n        self._get_tools_called_with = {\\n            \\\"user_id\\\": self._user_id,\\n            \\\"force_isolation\\\": self._force_isolation,\\n        }\\n        # Return both a read tool and a write tool to exercise the wrapping\\n        # branch in build_toolkit.\\n        return [_StubStructuredTool(\\\"read_file\\\"), _StubStructuredTool(\\\"write_file\\\")]\\n\\n\\nclass TestBuildToolkitBindsForceIsolation:\\n    async def test_should_bind_user_id_and_force_isolation_when_user_context_set(self, monkeypatch):\\n        # Arrange \u2014 replace the heavy FS component with our capturing stub.\\n        _CapturingFSComponent.instances.clear()\\n        monkeypatch.setattr(fba, \\\"FileSystemToolComponent\\\", _CapturingFSComponent)\\n\\n        # Skip the canvas-component instantiation (heavy registry side effects).\\n        async def fake_to_toolkit(_self):\\n            return []\\n\\n        for component_cls in (\\n            fba.SearchComponentTypes,\\n            fba.DescribeComponentType,\\n            fba.DescribeFlowIO,\\n            fba.GenerateComponent,\\n            fba.GetFieldValue,\\n            fba.ProposeFieldEdit,\\n            fba.ProposePlan,\\n            fba.AddComponent,\\n            fba.RemoveComponent,\\n            fba.ConnectComponents,\\n            fba.ConfigureComponent,\\n            fba.BuildFlowFromSpec,\\n            fba.RunFlow,\\n        ):\\n            monkeypatch.setattr(component_cls, \\\"to_toolkit\\\", fake_to_toolkit, raising=True)\\n\\n        # Bind the request's user context (mirrors assistant_service:578).\\n        set_current_user_id(\\\"user-alice\\\")\\n        try:\\n            await fba.build_toolkit()\\n        finally:\\n            reset_current_user_id()\\n\\n        # Assert \u2014 exactly one fs component was instantiated and it captured\\n        # the user_id + force_isolation at _get_tools time.\\n        assert len(_CapturingFSComponent.instances) == 1\\n        captured = _CapturingFSComponent.instances[0]._get_tools_called_with\\n        assert captured == {\\\"user_id\\\": \\\"user-alice\\\", \\\"force_isolation\\\": True}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/flows/test_translation_flow.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a936a9d8d075d5bf3409e9d750daa21bf67233f1345cc4a123d78139d73d73f7\",\"content\":\"\\\"\\\"\\\"Tests for TranslationFlow.\\n\\nTests the graph construction and model configuration for the translation flow.\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import MagicMock, patch\\n\\nfrom langflow.agentic.flows.translation_flow import (\\n    TRANSLATION_PROMPT,\\n    _build_model_config,\\n    get_graph,\\n)\\n\\n\\nclass TestBuildModelConfig:\\n    \\\"\\\"\\\"Tests for _build_model_config function.\\\"\\\"\\\"\\n\\n    def test_should_build_config_for_openai(self):\\n        \\\"\\\"\\\"Should build correct config for OpenAI provider.\\\"\\\"\\\"\\n        result = _build_model_config(\\\"OpenAI\\\", \\\"gpt-4o-mini\\\")\\n\\n        assert len(result) == 1\\n        config = result[0]\\n        assert config[\\\"provider\\\"] == \\\"OpenAI\\\"\\n        assert config[\\\"name\\\"] == \\\"gpt-4o-mini\\\"\\n        assert config[\\\"icon\\\"] == \\\"OpenAI\\\"\\n        assert config[\\\"metadata\\\"][\\\"model_class\\\"] == \\\"ChatOpenAI\\\"\\n        assert config[\\\"metadata\\\"][\\\"model_name_param\\\"] == \\\"model\\\"\\n        assert config[\\\"metadata\\\"][\\\"api_key_param\\\"] == \\\"api_key\\\"\\n\\n    def test_should_build_config_for_anthropic(self):\\n        \\\"\\\"\\\"Should build correct config for Anthropic provider.\\\"\\\"\\\"\\n        result = _build_model_config(\\\"Anthropic\\\", \\\"claude-3-haiku\\\")\\n\\n        config = result[0]\\n        assert config[\\\"provider\\\"] == \\\"Anthropic\\\"\\n        assert config[\\\"name\\\"] == \\\"claude-3-haiku\\\"\\n        assert config[\\\"metadata\\\"][\\\"model_class\\\"] == \\\"ChatAnthropic\\\"\\n\\n    def test_should_build_config_for_google(self):\\n        \\\"\\\"\\\"Should build correct config for Google Generative AI.\\\"\\\"\\\"\\n        result = _build_model_config(\\\"Google Generative AI\\\", \\\"gemini-flash\\\")\\n\\n        config = result[0]\\n        assert config[\\\"metadata\\\"][\\\"model_class\\\"] == \\\"ChatGoogleGenerativeAIFixed\\\"\\n\\n    def test_should_build_config_for_groq(self):\\n        \\\"\\\"\\\"Should build correct config for Groq.\\\"\\\"\\\"\\n        result = _build_model_config(\\\"Groq\\\", \\\"mixtral-8x7b\\\")\\n\\n        config = result[0]\\n        assert config[\\\"metadata\\\"][\\\"model_class\\\"] == \\\"ChatGroq\\\"\\n\\n    def test_should_build_config_for_azure_openai(self):\\n        \\\"\\\"\\\"Should build correct config for Azure OpenAI.\\\"\\\"\\\"\\n        result = _build_model_config(\\\"Azure OpenAI\\\", \\\"gpt-35-turbo\\\")\\n\\n        config = result[0]\\n        assert config[\\\"metadata\\\"][\\\"model_class\\\"] == \\\"AzureChatOpenAI\\\"\\n\\n    def test_should_default_to_openai_for_unknown_provider(self):\\n        \\\"\\\"\\\"Should default to ChatOpenAI for unknown provider.\\\"\\\"\\\"\\n        result = _build_model_config(\\\"CustomProvider\\\", \\\"custom-model\\\")\\n\\n        config = result[0]\\n        assert config[\\\"metadata\\\"][\\\"model_class\\\"] == \\\"ChatOpenAI\\\"\\n\\n    def test_should_include_context_length(self):\\n        \\\"\\\"\\\"Should include context_length in metadata.\\\"\\\"\\\"\\n        result = _build_model_config(\\\"OpenAI\\\", \\\"gpt-4\\\")\\n\\n        config = result[0]\\n        assert config[\\\"metadata\\\"][\\\"context_length\\\"] == 128000\\n\\n\\nclass TestGetGraph:\\n    \\\"\\\"\\\"Tests for get_graph function.\\\"\\\"\\\"\\n\\n    def test_should_create_graph_with_default_provider(self):\\n        \\\"\\\"\\\"Should create graph with OpenAI as default provider.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatInput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatOutput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.LanguageModelComponent\\\") as mock_llm,\\n            patch(\\\"langflow.agentic.flows.translation_flow.Graph\\\"),\\n        ):\\n            mock_llm_instance = MagicMock()\\n            mock_llm.return_value = mock_llm_instance\\n\\n            get_graph()\\n\\n            call_args = mock_llm_instance.set_input_value.call_args\\n            model_config = call_args[0][1]\\n            assert model_config[0][\\\"provider\\\"] == \\\"OpenAI\\\"\\n            assert model_config[0][\\\"name\\\"] == \\\"gpt-4o-mini\\\"\\n\\n    def test_should_use_provided_provider_and_model(self):\\n        \\\"\\\"\\\"Should use provided provider and model_name.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatInput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatOutput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.LanguageModelComponent\\\") as mock_llm,\\n            patch(\\\"langflow.agentic.flows.translation_flow.Graph\\\"),\\n        ):\\n            mock_llm_instance = MagicMock()\\n            mock_llm.return_value = mock_llm_instance\\n\\n            get_graph(provider=\\\"Anthropic\\\", model_name=\\\"claude-3-haiku\\\")\\n\\n            call_args = mock_llm_instance.set_input_value.call_args\\n            model_config = call_args[0][1]\\n            assert model_config[0][\\\"provider\\\"] == \\\"Anthropic\\\"\\n            assert model_config[0][\\\"name\\\"] == \\\"claude-3-haiku\\\"\\n\\n    def test_should_include_api_key_when_provided(self):\\n        \\\"\\\"\\\"Should include api_key in LLM config when api_key_var is provided.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatInput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatOutput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.LanguageModelComponent\\\") as mock_llm,\\n            patch(\\\"langflow.agentic.flows.translation_flow.Graph\\\"),\\n        ):\\n            mock_llm_instance = MagicMock()\\n            mock_llm.return_value = mock_llm_instance\\n\\n            get_graph(api_key_var=\\\"OPENAI_API_KEY\\\")\\n\\n            set_call = mock_llm_instance.set.call_args\\n            assert \\\"api_key\\\" in set_call[1]\\n            assert set_call[1][\\\"api_key\\\"] == \\\"OPENAI_API_KEY\\\"\\n\\n    def test_should_not_include_api_key_when_not_provided(self):\\n        \\\"\\\"\\\"Should not include api_key when api_key_var is None.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatInput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatOutput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.LanguageModelComponent\\\") as mock_llm,\\n            patch(\\\"langflow.agentic.flows.translation_flow.Graph\\\"),\\n        ):\\n            mock_llm_instance = MagicMock()\\n            mock_llm.return_value = mock_llm_instance\\n\\n            get_graph()\\n\\n            set_call = mock_llm_instance.set.call_args\\n            assert \\\"api_key\\\" not in set_call[1]\\n\\n    def test_should_set_low_temperature(self):\\n        \\\"\\\"\\\"Should set low temperature for consistent JSON output.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatInput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatOutput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.LanguageModelComponent\\\") as mock_llm,\\n            patch(\\\"langflow.agentic.flows.translation_flow.Graph\\\"),\\n        ):\\n            mock_llm_instance = MagicMock()\\n            mock_llm.return_value = mock_llm_instance\\n\\n            get_graph()\\n\\n            set_call = mock_llm_instance.set.call_args\\n            assert set_call[1][\\\"temperature\\\"] == 0.1\\n\\n    def test_should_set_system_message(self):\\n        \\\"\\\"\\\"Should set system_message to TRANSLATION_PROMPT.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatInput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatOutput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.LanguageModelComponent\\\") as mock_llm,\\n            patch(\\\"langflow.agentic.flows.translation_flow.Graph\\\"),\\n        ):\\n            mock_llm_instance = MagicMock()\\n            mock_llm.return_value = mock_llm_instance\\n\\n            get_graph()\\n\\n            set_call = mock_llm_instance.set.call_args\\n            assert set_call[1][\\\"system_message\\\"] == TRANSLATION_PROMPT\\n\\n    def test_should_configure_chat_input(self):\\n        \\\"\\\"\\\"Should configure ChatInput with correct settings.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatInput\\\") as mock_chat_input,\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatOutput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.LanguageModelComponent\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.Graph\\\"),\\n        ):\\n            mock_input_instance = MagicMock()\\n            mock_chat_input.return_value = mock_input_instance\\n\\n            get_graph()\\n\\n            mock_input_instance.set.assert_called_once()\\n            set_call = mock_input_instance.set.call_args\\n            assert set_call[1][\\\"sender\\\"] == \\\"User\\\"\\n            assert set_call[1][\\\"should_store_message\\\"] is False\\n\\n    def test_should_configure_chat_output(self):\\n        \\\"\\\"\\\"Should configure ChatOutput with correct settings.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatInput\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatOutput\\\") as mock_chat_output,\\n            patch(\\\"langflow.agentic.flows.translation_flow.LanguageModelComponent\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.Graph\\\"),\\n        ):\\n            mock_output_instance = MagicMock()\\n            mock_chat_output.return_value = mock_output_instance\\n\\n            get_graph()\\n\\n            mock_output_instance.set.assert_called_once()\\n            set_call = mock_output_instance.set.call_args\\n            assert set_call[1][\\\"sender\\\"] == \\\"Machine\\\"\\n            assert set_call[1][\\\"sender_name\\\"] == \\\"AI\\\"\\n            assert set_call[1][\\\"clean_data\\\"] is True\\n\\n    def test_should_create_graph_with_start_and_end(self):\\n        \\\"\\\"\\\"Should create Graph with chat_input as start and chat_output as end.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatInput\\\") as mock_chat_input,\\n            patch(\\\"langflow.agentic.flows.translation_flow.ChatOutput\\\") as mock_chat_output,\\n            patch(\\\"langflow.agentic.flows.translation_flow.LanguageModelComponent\\\"),\\n            patch(\\\"langflow.agentic.flows.translation_flow.Graph\\\") as mock_graph_class,\\n        ):\\n            mock_input = MagicMock()\\n            mock_output = MagicMock()\\n            mock_chat_input.return_value = mock_input\\n            mock_chat_output.return_value = mock_output\\n\\n            get_graph()\\n\\n            mock_graph_class.assert_called_once_with(start=mock_input, end=mock_output)\\n\\n\\nclass TestTranslationPrompt:\\n    \\\"\\\"\\\"Tests for TRANSLATION_PROMPT constant.\\\"\\\"\\\"\\n\\n    def test_should_contain_translation_instructions(self):\\n        \\\"\\\"\\\"Should contain instructions for translation.\\\"\\\"\\\"\\n        assert \\\"translation\\\" in TRANSLATION_PROMPT.lower()\\n        assert \\\"english\\\" in TRANSLATION_PROMPT.lower()\\n\\n    def test_should_contain_intent_classification_instructions(self):\\n        \\\"\\\"\\\"Should contain instructions for intent classification.\\\"\\\"\\\"\\n        assert \\\"intent\\\" in TRANSLATION_PROMPT.lower()\\n        assert \\\"generate_component\\\" in TRANSLATION_PROMPT\\n        assert \\\"question\\\" in TRANSLATION_PROMPT\\n\\n    def test_should_specify_json_output_format(self):\\n        \\\"\\\"\\\"Should specify JSON output format.\\\"\\\"\\\"\\n        assert \\\"json\\\" in TRANSLATION_PROMPT.lower()\\n        assert \\\"translation\\\" in TRANSLATION_PROMPT\\n        assert \\\"intent\\\" in TRANSLATION_PROMPT\\n\\n    def test_should_contain_examples(self):\\n        \\\"\\\"\\\"Should contain classification examples.\\\"\\\"\\\"\\n        assert \\\"generate_component\\\" in TRANSLATION_PROMPT\\n        assert \\\"question\\\" in TRANSLATION_PROMPT\\n\\n    def test_should_distinguish_how_to_from_create(self):\\n        \\\"\\\"\\\"Should explain difference between 'how to create' and 'create'.\\\"\\\"\\\"\\n        prompt_lower = TRANSLATION_PROMPT.lower()\\n        assert \\\"how\\\" in prompt_lower\\n        assert \\\"create\\\" in prompt_lower or \\\"build\\\" in prompt_lower or \\\"generate\\\" in prompt_lower\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/flows/test_translation_flow_intents.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3fde28316f72adc4afad113e7d74897d7cd1540c6f3ec7a0a7e88638153f48e6\",\"content\":\"\\\"\\\"\\\"Tests for the TranslationFlow intent coverage.\\n\\nThese tests assert the prompt-level contract: which intents the TranslationFlow\\ndeclares, and which user phrasings map to each intent in the examples block.\\n\\nWhy prompt-level (not behavioral): the actual classification is performed by an\\nLLM at runtime, and behavioral tests would require a live model. The prompt is\\nthe executable specification of the routing rule \u2014 if the intent or its\\nexamples are missing here, the LLM has no way to learn the routing.\\n\\\"\\\"\\\"\\n\\nimport re\\n\\nfrom langflow.agentic.flows.translation_flow import TRANSLATION_PROMPT\\n\\n\\nclass TestManageFilesIntentDeclared:\\n    \\\"\\\"\\\"Slice B1 \u2014 manage_files intent is declared in the prompt with disambiguating examples.\\\"\\\"\\\"\\n\\n    def test_translation_prompt_should_list_manage_files_intent(self):\\n        # Arrange / Act\\n        prompt = TRANSLATION_PROMPT\\n\\n        # Assert \u2014 intent label must be declared in the JSON output format\\n        assert \\\"manage_files\\\" in prompt, \\\"TRANSLATION_PROMPT must list 'manage_files' as a recognized intent\\\"\\n        # ... and in the union in the output format line\\n        output_format_match = re.search(r'\\\"intent\\\":\\\\s*\\\"<([^\\\"]+)>\\\"', prompt)\\n        assert output_format_match is not None, \\\"Could not locate output format line\\\"\\n        union = output_format_match.group(1)\\n        assert \\\"manage_files\\\" in union.split(\\\"|\\\"), f\\\"manage_files must appear in the output format union, got: {union}\\\"\\n\\n    def test_translation_prompt_should_include_manage_files_example_in_english(self):\\n        prompt = TRANSLATION_PROMPT\\n        # At least one example whose Output JSON pairs an English file-action input with manage_files intent.\\n        # Match any line like: Output: {{\\\"translation\\\": \\\"<en>\\\", \\\"intent\\\": \\\"manage_files\\\"}}\\n        examples = re.findall(\\n            r'Output:\\\\s*\\\\{\\\\{\\\"translation\\\":\\\\s*\\\"([^\\\"]+)\\\",\\\\s*\\\"intent\\\":\\\\s*\\\"manage_files\\\"\\\\}\\\\}',\\n            prompt,\\n        )\\n        # At least one English example mentioning files / writing / saving.\\n        english_file_examples = [\\n            ex for ex in examples if re.search(r\\\"\\\\b(file|markdown|md|write|save|read|document)\\\\b\\\", ex, re.IGNORECASE)\\n        ]\\n        assert english_file_examples, (\\n            f\\\"Expected at least one English manage_files example mentioning file/markdown/document, got: {examples}\\\"\\n        )\\n\\n    def test_translation_prompt_should_include_manage_files_example_in_portuguese(self):\\n        prompt = TRANSLATION_PROMPT\\n        # Inputs (not translations) in PT \u2014 the example block has Input: \\\"<pt>\\\" / Output: ... .\\n        # We assert at least one Input line that looks Portuguese AND its paired Output is manage_files.\\n        pt_blocks = re.findall(\\n            r'Input:\\\\s*\\\"([^\\\"]+)\\\"\\\\s*\\\\nOutput:\\\\s*\\\\{\\\\{\\\"translation\\\":\\\\s*\\\"[^\\\"]+\\\",\\\\s*\\\"intent\\\":\\\\s*\\\"manage_files\\\"\\\\}\\\\}',\\n            prompt,\\n        )\\n        pt_examples = [\\n            block\\n            for block in pt_blocks\\n            if re.search(r\\\"\\\\b(crie|criar|salve|salvar|arquivo|documenta|leia|ler)\\\\b\\\", block, re.IGNORECASE)\\n        ]\\n        assert pt_examples, f\\\"Expected at least one Portuguese manage_files example, got blocks: {pt_blocks}\\\"\\n\\n    def test_translation_prompt_should_not_classify_file_creation_examples_as_build_flow(self):\\n        \\\"\\\"\\\"Disambiguation guard: no example pairs file-creation phrasing with build_flow intent.\\\"\\\"\\\"\\n        prompt = TRANSLATION_PROMPT\\n        # Find all Input/Output example blocks.\\n        blocks = re.findall(\\n            r'Input:\\\\s*\\\"([^\\\"]+)\\\"\\\\s*\\\\nOutput:\\\\s*\\\\{\\\\{\\\"translation\\\":\\\\s*\\\"([^\\\"]+)\\\",\\\\s*\\\"intent\\\":\\\\s*\\\"([^\\\"]+)\\\"\\\\}\\\\}',\\n            prompt,\\n        )\\n        # Look for file/document phrasing inside any block paired with build_flow.\\n        file_phrases = re.compile(\\n            r\\\"\\\\b(file|markdown|\\\\.md|write\\\\s+a\\\\s+file|save\\\\s+(?:as|to)\\\\s+file|crie\\\\s+um\\\\s+arquivo|salve\\\\s+o\\\\s+arquivo)\\\\b\\\",\\n            re.IGNORECASE,\\n        )\\n        offenders = [\\n            (block[0], block[2]) for block in blocks if block[2] == \\\"build_flow\\\" and file_phrases.search(block[0])\\n        ]\\n        assert not offenders, (\\n            f\\\"File-creation phrasings must not be classified as build_flow. Offending examples: {offenders}\\\"\\n        )\\n\\n\\nclass TestFollowUpSessionContextRouting:\\n    \\\"\\\"\\\"WS-1 / RC-1 \u2014 prompt teaches the classifier to use the session-context block for follow-ups.\\\"\\\"\\\"\\n\\n    def test_translation_prompt_should_reference_session_context_block(self):\\n        prompt = TRANSLATION_PROMPT.lower()\\n        assert \\\"session context\\\" in prompt, (\\n            \\\"Prompt must tell the classifier a [Session context ...] block may precede the user message\\\"\\n        )\\n\\n    def test_translation_prompt_should_route_contextual_followup_to_build_flow(self):\\n        \\\"\\\"\\\"With session context present, an imperative follow-up is build_flow, not question/off_topic.\\\"\\\"\\\"\\n        prompt = TRANSLATION_PROMPT.lower()\\n        has_rule = (\\n            \\\"session context\\\" in prompt\\n            and \\\"build_flow\\\" in prompt\\n            and (\\\"follow-up\\\" in prompt or \\\"follow up\\\" in prompt or \\\"followup\\\" in prompt)\\n        )\\n        assert has_rule, (\\n            \\\"Prompt must include a rule: with session context present, a follow-up \\\"\\n            \\\"edit/build is build_flow (not question/off_topic)\\\"\\n        )\\n\\n    def test_translation_prompt_should_translate_only_user_message_not_context(self):\\n        prompt = TRANSLATION_PROMPT.lower()\\n        assert \\\"do not translate\\\" in prompt, \\\"Prompt must instruct: do not translate the quoted context\\\"\\n        assert \\\"session context\\\" in prompt, \\\"Prompt must name the session context block\\\"\\n\\n\\nclass TestFileQuestionDisambiguationStillHolds:\\n    \\\"\\\"\\\"Regression guard \u2014 the original file-question disambiguation rule must survive the Slice 4 edits.\\\"\\\"\\\"\\n\\n    def test_translation_prompt_should_include_disambiguation_rule_for_file_question(self):\\n        \\\"\\\"\\\"`how do I save a file?` is a Langflow question, not a file action.\\\"\\\"\\\"\\n        prompt = TRANSLATION_PROMPT\\n        # Either as an explicit rule line OR as a question example.\\n        rule_or_example = (\\n            \\\"how do I save\\\" in prompt.lower()\\n            or \\\"how to save a file\\\" in prompt.lower()\\n            or \\\"how do i create a file\\\" in prompt.lower()\\n        )\\n        assert rule_or_example, (\\n            \\\"Prompt should disambiguate 'how do I save/create a file?' as question, not manage_files\\\"\\n        )\\n\\n\\nclass TestRunFlowIntentDeclared:\\n    \\\"\\\"\\\"Bugfix \u2014 run/execute/test the flow is its own intent (run_flow), not build_flow.\\\"\\\"\\\"\\n\\n    def test_prompt_declares_run_flow_intent(self):\\n        prompt = TRANSLATION_PROMPT\\n        assert '\\\"run_flow\\\"' in prompt, \\\"TRANSLATION_PROMPT must declare the run_flow intent\\\"\\n        m = re.search(r'\\\"intent\\\":\\\\s*\\\"<([^\\\"]+)>\\\"', prompt)\\n        assert m is not None\\n        assert \\\"run_flow\\\" in m.group(1).split(\\\"|\\\"), f\\\"run_flow must be in the output union, got: {m.group(1)}\\\"\\n\\n    def test_prompt_has_run_flow_examples(self):\\n        prompt = TRANSLATION_PROMPT\\n        examples = re.findall(\\n            r'Output:\\\\s*\\\\{\\\\{\\\"translation\\\":\\\\s*\\\"([^\\\"]+)\\\",\\\\s*\\\"intent\\\":\\\\s*\\\"run_flow\\\"\\\\}\\\\}',\\n            prompt,\\n        )\\n        assert examples, \\\"Expected at least one run_flow example\\\"\\n        assert any(re.search(r\\\"\\\\b(run|execute|test)\\\\b\\\", ex, re.IGNORECASE) for ex in examples), (\\n            f\\\"run_flow examples should use run/execute/test verbs, got: {examples}\\\"\\n        )\\n\\n    def test_run_examples_are_not_classified_as_build_flow(self):\\n        prompt = TRANSLATION_PROMPT\\n        blocks = re.findall(\\n            r'Input:\\\\s*\\\"([^\\\"]+)\\\"\\\\s*\\\\nOutput:\\\\s*\\\\{\\\\{\\\"translation\\\":\\\\s*\\\"[^\\\"]+\\\",\\\\s*\\\"intent\\\":\\\\s*\\\"([^\\\"]+)\\\"\\\\}\\\\}',\\n            prompt,\\n        )\\n        run_phrase = re.compile(r\\\"\\\\b(rode o flow|run the flow|execute o flow|execute the flow)\\\\b\\\", re.IGNORECASE)\\n        offenders = [(i, intent) for i, intent in blocks if intent == \\\"build_flow\\\" and run_phrase.search(i)]\\n        assert not offenders, f\\\"run-the-flow phrasings must be run_flow, not build_flow: {offenders}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/flows/test_translation_flow_requested_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"74dae0182bfa76d7bd7bf44ccfef23c2eae5469662c78614729c091fd6b12be6\",\"content\":\"\\\"\\\"\\\"Prompt-contract for extracting the user's explicitly-named model.\\n\\nThe actual extraction is performed by an LLM at runtime; these tests assert the\\nprompt is the executable spec \u2014 it must declare ``requested_model`` /\\n``requested_provider`` in the output format and teach (by example) to fill them\\nONLY when the user names a model, leaving them empty otherwise.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport re\\n\\nfrom langflow.agentic.flows.translation_flow import TRANSLATION_PROMPT\\n\\n\\ndef test_prompt_should_declare_requested_model_in_output_format():\\n    assert \\\"requested_model\\\" in TRANSLATION_PROMPT\\n    assert \\\"requested_provider\\\" in TRANSLATION_PROMPT\\n\\n\\ndef test_prompt_should_include_an_example_that_names_a_model():\\n    # At least one example Output JSON carries a non-empty requested_model.\\n    named = re.findall(r'\\\"requested_model\\\":\\\\s*\\\"([^\\\"]+)\\\"', TRANSLATION_PROMPT)\\n    assert any(v.strip() for v in named), (\\n        f\\\"Expected at least one example with a populated requested_model, got: {named}\\\"\\n    )\\n\\n\\ndef test_prompt_should_include_an_example_with_empty_model_when_none_named():\\n    # And at least one example where no model is named (empty string), so the\\n    # LLM learns not to hallucinate a model for plain requests.\\n    assert '\\\"requested_model\\\": \\\"\\\"' in TRANSLATION_PROMPT\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/helpers/test_assistant_workspace.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0ad860da2e77bb21aa1b18cd961b165d327ac0a4ceb499e7cbb8b2e76064214b\",\"content\":\"\\\"\\\"\\\"Tests for resolve_assistant_fs_root \u2014 assistant workspace path resolution.\\n\\nForward-compatible with PR #13031 (per-user FileSystemTool isolation):\\n- Env var name (LANGFLOW_FS_TOOL_BASE_DIR) and default path (~/.langflow/fs_tool/fs_sandbox)\\n  match the contract that PR #13031 introduces.\\n- When PR #13031 ships its isolation module, this resolver returns None so the\\n  flow_preparation injector skips writing root_path and lets the component\\n  resolve its own per-user namespace.\\n\\\"\\\"\\\"\\n\\nimport importlib.machinery\\nimport importlib.util\\nimport sys\\n\\nimport pytest\\nfrom langflow.agentic.helpers.assistant_workspace import (\\n    BASE_DIR_ENV,\\n    DEFAULT_BASE_SUBPATH,\\n    ISOLATION_MODULE,\\n    resolve_assistant_fs_root,\\n)\\n\\n\\nclass TestResolveAssistantFsRoot:\\n    \\\"\\\"\\\"Resolution order: skip if isolation module is present \u2192\\n    env var (expanded, stripped) \u2192 ~/.langflow/fs_tool/fs_sandbox default.\\n    Always mkdir when a path is returned.\\n    \\\"\\\"\\\"  # noqa: D205\\n\\n    @pytest.fixture(autouse=True)\\n    def _isolate_env(self, monkeypatch, tmp_path):\\n        monkeypatch.delenv(BASE_DIR_ENV, raising=False)\\n        # Pin HOME so the default path test is portable.\\n        fake_home = tmp_path / \\\"home\\\"\\n        fake_home.mkdir()\\n        monkeypatch.setenv(\\\"HOME\\\", str(fake_home))\\n        monkeypatch.setenv(\\\"USERPROFILE\\\", str(fake_home))\\n        # Make sure the isolation module is NOT importable by default\\n        # (so we test the legacy path; one test below puts it back).\\n        # The module ships on disk once PR #13031 lands, so `find_spec`\\n        # would discover it via the filesystem \u2014 stub it out to force\\n        # the legacy resolution path.\\n        monkeypatch.delitem(sys.modules, ISOLATION_MODULE, raising=False)\\n        original_find_spec = importlib.util.find_spec\\n        monkeypatch.setattr(\\n            importlib.util,\\n            \\\"find_spec\\\",\\n            lambda name, *a, **kw: (None if name == ISOLATION_MODULE else original_find_spec(name, *a, **kw)),\\n        )\\n        return fake_home\\n\\n    def test_should_resolve_to_default_when_env_unset(self, _isolate_env):  # noqa: PT019\\n        result = resolve_assistant_fs_root()\\n\\n        assert result == (_isolate_env / DEFAULT_BASE_SUBPATH).resolve()\\n\\n    def test_should_resolve_to_env_var_when_set(self, tmp_path, monkeypatch):\\n        target = tmp_path / \\\"custom\\\"\\n        monkeypatch.setenv(BASE_DIR_ENV, str(target))\\n\\n        result = resolve_assistant_fs_root()\\n\\n        assert result == target.resolve()\\n\\n    def test_should_expanduser_in_env_var(self, _isolate_env, monkeypatch):  # noqa: PT019\\n        monkeypatch.setenv(BASE_DIR_ENV, \\\"~/my-workspace\\\")\\n\\n        result = resolve_assistant_fs_root()\\n\\n        assert result == (_isolate_env / \\\"my-workspace\\\").resolve()\\n\\n    def test_should_create_workspace_dir_if_missing(self, tmp_path, monkeypatch):\\n        target = tmp_path / \\\"new-dir\\\"\\n        assert not target.exists()\\n        monkeypatch.setenv(BASE_DIR_ENV, str(target))\\n\\n        resolve_assistant_fs_root()\\n\\n        assert target.exists()\\n        assert target.is_dir()\\n\\n    def test_should_be_idempotent_when_workspace_already_exists(self, tmp_path, monkeypatch):\\n        target = tmp_path / \\\"existing\\\"\\n        target.mkdir()\\n        sentinel = target / \\\"sentinel.txt\\\"\\n        sentinel.write_text(\\\"keep me\\\", encoding=\\\"utf-8\\\")\\n        monkeypatch.setenv(BASE_DIR_ENV, str(target))\\n\\n        result = resolve_assistant_fs_root()\\n\\n        assert result == target.resolve()\\n        assert sentinel.read_text(encoding=\\\"utf-8\\\") == \\\"keep me\\\"\\n\\n    def test_should_strip_whitespace_from_env_var(self, tmp_path, monkeypatch):\\n        target = tmp_path / \\\"padded\\\"\\n        monkeypatch.setenv(BASE_DIR_ENV, f\\\"  {target}  \\\")\\n\\n        result = resolve_assistant_fs_root()\\n\\n        assert result == target.resolve()\\n\\n    def test_should_fall_back_to_default_when_env_var_is_blank(self, _isolate_env, monkeypatch):  # noqa: PT019\\n        monkeypatch.setenv(BASE_DIR_ENV, \\\"   \\\")\\n\\n        result = resolve_assistant_fs_root()\\n\\n        assert result == (_isolate_env / DEFAULT_BASE_SUBPATH).resolve()\\n\\n    def test_should_create_parent_dirs_when_missing(self, tmp_path, monkeypatch):\\n        target = tmp_path / \\\"deep\\\" / \\\"nested\\\" / \\\"workspace\\\"\\n        monkeypatch.setenv(BASE_DIR_ENV, str(target))\\n\\n        result = resolve_assistant_fs_root()\\n\\n        assert result == target.resolve()\\n        assert target.is_dir()\\n\\n    def test_should_return_none_when_isolation_module_is_present(self, monkeypatch, tmp_path):\\n        \\\"\\\"\\\"When PR #13031 lands the FileSystemTool self-resolves a per-user namespace.\\n\\n        We detect that by importing the isolation module shipped in #13031 and,\\n        if it's present, return None \u2014 telling the flow_preparation injector\\n        to skip writing root_path so the component handles its own resolution.\\n        \\\"\\\"\\\"\\n        # Even with the env var set we must skip \u2014 once isolation is active,\\n        # any injected root_path would be misinterpreted as a sub_path.\\n        monkeypatch.setenv(BASE_DIR_ENV, str(tmp_path / \\\"ignored\\\"))\\n        # Simulate the isolation module being importable.\\n        fake_module = type(sys)(ISOLATION_MODULE)\\n        monkeypatch.setitem(sys.modules, ISOLATION_MODULE, fake_module)\\n        # Patch importlib.util.find_spec to report the module as available.\\n        original = importlib.util.find_spec\\n        monkeypatch.setattr(\\n            importlib.util,\\n            \\\"find_spec\\\",\\n            lambda name, *a, **kw: (\\n                importlib.machinery.ModuleSpec(name, None) if name == ISOLATION_MODULE else original(name, *a, **kw)\\n            ),\\n        )\\n\\n        result = resolve_assistant_fs_root()\\n\\n        assert result is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/helpers/test_flow_loader.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"552480e56fbc4c78fc522e4c446360ed9ed1f7d7ff1ab0e52c9e1531aecd9b80\",\"content\":\"\\\"\\\"\\\"Tests for flow loader module.\\n\\nTests _temporary_sys_path context manager, resolve_flow_path,\\n_load_graph_from_python, and load_graph_for_execution functions.\\n\\\"\\\"\\\"\\n\\nimport sys\\nfrom pathlib import Path\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.agentic.services.helpers.flow_loader import (\\n    _load_graph_from_python,\\n    _temporary_sys_path,\\n    load_graph_for_execution,\\n    resolve_flow_path,\\n)\\nfrom lfx.utils.flow_validation import CustomComponentValidationError\\n\\n\\nclass TestTemporarySysPath:\\n    \\\"\\\"\\\"Tests for _temporary_sys_path context manager.\\\"\\\"\\\"\\n\\n    def test_should_add_path_to_sys_path_temporarily(self):\\n        \\\"\\\"\\\"Should add path to sys.path and remove after context.\\\"\\\"\\\"\\n        test_path = \\\"/some/unique/test/path\\\"\\n        assert test_path not in sys.path\\n\\n        with _temporary_sys_path(test_path):\\n            assert test_path in sys.path\\n\\n        assert test_path not in sys.path\\n\\n    def test_should_not_duplicate_existing_path(self):\\n        \\\"\\\"\\\"Should not add path if already in sys.path.\\\"\\\"\\\"\\n        existing_path = sys.path[0]\\n        original_count = sys.path.count(existing_path)\\n\\n        with _temporary_sys_path(existing_path):\\n            assert sys.path.count(existing_path) == original_count\\n\\n        assert sys.path.count(existing_path) == original_count\\n\\n    def test_should_remove_path_even_on_exception(self):\\n        \\\"\\\"\\\"Should remove path from sys.path even if exception occurs.\\\"\\\"\\\"\\n        test_path = \\\"/another/unique/test/path\\\"\\n        assert test_path not in sys.path\\n\\n        try:\\n            with _temporary_sys_path(test_path):\\n                assert test_path in sys.path\\n                msg = \\\"test error\\\"\\n                raise ValueError(msg)\\n        except ValueError:\\n            pass\\n\\n        assert test_path not in sys.path\\n\\n\\nclass TestResolveFlowPath:\\n    \\\"\\\"\\\"Tests for resolve_flow_path function.\\\"\\\"\\\"\\n\\n    def test_should_return_json_path_for_explicit_json_extension(self, tmp_path):\\n        \\\"\\\"\\\"Should return JSON path when .json extension is explicit.\\\"\\\"\\\"\\n        json_file = tmp_path / \\\"test.json\\\"\\n        json_file.write_text(\\\"{}\\\")\\n\\n        with patch(\\\"langflow.agentic.services.helpers.flow_loader.FLOWS_BASE_PATH\\\", tmp_path):\\n            result_path, result_type = resolve_flow_path(\\\"test.json\\\")\\n\\n            assert result_type == \\\"json\\\"\\n            assert result_path == json_file\\n\\n    def test_should_return_python_path_for_explicit_py_extension(self, tmp_path):\\n        \\\"\\\"\\\"Should return Python path when .py extension is explicit.\\\"\\\"\\\"\\n        py_file = tmp_path / \\\"test.py\\\"\\n        py_file.write_text(\\\"# test\\\")\\n\\n        with patch(\\\"langflow.agentic.services.helpers.flow_loader.FLOWS_BASE_PATH\\\", tmp_path):\\n            result_path, result_type = resolve_flow_path(\\\"test.py\\\")\\n\\n            assert result_type == \\\"python\\\"\\n            assert result_path == py_file\\n\\n    def test_should_prefer_python_over_json_when_both_exist(self, tmp_path):\\n        \\\"\\\"\\\"Should prefer .py over .json when auto-detecting.\\\"\\\"\\\"\\n        py_file = tmp_path / \\\"test.py\\\"\\n        py_file.write_text(\\\"# test\\\")\\n        json_file = tmp_path / \\\"test.json\\\"\\n        json_file.write_text(\\\"{}\\\")\\n\\n        with patch(\\\"langflow.agentic.services.helpers.flow_loader.FLOWS_BASE_PATH\\\", tmp_path):\\n            result_path, result_type = resolve_flow_path(\\\"test\\\")\\n\\n            assert result_type == \\\"python\\\"\\n            assert result_path == py_file\\n\\n    def test_should_fallback_to_json_when_python_not_found(self, tmp_path):\\n        \\\"\\\"\\\"Should use .json when .py doesn't exist.\\\"\\\"\\\"\\n        json_file = tmp_path / \\\"test.json\\\"\\n        json_file.write_text(\\\"{}\\\")\\n\\n        with patch(\\\"langflow.agentic.services.helpers.flow_loader.FLOWS_BASE_PATH\\\", tmp_path):\\n            result_path, result_type = resolve_flow_path(\\\"test\\\")\\n\\n            assert result_type == \\\"json\\\"\\n            assert result_path == json_file\\n\\n    def test_should_reject_filename_with_path_traversal_sequences(self, tmp_path):\\n        \\\"\\\"\\\"Should reject filenames containing '..' before any path construction.\\\"\\\"\\\"\\n        with patch(\\\"langflow.agentic.services.helpers.flow_loader.FLOWS_BASE_PATH\\\", tmp_path):\\n            with pytest.raises(HTTPException) as exc_info:\\n                resolve_flow_path(\\\"../../etc/passwd\\\")\\n\\n            assert exc_info.value.status_code == 400\\n            assert \\\"Invalid flow filename\\\" in exc_info.value.detail\\n\\n    def test_should_reject_filename_with_backslash_traversal(self, tmp_path):\\n        \\\"\\\"\\\"Should reject filenames containing backslash path separators.\\\"\\\"\\\"\\n        with patch(\\\"langflow.agentic.services.helpers.flow_loader.FLOWS_BASE_PATH\\\", tmp_path):\\n            with pytest.raises(HTTPException) as exc_info:\\n                resolve_flow_path(\\\"..\\\\\\\\..\\\\\\\\etc\\\\\\\\passwd\\\")\\n\\n            assert exc_info.value.status_code == 400\\n            assert \\\"Invalid flow filename\\\" in exc_info.value.detail\\n\\n    def test_should_raise_404_when_flow_not_found(self, tmp_path):\\n        \\\"\\\"\\\"Should raise HTTPException 404 when flow file doesn't exist.\\\"\\\"\\\"\\n        with patch(\\\"langflow.agentic.services.helpers.flow_loader.FLOWS_BASE_PATH\\\", tmp_path):\\n            with pytest.raises(HTTPException) as exc_info:\\n                resolve_flow_path(\\\"missing.json\\\")\\n\\n            assert exc_info.value.status_code == 404\\n            assert \\\"not found\\\" in exc_info.value.detail.lower()\\n\\n\\nclass TestLoadGraphFromPython:\\n    \\\"\\\"\\\"Tests for _load_graph_from_python function.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_load_graph_from_get_graph_function(self):\\n        \\\"\\\"\\\"Should load graph by calling get_graph() function.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_module = MagicMock()\\n        mock_module.get_graph = MagicMock(return_value=mock_graph)\\n\\n        with (\\n            patch(\\\"importlib.util.spec_from_file_location\\\") as mock_spec_from_file,\\n            patch(\\\"importlib.util.module_from_spec\\\") as mock_module_from_spec,\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader._temporary_sys_path\\\"),\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader.validate_flow_for_current_settings\\\") as mock_validate,\\n        ):\\n            mock_spec = MagicMock()\\n            mock_spec.loader = MagicMock()\\n            mock_spec_from_file.return_value = mock_spec\\n            mock_module_from_spec.return_value = mock_module\\n\\n            result = await _load_graph_from_python(Path(\\\"/test/flow.py\\\"))\\n\\n            assert result == mock_graph\\n            mock_module.get_graph.assert_called_once()\\n            mock_validate.assert_called_once_with(mock_graph)\\n\\n    @pytest.mark.asyncio\\n    async def test_should_pass_provider_params_to_get_graph(self):\\n        \\\"\\\"\\\"Should pass provider, model_name, api_key_var to get_graph when accepted.\\\"\\\"\\\"\\n        import inspect\\n\\n        mock_graph = MagicMock()\\n\\n        def mock_get_graph(\\n            provider=None,  # noqa: ARG001\\n            model_name=None,  # noqa: ARG001\\n            api_key_var=None,  # noqa: ARG001\\n        ):\\n            return mock_graph\\n\\n        mock_module = MagicMock()\\n        mock_module.get_graph = mock_get_graph\\n\\n        with (\\n            patch(\\\"importlib.util.spec_from_file_location\\\") as mock_spec_from_file,\\n            patch(\\\"importlib.util.module_from_spec\\\") as mock_module_from_spec,\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader._temporary_sys_path\\\"),\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader.validate_flow_for_current_settings\\\"),\\n            patch.object(inspect, \\\"signature\\\", return_value=inspect.signature(mock_get_graph)),\\n        ):\\n            mock_spec = MagicMock()\\n            mock_spec.loader = MagicMock()\\n            mock_spec_from_file.return_value = mock_spec\\n            mock_module_from_spec.return_value = mock_module\\n\\n            result = await _load_graph_from_python(\\n                Path(\\\"/test/flow.py\\\"),\\n                provider=\\\"OpenAI\\\",\\n                model_name=\\\"gpt-4\\\",\\n                api_key_var=\\\"OPENAI_API_KEY\\\",\\n            )\\n\\n            assert result == mock_graph\\n\\n    @pytest.mark.asyncio\\n    async def test_should_support_async_get_graph(self):\\n        \\\"\\\"\\\"Should support async get_graph() functions.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n\\n        async def mock_async_get_graph():\\n            return mock_graph\\n\\n        mock_module = MagicMock()\\n        mock_module.get_graph = mock_async_get_graph\\n\\n        with (\\n            patch(\\\"importlib.util.spec_from_file_location\\\") as mock_spec_from_file,\\n            patch(\\\"importlib.util.module_from_spec\\\") as mock_module_from_spec,\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader._temporary_sys_path\\\"),\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader.validate_flow_for_current_settings\\\"),\\n        ):\\n            mock_spec = MagicMock()\\n            mock_spec.loader = MagicMock()\\n            mock_spec_from_file.return_value = mock_spec\\n            mock_module_from_spec.return_value = mock_module\\n\\n            result = await _load_graph_from_python(Path(\\\"/test/flow.py\\\"))\\n\\n            assert result == mock_graph\\n\\n    @pytest.mark.asyncio\\n    async def test_should_fallback_to_graph_variable(self):\\n        \\\"\\\"\\\"Should use 'graph' variable if get_graph() not defined.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_module = MagicMock(spec=[\\\"graph\\\"])\\n        mock_module.graph = mock_graph\\n\\n        with (\\n            patch(\\\"importlib.util.spec_from_file_location\\\") as mock_spec_from_file,\\n            patch(\\\"importlib.util.module_from_spec\\\") as mock_module_from_spec,\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader._temporary_sys_path\\\"),\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader.validate_flow_for_current_settings\\\") as mock_validate,\\n        ):\\n            mock_spec = MagicMock()\\n            mock_spec.loader = MagicMock()\\n            mock_spec_from_file.return_value = mock_spec\\n            mock_module_from_spec.return_value = mock_module\\n\\n            result = await _load_graph_from_python(Path(\\\"/test/flow.py\\\"))\\n\\n            assert result == mock_graph\\n            mock_validate.assert_called_once_with(mock_graph)\\n\\n    @pytest.mark.asyncio\\n    async def test_should_raise_validation_error_for_blocked_python_graph(self):\\n        \\\"\\\"\\\"Should propagate custom-component validation errors for Python flows.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_module = MagicMock()\\n        mock_module.get_graph = MagicMock(return_value=mock_graph)\\n\\n        with (\\n            patch(\\\"importlib.util.spec_from_file_location\\\") as mock_spec_from_file,\\n            patch(\\\"importlib.util.module_from_spec\\\") as mock_module_from_spec,\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader._temporary_sys_path\\\"),\\n            patch(\\n                \\\"langflow.agentic.services.helpers.flow_loader.validate_flow_for_current_settings\\\",\\n                side_effect=CustomComponentValidationError(\\n                    \\\"Flow build blocked: custom components are not allowed: Bad (node)\\\"\\n                ),\\n            ),\\n        ):\\n            mock_spec = MagicMock()\\n            mock_spec.loader = MagicMock()\\n            mock_spec_from_file.return_value = mock_spec\\n            mock_module_from_spec.return_value = mock_module\\n\\n            with pytest.raises(CustomComponentValidationError, match=\\\"custom components are not allowed\\\"):\\n                await _load_graph_from_python(Path(\\\"/test/flow.py\\\"))\\n\\n    @pytest.mark.asyncio\\n    async def test_should_raise_500_when_no_get_graph_or_graph(self):\\n        \\\"\\\"\\\"Should raise HTTPException 500 when neither get_graph nor graph exists.\\\"\\\"\\\"\\n        mock_module = MagicMock(spec=[])\\n\\n        with (\\n            patch(\\\"importlib.util.spec_from_file_location\\\") as mock_spec_from_file,\\n            patch(\\\"importlib.util.module_from_spec\\\") as mock_module_from_spec,\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader._temporary_sys_path\\\"),\\n        ):\\n            mock_spec = MagicMock()\\n            mock_spec.loader = MagicMock()\\n            mock_spec_from_file.return_value = mock_spec\\n            mock_module_from_spec.return_value = mock_module\\n\\n            with pytest.raises(HTTPException) as exc_info:\\n                await _load_graph_from_python(Path(\\\"/test/flow.py\\\"))\\n\\n            assert exc_info.value.status_code == 500\\n            assert \\\"get_graph()\\\" in exc_info.value.detail\\n\\n    @pytest.mark.asyncio\\n    async def test_should_raise_500_when_spec_is_none(self):\\n        \\\"\\\"\\\"Should raise HTTPException 500 when spec cannot be loaded.\\\"\\\"\\\"\\n        with patch(\\\"importlib.util.spec_from_file_location\\\", return_value=None):\\n            with pytest.raises(HTTPException) as exc_info:\\n                await _load_graph_from_python(Path(\\\"/test/flow.py\\\"))\\n\\n            assert exc_info.value.status_code == 500\\n            assert \\\"Could not load flow module\\\" in exc_info.value.detail\\n\\n    @pytest.mark.asyncio\\n    async def test_should_raise_500_on_module_execution_error(self):\\n        \\\"\\\"\\\"Should raise HTTPException 500 when module execution fails.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"importlib.util.spec_from_file_location\\\") as mock_spec_from_file,\\n            patch(\\\"importlib.util.module_from_spec\\\") as mock_module_from_spec,\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader._temporary_sys_path\\\"),\\n        ):\\n            mock_spec = MagicMock()\\n            mock_spec.loader.exec_module.side_effect = ImportError(\\\"module error\\\")\\n            mock_spec_from_file.return_value = mock_spec\\n            mock_module_from_spec.return_value = MagicMock()\\n\\n            with pytest.raises(HTTPException) as exc_info:\\n                await _load_graph_from_python(Path(\\\"/test/flow.py\\\"))\\n\\n            assert exc_info.value.status_code == 500\\n            assert \\\"Error loading flow module\\\" in exc_info.value.detail\\n\\n    @pytest.mark.asyncio\\n    async def test_should_cleanup_sys_modules_on_success(self):\\n        \\\"\\\"\\\"Should remove module from sys.modules after loading.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_module = MagicMock()\\n        mock_module.get_graph = MagicMock(return_value=mock_graph)\\n\\n        with (\\n            patch(\\\"importlib.util.spec_from_file_location\\\") as mock_spec_from_file,\\n            patch(\\\"importlib.util.module_from_spec\\\") as mock_module_from_spec,\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader._temporary_sys_path\\\"),\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader.validate_flow_for_current_settings\\\"),\\n            patch.dict(sys.modules, {}, clear=False),\\n        ):\\n            mock_spec = MagicMock()\\n            mock_spec.loader = MagicMock()\\n            mock_spec_from_file.return_value = mock_spec\\n            mock_module_from_spec.return_value = mock_module\\n\\n            await _load_graph_from_python(Path(\\\"/test/test_module.py\\\"))\\n\\n            assert \\\"test_module\\\" not in sys.modules\\n\\n\\nclass TestLoadGraphForExecution:\\n    \\\"\\\"\\\"Tests for load_graph_for_execution function.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_use_python_loader_for_python_type(self):\\n        \\\"\\\"\\\"Should use _load_graph_from_python for python flow type.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n\\n        with patch(\\n            \\\"langflow.agentic.services.helpers.flow_loader._load_graph_from_python\\\",\\n            new_callable=AsyncMock,\\n            return_value=mock_graph,\\n        ) as mock_load:\\n            result = await load_graph_for_execution(\\n                Path(\\\"/test/flow.py\\\"),\\n                \\\"python\\\",\\n                provider=\\\"OpenAI\\\",\\n                model_name=\\\"gpt-4\\\",\\n            )\\n\\n            mock_load.assert_called_once_with(\\n                Path(\\\"/test/flow.py\\\"),\\n                \\\"OpenAI\\\",\\n                \\\"gpt-4\\\",\\n                None,\\n                None,\\n            )\\n            assert result == mock_graph\\n\\n    @pytest.mark.asyncio\\n    async def test_should_use_json_loader_for_json_type(self):\\n        \\\"\\\"\\\"Should use load_and_prepare_flow + aload_flow_from_json for json type.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n\\n        with (\\n            patch(\\n                \\\"langflow.agentic.services.helpers.flow_loader.load_and_prepare_flow\\\",\\n                return_value='{\\\"data\\\": {\\\"nodes\\\": []}}',\\n            ) as mock_prepare,\\n            patch(\\n                \\\"langflow.agentic.services.helpers.flow_loader.aload_flow_from_json\\\",\\n                new_callable=AsyncMock,\\n                return_value=mock_graph,\\n            ) as mock_load_json,\\n        ):\\n            result = await load_graph_for_execution(\\n                Path(\\\"/test/flow.json\\\"),\\n                \\\"json\\\",\\n                provider=\\\"OpenAI\\\",\\n                model_name=\\\"gpt-4\\\",\\n            )\\n\\n            mock_prepare.assert_called_once()\\n            mock_load_json.assert_called_once()\\n            assert result == mock_graph\\n\\n    @pytest.mark.asyncio\\n    async def test_should_pass_api_key_var_to_loader(self):\\n        \\\"\\\"\\\"Should pass api_key_var parameter to the appropriate loader.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n\\n        with patch(\\n            \\\"langflow.agentic.services.helpers.flow_loader._load_graph_from_python\\\",\\n            new_callable=AsyncMock,\\n            return_value=mock_graph,\\n        ) as mock_load:\\n            await load_graph_for_execution(\\n                Path(\\\"/test/flow.py\\\"),\\n                \\\"python\\\",\\n                provider=\\\"Anthropic\\\",\\n                model_name=\\\"claude-3\\\",\\n                api_key_var=\\\"ANTHROPIC_API_KEY\\\",\\n            )\\n\\n            mock_load.assert_called_once_with(\\n                Path(\\\"/test/flow.py\\\"),\\n                \\\"Anthropic\\\",\\n                \\\"claude-3\\\",\\n                \\\"ANTHROPIC_API_KEY\\\",\\n                None,\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_should_forward_provider_vars_to_python_loader(self):\\n        \\\"\\\"\\\"The step budget rides in provider_vars \u2014 it must reach the Python loader intact.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        provider_vars = {\\\"ITERATIONS_LIMIT\\\": \\\"2\\\", \\\"WATSONX_URL\\\": \\\"https://example.com\\\"}\\n\\n        with patch(\\n            \\\"langflow.agentic.services.helpers.flow_loader._load_graph_from_python\\\",\\n            new_callable=AsyncMock,\\n            return_value=mock_graph,\\n        ) as mock_load:\\n            await load_graph_for_execution(\\n                Path(\\\"/test/flow.py\\\"),\\n                \\\"python\\\",\\n                provider=\\\"OpenAI\\\",\\n                model_name=\\\"gpt-4\\\",\\n                api_key_var=\\\"OPENAI_API_KEY\\\",\\n                provider_vars=provider_vars,\\n            )\\n\\n            mock_load.assert_called_once_with(\\n                Path(\\\"/test/flow.py\\\"),\\n                \\\"OpenAI\\\",\\n                \\\"gpt-4\\\",\\n                \\\"OPENAI_API_KEY\\\",\\n                provider_vars,\\n            )\\n\\n\\nclass TestBugsAndEdgeCases:\\n    \\\"\\\"\\\"Tests that challenge the code \u2014 exposing real bugs and untested edge cases.\\\"\\\"\\\"\\n\\n    def test_resolve_flow_path_traversal_escape(self, tmp_path):\\n        \\\"\\\"\\\"resolve_flow_path should reject paths that traverse outside FLOWS_BASE_PATH.\\\"\\\"\\\"\\n        flows_dir = tmp_path / \\\"flows\\\"\\n        flows_dir.mkdir()\\n        secret = tmp_path / \\\"secret.json\\\"\\n        secret.write_text('{\\\"secret\\\": true}')\\n\\n        with patch(\\\"langflow.agentic.services.helpers.flow_loader.FLOWS_BASE_PATH\\\", flows_dir):\\n            with pytest.raises(HTTPException) as exc_info:\\n                resolve_flow_path(\\\"../secret.json\\\")\\n\\n            assert exc_info.value.status_code == 400\\n\\n    def test_resolve_flow_path_empty_string_returns_directory(self, tmp_path):\\n        \\\"\\\"\\\"L78: resolve_flow_path('') returns FLOWS_BASE_PATH directory as a 'json' file.\\n\\n        Empty string \u2192 base_name = '' \u2192 no .py/.json match \u2192 direct_path = FLOWS_BASE_PATH\\n        \u2192 exists() = True (it's a directory) \u2192 returned as 'json'.\\n        Downstream code will crash trying to read a directory as JSON.\\n        \\\"\\\"\\\"\\n        with patch(\\\"langflow.agentic.services.helpers.flow_loader.FLOWS_BASE_PATH\\\", tmp_path):\\n            result_path, result_type = resolve_flow_path(\\\"\\\")\\n\\n        assert result_path == tmp_path  # Returns directory as if it were a file\\n        assert result_type == \\\"json\\\"\\n\\n    def test_resolve_flow_path_only_extension_literal(self, tmp_path):\\n        \\\"\\\"\\\"resolve_flow_path('.json') treats it as literal filename, not just extension.\\\"\\\"\\\"\\n        # File literally named '.json'\\n        dot_json = tmp_path / \\\".json\\\"\\n        dot_json.write_text(\\\"{}\\\")\\n\\n        with patch(\\\"langflow.agentic.services.helpers.flow_loader.FLOWS_BASE_PATH\\\", tmp_path):\\n            result_path, result_type = resolve_flow_path(\\\".json\\\")\\n\\n        assert result_path == dot_json\\n        assert result_type == \\\"json\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_load_graph_returns_none_from_get_graph(self):\\n        \\\"\\\"\\\"get_graph() returning None is passed through without validation.\\n\\n        No check that the returned value is actually a Graph instance.\\n        Downstream code will crash on None.\\n        \\\"\\\"\\\"\\n        mock_module = MagicMock()\\n        mock_module.get_graph = MagicMock(return_value=None)\\n\\n        with (\\n            patch(\\\"importlib.util.spec_from_file_location\\\") as mock_spec_from_file,\\n            patch(\\\"importlib.util.module_from_spec\\\") as mock_module_from_spec,\\n            patch(\\\"langflow.agentic.services.helpers.flow_loader._temporary_sys_path\\\"),\\n        ):\\n            mock_spec = MagicMock()\\n            mock_spec.loader = MagicMock()\\n            mock_spec_from_file.return_value = mock_spec\\n            mock_module_from_spec.return_value = mock_module\\n\\n            result = await _load_graph_from_python(Path(\\\"/test/flow.py\\\"))\\n\\n        # Documents: None is returned without validation\\n        assert result is None\\n\\n    def test_sys_modules_uses_stem_as_module_name(self):\\n        \\\"\\\"\\\"L110: module_name = flow_path.stem \u2014 files with same stem collide in sys.modules.\\n\\n        Two concurrent requests loading /path/a/flow.py and /path/b/flow.py\\n        both use 'flow' as module_name, creating a race condition in sys.modules.\\n        \\\"\\\"\\\"\\n        path_a = Path(\\\"/path/a/flow.py\\\")\\n        path_b = Path(\\\"/path/b/flow.py\\\")\\n        # Same stem means same key in sys.modules \u2014 concurrent collision\\n        assert path_a.stem == path_b.stem == \\\"flow\\\"\\n\\n    def test_temporary_sys_path_crashes_if_path_removed_during_context(self):\\n        \\\"\\\"\\\"L34: sys.path.remove() raises ValueError if path was removed inside context.\\n\\n        If code inside the context (or another thread) removes the path,\\n        the finally block crashes with ValueError instead of handling gracefully.\\n        \\\"\\\"\\\"\\n        test_path = \\\"/unique/concurrent/removal/test/path\\\"\\n\\n        with (\\n            pytest.raises(ValueError, match=\\\"not in list\\\"),\\n            _temporary_sys_path(test_path),\\n        ):\\n            # Simulate another thread or code removing the path\\n            sys.path.remove(test_path)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_assistant_service_flow_summary.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"294d9af35ae072d7833ab58e7774e4c3430b9e1b04085855f6dda841082dc921\",\"content\":\"\\\"\\\"\\\"Tests for _get_current_flow_summary ownership + error isolation.\\n\\nCovers reviewer findings:\\n- I2: the canvas-context loader must never load a flow the caller does not\\n  own (IDOR \u2014 another user's flow structure leaking into the prompt).\\n- I5: a malformed flow_id must be distinguished from an operational DB\\n  failure \u2014 it is \\\"no context\\\", not an error, and must not hit the DB.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom contextlib import asynccontextmanager\\nfrom uuid import uuid4\\n\\nfrom langflow.agentic.services import assistant_service\\n\\n\\nclass _FakeFlow:\\n    def __init__(self, *, user_id, data, name=\\\"Canvas\\\"):\\n        self.user_id = user_id\\n        self.data = data\\n        self.name = name\\n\\n\\nclass _FakeSession:\\n    def __init__(self, flow):\\n        self._flow = flow\\n\\n    async def get(self, _model, _pk):\\n        return self._flow\\n\\n\\ndef _patch_session(monkeypatch, flow, *, entered_flag=None):\\n    @asynccontextmanager\\n    async def _scope():\\n        if entered_flag is not None:\\n            entered_flag.append(True)\\n        yield _FakeSession(flow)\\n\\n    monkeypatch.setattr(\\\"lfx.services.deps.session_scope\\\", _scope)\\n\\n\\nclass TestFlowSummaryOwnership:\\n    async def test_should_return_none_when_flow_belongs_to_another_user(self, monkeypatch):\\n        # Arrange \u2014 flow owned by user B, requested by user A.\\n        owner_b = uuid4()\\n        caller_a = str(uuid4())\\n        flow = _FakeFlow(user_id=owner_b, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n        _patch_session(monkeypatch, flow)\\n\\n        init_calls: list = []\\n        monkeypatch.setattr(\\n            assistant_service,\\n            \\\"init_working_flow\\\",\\n            lambda *a, **k: init_calls.append((a, k)),\\n        )\\n\\n        # Act\\n        result = await assistant_service._get_current_flow_summary(str(uuid4()), user_id=caller_a)\\n\\n        # Assert \u2014 no cross-user canvas leaked, and the working flow was NOT seeded.\\n        assert result is None\\n        assert init_calls == []\\n\\n    async def test_should_return_summary_when_caller_owns_the_flow(self, monkeypatch):\\n        owner = uuid4()\\n        flow = _FakeFlow(user_id=owner, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n        _patch_session(monkeypatch, flow)\\n        monkeypatch.setattr(assistant_service, \\\"init_working_flow\\\", lambda *_a, **_k: None)\\n        monkeypatch.setattr(assistant_service, \\\"flow_to_spec_summary\\\", lambda _d: \\\"SUMMARY\\\")\\n\\n        result = await assistant_service._get_current_flow_summary(str(uuid4()), user_id=str(owner))\\n\\n        assert result == \\\"SUMMARY\\\"\\n\\n\\nclass TestFlowSummaryBadUuid:\\n    async def test_should_skip_context_without_db_call_when_flow_id_is_not_a_uuid(self, monkeypatch):\\n        entered: list = []\\n        _patch_session(monkeypatch, _FakeFlow(user_id=uuid4(), data={}), entered_flag=entered)\\n\\n        result = await assistant_service._get_current_flow_summary(\\\"not-a-uuid\\\", user_id=str(uuid4()))\\n\\n        # Malformed id \u2192 no context, and the DB session must never be opened.\\n        assert result is None\\n        assert entered == []\\n\\n\\nclass TestFlowSummaryHardCap:\\n    \\\"\\\"\\\"Token-budget safety net: very large canvases must not blow per-turn cost.\\n\\n    ``flow_to_spec_summary`` is best-effort terse, but edge cases (50+ nodes,\\n    long sticky notes, big custom-component code) can produce multi-kB\\n    summaries. The summary is re-sent on every LLM turn, so an unbounded one\\n    multiplies cost geometrically. The hard cap is the safety net; the truncation\\n    marker tells the agent (and any human reading logs) that data was clipped.\\n    \\\"\\\"\\\"\\n\\n    async def test_should_truncate_when_summary_exceeds_max_chars(self, monkeypatch):\\n        from langflow.agentic.services.flow_types import MAX_CANVAS_SUMMARY_CHARS\\n\\n        owner = uuid4()\\n        flow = _FakeFlow(user_id=owner, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n        _patch_session(monkeypatch, flow)\\n        monkeypatch.setattr(assistant_service, \\\"init_working_flow\\\", lambda *_a, **_k: None)\\n        # Simulate a canvas summary that overshoots the cap by 5x.\\n        big_summary = \\\"X\\\" * (MAX_CANVAS_SUMMARY_CHARS * 5)\\n        monkeypatch.setattr(assistant_service, \\\"flow_to_spec_summary\\\", lambda _d: big_summary)\\n\\n        result = await assistant_service._get_current_flow_summary(str(uuid4()), user_id=str(owner))\\n\\n        assert result is not None\\n        assert len(result) <= MAX_CANVAS_SUMMARY_CHARS + len(\\\"\\\\n... [truncated]\\\")\\n        assert result.endswith(\\\"[truncated]\\\"), \\\"expected truncation marker so the agent knows data was clipped\\\"\\n\\n    async def test_should_pass_through_when_summary_is_within_cap(self, monkeypatch):\\n        from langflow.agentic.services.flow_types import MAX_CANVAS_SUMMARY_CHARS\\n\\n        owner = uuid4()\\n        flow = _FakeFlow(user_id=owner, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n        _patch_session(monkeypatch, flow)\\n        monkeypatch.setattr(assistant_service, \\\"init_working_flow\\\", lambda *_a, **_k: None)\\n        small_summary = \\\"Y\\\" * (MAX_CANVAS_SUMMARY_CHARS - 1)\\n        monkeypatch.setattr(assistant_service, \\\"flow_to_spec_summary\\\", lambda _d: small_summary)\\n\\n        result = await assistant_service._get_current_flow_summary(str(uuid4()), user_id=str(owner))\\n\\n        # Under-cap summaries must be byte-identical: no truncation marker, no clipping.\\n        assert result == small_summary\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_assistant_service_flow_verification.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"afcc8b6924f38eb9b78479752a82eb0e6ca1c391e5afa0a0dfa007801a0a918a\",\"content\":\"\\\"\\\"\\\"Slice 4 \u2014 post-build flow verification wired into the live turn.\\n\\nCharacterization first (the no-FLOW_ID path must stay byte-identical),\\nthen the new behavior: a built flow whose real run fails with a\\nnon-fixable error is delivered with an honest caveat \u2014 never as a\\nconfident success \u2014 and the kill switch restores legacy behavior.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom langflow.agentic.services.assistant_service import execute_flow_with_validation_streaming\\nfrom langflow.agentic.services.flow_types import IntentResult\\n\\nMODULE = \\\"langflow.agentic.services.assistant_service\\\"\\n\\n\\ndef _intent(intent):\\n    return IntentResult(intent=intent, translation=\\\"build a flow\\\")\\n\\n\\ndef _stream_end():\\n    async def gen():\\n        yield \\\"end\\\", {\\\"result\\\": \\\"Flow built.\\\"}\\n\\n    return gen()\\n\\n\\ndef _drain_set_flow_once():\\n    \\\"\\\"\\\"drain_flow_events: emit one set_flow on the first call, then [].\\\"\\\"\\\"\\n    state = {\\\"done\\\": False}\\n\\n    def _drain():\\n        if state[\\\"done\\\"]:\\n            return []\\n        state[\\\"done\\\"] = True\\n        return [{\\\"action\\\": \\\"set_flow\\\"}]\\n\\n    return _drain\\n\\n\\n_BUILT_FLOW = {\\n    \\\"name\\\": \\\"f\\\",\\n    \\\"data\\\": {\\n        \\\"nodes\\\": [\\n            {\\\"id\\\": \\\"ChatInput-1\\\", \\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\", \\\"node\\\": {\\\"template\\\": {\\\"input_value\\\": {\\\"value\\\": \\\"\\\"}}}}},\\n            {\\\"id\\\": \\\"ChatOutput-1\\\", \\\"data\\\": {\\\"type\\\": \\\"ChatOutput\\\", \\\"node\\\": {\\\"template\\\": {}}}},\\n        ],\\n        \\\"edges\\\": [{\\\"source\\\": \\\"ChatInput-1\\\", \\\"target\\\": \\\"ChatOutput-1\\\"}],\\n    },\\n}\\n\\n\\n_BUILT_LOOP_FLOW = {\\n    \\\"name\\\": \\\"loop\\\",\\n    \\\"data\\\": {\\n        \\\"nodes\\\": [\\n            {\\\"id\\\": \\\"LoopComponent-1\\\", \\\"data\\\": {\\\"type\\\": \\\"LoopComponent\\\", \\\"node\\\": {\\\"template\\\": {}}}},\\n            {\\\"id\\\": \\\"TypeConverterComponent-1\\\", \\\"data\\\": {\\\"type\\\": \\\"TypeConverterComponent\\\", \\\"node\\\": {\\\"template\\\": {}}}},\\n        ],\\n        \\\"edges\\\": [\\n            {\\n                \\\"source\\\": \\\"TypeConverterComponent-1\\\",\\n                \\\"target\\\": \\\"LoopComponent-1\\\",\\n                \\\"data\\\": {\\\"targetHandle\\\": {\\\"name\\\": \\\"item\\\", \\\"id\\\": \\\"LoopComponent-1\\\", \\\"output_types\\\": [\\\"Data\\\"]}},\\n            }\\n        ],\\n    },\\n}\\n\\n\\n_LOOP_OUTPUTS = [\\n    {\\\"name\\\": \\\"item\\\", \\\"types\\\": [\\\"Data\\\"], \\\"allows_loop\\\": True, \\\"group_outputs\\\": True},\\n    {\\\"name\\\": \\\"done\\\", \\\"types\\\": [\\\"DataFrame\\\"], \\\"allows_loop\\\": False, \\\"group_outputs\\\": True},\\n]\\n\\n_COMPLETE_LOOP_FLOW = {\\n    \\\"name\\\": \\\"loop\\\",\\n    \\\"data\\\": {\\n        \\\"nodes\\\": [\\n            {\\\"id\\\": \\\"ChatInput-1\\\", \\\"data\\\": {\\\"id\\\": \\\"ChatInput-1\\\", \\\"type\\\": \\\"ChatInput\\\", \\\"node\\\": {\\\"template\\\": {}}}},\\n            {\\n                \\\"id\\\": \\\"LoopComponent-1\\\",\\n                \\\"data\\\": {\\n                    \\\"id\\\": \\\"LoopComponent-1\\\",\\n                    \\\"type\\\": \\\"LoopComponent\\\",\\n                    \\\"node\\\": {\\\"template\\\": {\\\"data\\\": {\\\"input_types\\\": [\\\"Data\\\"]}}, \\\"outputs\\\": _LOOP_OUTPUTS},\\n                },\\n            },\\n            {\\\"id\\\": \\\"ChatOutput-1\\\", \\\"data\\\": {\\\"id\\\": \\\"ChatOutput-1\\\", \\\"type\\\": \\\"ChatOutput\\\", \\\"node\\\": {\\\"template\\\": {}}}},\\n        ],\\n        \\\"edges\\\": [\\n            {\\n                \\\"source\\\": \\\"ChatInput-1\\\",\\n                \\\"target\\\": \\\"LoopComponent-1\\\",\\n                \\\"data\\\": {\\n                    \\\"sourceHandle\\\": {\\\"name\\\": \\\"message\\\", \\\"id\\\": \\\"ChatInput-1\\\"},\\n                    \\\"targetHandle\\\": {\\\"fieldName\\\": \\\"data\\\", \\\"id\\\": \\\"LoopComponent-1\\\"},\\n                },\\n            },\\n            {\\n                \\\"source\\\": \\\"LoopComponent-1\\\",\\n                \\\"target\\\": \\\"ChatOutput-1\\\",\\n                \\\"data\\\": {\\n                    \\\"sourceHandle\\\": {\\\"name\\\": \\\"item\\\", \\\"id\\\": \\\"LoopComponent-1\\\"},\\n                    \\\"targetHandle\\\": {\\\"fieldName\\\": \\\"input_value\\\", \\\"id\\\": \\\"ChatOutput-1\\\"},\\n                },\\n            },\\n            {\\n                \\\"source\\\": \\\"ChatOutput-1\\\",\\n                \\\"target\\\": \\\"LoopComponent-1\\\",\\n                \\\"data\\\": {\\n                    \\\"sourceHandle\\\": {\\\"name\\\": \\\"message\\\", \\\"id\\\": \\\"ChatOutput-1\\\"},\\n                    \\\"targetHandle\\\": {\\\"name\\\": \\\"item\\\", \\\"id\\\": \\\"LoopComponent-1\\\", \\\"output_types\\\": [\\\"Data\\\"]},\\n                },\\n            },\\n        ],\\n    },\\n}\\n\\n\\ndef _complete_payload(events):\\n    for e in events:\\n        if '\\\"event\\\": \\\"complete\\\"' in e:\\n            return json.loads(e.split(\\\"data: \\\", 1)[1])\\n    return None\\n\\n\\nasync def _collect(gen):\\n    return [e async for e in gen]\\n\\n\\nclass TestCharacterizationNoFlowIdPath:\\n    \\\"\\\"\\\"SAFETY NET: with no FLOW_ID, the build path is unchanged by Slice 4.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_emit_flow_proposal_ready_then_one_complete_without_caveat(self):\\n        with (\\n            patch(f\\\"{MODULE}.classify_intent\\\", AsyncMock(return_value=_intent(\\\"build_flow\\\"))),\\n            patch(f\\\"{MODULE}.execute_flow_file_streaming\\\", MagicMock(side_effect=lambda **_k: _stream_end())),\\n            patch(f\\\"{MODULE}.drain_flow_events\\\", side_effect=_drain_set_flow_once()),\\n            patch(f\\\"{MODULE}.extract_response_text\\\", return_value=\\\"Flow built.\\\"),\\n            patch(\\\"asyncio.sleep\\\", new_callable=AsyncMock),\\n        ):\\n            events = await _collect(\\n                execute_flow_with_validation_streaming(\\n                    flow_filename=\\\"flow_builder_assistant\\\",\\n                    input_value=\\\"build me a chat flow\\\",\\n                    global_variables={},  # NO FLOW_ID \u2192 verification must not trigger\\n                    max_retries=1,\\n                )\\n            )\\n\\n        blob = \\\"\\\\n\\\".join(events)\\n        assert '\\\"step\\\": \\\"flow_proposal_ready\\\"' in blob\\n        assert len([e for e in events if '\\\"event\\\": \\\"complete\\\"' in e]) == 1\\n        assert '\\\"event\\\": \\\"error\\\"' not in blob\\n        assert \\\"verification_caveat\\\" not in blob\\n\\n\\nclass TestFlowVerificationDeliversHonestCaveat:\\n    @pytest.mark.asyncio\\n    async def test_should_deliver_caveat_when_built_flow_run_fails_non_fixably(self):\\n        run = AsyncMock(return_value={\\\"error\\\": \\\"Incorrect API key provided\\\"})\\n        with (\\n            patch(f\\\"{MODULE}.classify_intent\\\", AsyncMock(return_value=_intent(\\\"build_flow\\\"))),\\n            patch(f\\\"{MODULE}.execute_flow_file_streaming\\\", MagicMock(side_effect=lambda **_k: _stream_end())),\\n            patch(f\\\"{MODULE}.drain_flow_events\\\", side_effect=_drain_set_flow_once()),\\n            patch(f\\\"{MODULE}.extract_response_text\\\", return_value=\\\"Flow built.\\\"),\\n            patch(f\\\"{MODULE}.get_working_flow\\\", return_value=_BUILT_FLOW),\\n            patch(f\\\"{MODULE}.run_working_flow\\\", run),\\n            patch(\\\"asyncio.sleep\\\", new_callable=AsyncMock),\\n        ):\\n            events = await _collect(\\n                execute_flow_with_validation_streaming(\\n                    flow_filename=\\\"flow_builder_assistant\\\",\\n                    input_value=\\\"build me a chat flow\\\",\\n                    global_variables={\\\"FLOW_ID\\\": \\\"11111111-1111-1111-1111-111111111111\\\"},\\n                    max_retries=1,\\n                )\\n            )\\n\\n        run.assert_awaited()  # the flow was actually run to verify it\\n        blob = \\\"\\\\n\\\".join(events)\\n        assert '\\\"event\\\": \\\"error\\\"' not in blob  # flow still delivered, not an error\\n        data = _complete_payload(events)\\n        assert data is not None\\n        # Honest: presented with a caveat, NOT as a confident success.\\n        assert data[\\\"data\\\"].get(\\\"verified\\\") is False\\n        assert data[\\\"data\\\"].get(\\\"verification_caveat\\\")\\n        assert \\\"couldn't\\\" in data[\\\"data\\\"][\\\"verification_caveat\\\"].lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_cyclic_loop_flow_is_structurally_validated_not_run_and_flags_incomplete(self):\\n        run = AsyncMock()\\n        # get_working_flow returns the same broken loop each time, so the\\n        # structural fix loop can never repair it -> honest incomplete caveat.\\n        with (\\n            patch(f\\\"{MODULE}.classify_intent\\\", AsyncMock(return_value=_intent(\\\"build_flow\\\"))),\\n            patch(f\\\"{MODULE}.execute_flow_file_streaming\\\", MagicMock(side_effect=lambda **_k: _stream_end())),\\n            patch(f\\\"{MODULE}.execute_flow_file\\\", new_callable=AsyncMock),\\n            patch(f\\\"{MODULE}.drain_flow_events\\\", side_effect=_drain_set_flow_once()),\\n            patch(f\\\"{MODULE}.extract_response_text\\\", return_value=\\\"Flow built.\\\"),\\n            patch(f\\\"{MODULE}.get_working_flow\\\", return_value=_BUILT_LOOP_FLOW),\\n            patch(f\\\"{MODULE}.run_working_flow\\\", run),\\n            patch(\\\"asyncio.sleep\\\", new_callable=AsyncMock),\\n        ):\\n            events = await _collect(\\n                execute_flow_with_validation_streaming(\\n                    flow_filename=\\\"flow_builder_assistant\\\",\\n                    input_value=\\\"build me a loop flow\\\",\\n                    global_variables={\\\"FLOW_ID\\\": \\\"11111111-1111-1111-1111-111111111111\\\"},\\n                    max_retries=1,\\n                )\\n            )\\n\\n        run.assert_not_called()  # cyclic flow is never run to completion for verification\\n        data = _complete_payload(events)\\n        assert data is not None\\n        assert data[\\\"data\\\"].get(\\\"verified\\\") is False\\n        caveat = data[\\\"data\\\"][\\\"verification_caveat\\\"].lower()\\n        assert \\\"loop\\\" in caveat\\n        assert \\\"incomplete\\\" in caveat\\n        assert '\\\"event\\\": \\\"error\\\"' not in \\\"\\\\n\\\".join(events)\\n\\n    @pytest.mark.asyncio\\n    async def test_structurally_complete_loop_is_delivered_as_verified(self):\\n        run = AsyncMock()\\n        fix = AsyncMock()\\n        with (\\n            patch(f\\\"{MODULE}.classify_intent\\\", AsyncMock(return_value=_intent(\\\"build_flow\\\"))),\\n            patch(f\\\"{MODULE}.execute_flow_file_streaming\\\", MagicMock(side_effect=lambda **_k: _stream_end())),\\n            patch(f\\\"{MODULE}.execute_flow_file\\\", fix),\\n            patch(f\\\"{MODULE}.drain_flow_events\\\", side_effect=_drain_set_flow_once()),\\n            patch(f\\\"{MODULE}.extract_response_text\\\", return_value=\\\"Flow built.\\\"),\\n            patch(f\\\"{MODULE}.get_working_flow\\\", return_value=_COMPLETE_LOOP_FLOW),\\n            patch(f\\\"{MODULE}.run_working_flow\\\", run),\\n            patch(\\\"asyncio.sleep\\\", new_callable=AsyncMock),\\n        ):\\n            events = await _collect(\\n                execute_flow_with_validation_streaming(\\n                    flow_filename=\\\"flow_builder_assistant\\\",\\n                    input_value=\\\"build me a loop flow\\\",\\n                    global_variables={\\\"FLOW_ID\\\": \\\"11111111-1111-1111-1111-111111111111\\\"},\\n                    max_retries=1,\\n                )\\n            )\\n\\n        run.assert_not_called()  # loops are validated structurally, never run\\n        fix.assert_not_awaited()  # a sound loop needs no fix turn\\n        data = _complete_payload(events)\\n        assert data is not None\\n        assert data[\\\"data\\\"].get(\\\"verified\\\") is True\\n        assert \\\"verification_caveat\\\" not in data[\\\"data\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_switch_disables_verification(self, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_ASSISTANT_VERIFY_FLOWS\\\", \\\"0\\\")\\n        run = AsyncMock()\\n        with (\\n            patch(f\\\"{MODULE}.classify_intent\\\", AsyncMock(return_value=_intent(\\\"build_flow\\\"))),\\n            patch(f\\\"{MODULE}.execute_flow_file_streaming\\\", MagicMock(side_effect=lambda **_k: _stream_end())),\\n            patch(f\\\"{MODULE}.drain_flow_events\\\", side_effect=_drain_set_flow_once()),\\n            patch(f\\\"{MODULE}.extract_response_text\\\", return_value=\\\"Flow built.\\\"),\\n            patch(f\\\"{MODULE}.get_working_flow\\\", return_value=_BUILT_FLOW),\\n            patch(f\\\"{MODULE}.run_working_flow\\\", run),\\n            patch(\\\"asyncio.sleep\\\", new_callable=AsyncMock),\\n        ):\\n            events = await _collect(\\n                execute_flow_with_validation_streaming(\\n                    flow_filename=\\\"flow_builder_assistant\\\",\\n                    input_value=\\\"build me a chat flow\\\",\\n                    global_variables={\\\"FLOW_ID\\\": \\\"11111111-1111-1111-1111-111111111111\\\"},\\n                    max_retries=1,\\n                )\\n            )\\n\\n        run.assert_not_called()  # kill switch \u2192 no verification run\\n        assert \\\"verification_caveat\\\" not in \\\"\\\\n\\\".join(events)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_agent_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"25128f5a6a7c3a4f04c009f52d858d3212b100b1a8d135652f39fbc3287c2a21\",\"content\":\"\\\"\\\"\\\"find_agents_missing_model \u2014 static detection of Agents with no model.\\n\\n\\\"Agent has no model selected\\\" only raises at RUN time\\n(agent.py get_agent_requirements), which is exactly what we must NOT pay\\nto discover. It is trivially detectable from the flow JSON: an Agent\\nnode whose `model` field is empty and which has no legacy\\nagent_llm/model_name. This is the pure unit at the heart of the\\nauto-assign / honest-caveat decision.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom langflow.agentic.services.flow_agent_model import find_agents_missing_model\\n\\n\\ndef _flow(nodes):\\n    return {\\\"name\\\": \\\"f\\\", \\\"data\\\": {\\\"nodes\\\": nodes, \\\"edges\\\": []}}\\n\\n\\ndef _agent(node_id, template):\\n    return {\\\"id\\\": node_id, \\\"data\\\": {\\\"type\\\": \\\"Agent\\\", \\\"node\\\": {\\\"template\\\": template}}}\\n\\n\\nclass TestFindAgentsMissingModel:\\n    def test_should_flag_agent_with_empty_model_field(self):\\n        flow = _flow([_agent(\\\"Agent-1\\\", {\\\"model\\\": {\\\"value\\\": \\\"\\\"}})])\\n        assert find_agents_missing_model(flow) == [\\\"Agent-1\\\"]\\n\\n    def test_should_flag_agent_with_no_model_field_at_all(self):\\n        flow = _flow([_agent(\\\"Agent-1\\\", {})])\\n        assert find_agents_missing_model(flow) == [\\\"Agent-1\\\"]\\n\\n    def test_should_not_flag_agent_with_a_configured_model(self):\\n        flow = _flow([_agent(\\\"Agent-1\\\", {\\\"model\\\": {\\\"value\\\": [{\\\"name\\\": \\\"gpt-4o\\\"}]}})])\\n        assert find_agents_missing_model(flow) == []\\n\\n    def test_should_not_flag_agent_using_legacy_agent_llm_and_model_name(self):\\n        # Older serialized Agents resolve via agent_llm + model_name.\\n        flow = _flow(\\n            [\\n                _agent(\\n                    \\\"Agent-1\\\",\\n                    {\\\"agent_llm\\\": {\\\"value\\\": \\\"OpenAI\\\"}, \\\"model_name\\\": {\\\"value\\\": \\\"gpt-4o\\\"}},\\n                )\\n            ]\\n        )\\n        assert find_agents_missing_model(flow) == []\\n\\n    def test_should_flag_agent_with_legacy_provider_but_no_model_name(self):\\n        flow = _flow([_agent(\\\"Agent-1\\\", {\\\"agent_llm\\\": {\\\"value\\\": \\\"OpenAI\\\"}, \\\"model_name\\\": {\\\"value\\\": \\\"\\\"}})])\\n        assert find_agents_missing_model(flow) == [\\\"Agent-1\\\"]\\n\\n    def test_should_ignore_non_agent_nodes_even_if_they_have_a_model_field(self):\\n        node = {\\\"id\\\": \\\"X-1\\\", \\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\", \\\"node\\\": {\\\"template\\\": {\\\"model\\\": {\\\"value\\\": \\\"\\\"}}}}}\\n        assert find_agents_missing_model(_flow([node])) == []\\n\\n    def test_should_flag_only_the_agents_that_lack_a_model_when_several_exist(self):\\n        flow = _flow(\\n            [\\n                _agent(\\\"Agent-good\\\", {\\\"model\\\": {\\\"value\\\": [{\\\"name\\\": \\\"claude\\\"}]}}),\\n                _agent(\\\"Agent-bad\\\", {\\\"model\\\": {\\\"value\\\": \\\"\\\"}}),\\n            ]\\n        )\\n        assert find_agents_missing_model(flow) == [\\\"Agent-bad\\\"]\\n\\n    def test_should_be_resilient_to_malformed_nodes_and_empty_flow(self):\\n        assert find_agents_missing_model({}) == []\\n        assert find_agents_missing_model({\\\"data\\\": {}}) == []\\n        # A malformed Agent node (no node/template) cannot prove it has a\\n        # model, so it IS flagged (so the resolver/caveat handles it)\\n        # rather than crashing.\\n        flow = _flow([{\\\"id\\\": \\\"x\\\"}, {\\\"id\\\": \\\"Agent-broken\\\", \\\"data\\\": {\\\"type\\\": \\\"Agent\\\"}}])\\n        assert find_agents_missing_model(flow) == [\\\"Agent-broken\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_agent_model_ensure.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4cb38ffdfd7affda819db77bbe7bf7045ccf71765f0ef029fd0e97d43ee3f2cd\",\"content\":\"\\\"\\\"\\\"ensure_agent_models \u2014 auto-assign a model, else report NO_PROVIDER.\\n\\nWhen the built flow has an Agent with no model, the assistant must NOT\\nrun the LLM to discover it. If the request itself has a usable\\nprovider/model (it always does \u2014 that is the model the agent ran with),\\ninject it into the Agent node(s). If there is genuinely none, report it\\nso the caller can deliver an honest caveat \u2014 never loop on this.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom langflow.agentic.services.flow_agent_model import (\\n    AgentModelOutcome,\\n    ensure_agent_models,\\n    find_agents_missing_model,\\n)\\n\\n\\ndef _flow_with_modelless_agent():\\n    return {\\n        \\\"name\\\": \\\"f\\\",\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": \\\"Agent-1\\\",\\n                    \\\"data\\\": {\\n                        \\\"type\\\": \\\"Agent\\\",\\n                        \\\"node\\\": {\\\"template\\\": {\\\"model\\\": {\\\"value\\\": \\\"\\\"}}},\\n                    },\\n                }\\n            ],\\n            \\\"edges\\\": [],\\n        },\\n    }\\n\\n\\nclass TestEnsureAgentModels:\\n    def test_should_return_none_needed_when_no_agent_is_missing_a_model(self):\\n        flow = {\\n            \\\"name\\\": \\\"f\\\",\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"id\\\": \\\"Agent-1\\\",\\n                        \\\"data\\\": {\\\"type\\\": \\\"Agent\\\", \\\"node\\\": {\\\"template\\\": {\\\"model\\\": {\\\"value\\\": [{\\\"name\\\": \\\"gpt-4o\\\"}]}}}},\\n                    }\\n                ],\\n                \\\"edges\\\": [],\\n            },\\n        }\\n        outcome = ensure_agent_models(flow=flow, provider=\\\"OpenAI\\\", model_name=\\\"gpt-4o\\\", api_key_var=\\\"OPENAI_API_KEY\\\")\\n        assert outcome is AgentModelOutcome.NONE_NEEDED\\n\\n    def test_should_inject_the_request_model_when_an_agent_lacks_one(self):\\n        flow = _flow_with_modelless_agent()\\n\\n        outcome = ensure_agent_models(flow=flow, provider=\\\"OpenAI\\\", model_name=\\\"gpt-4o\\\", api_key_var=\\\"OPENAI_API_KEY\\\")\\n\\n        assert outcome is AgentModelOutcome.ASSIGNED\\n        # The Agent now resolves a model (no longer flagged).\\n        assert find_agents_missing_model(flow) == []\\n\\n    def test_should_report_no_provider_when_request_has_no_usable_model(self):\\n        flow = _flow_with_modelless_agent()\\n\\n        outcome = ensure_agent_models(flow=flow, provider=None, model_name=None, api_key_var=None)\\n\\n        assert outcome is AgentModelOutcome.NO_PROVIDER\\n        # Flow is left untouched \u2014 the caller delivers an honest caveat.\\n        assert find_agents_missing_model(flow) == [\\\"Agent-1\\\"]\\n\\n    def test_should_not_loop_or_raise_when_provider_is_unknown(self):\\n        # An unknown provider must degrade to NO_PROVIDER, never explode\\n        # the build (inject_model_into_flow raises ValueError on unknown).\\n        flow = _flow_with_modelless_agent()\\n\\n        outcome = ensure_agent_models(flow=flow, provider=\\\"Nonexistent\\\", model_name=\\\"x\\\", api_key_var=None)\\n\\n        assert outcome is AgentModelOutcome.NO_PROVIDER\\n        assert find_agents_missing_model(flow) == [\\\"Agent-1\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_executor.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b341d6bc6d96454015fe2badd8427b4c99f4cd54a16eeb3c0d1ebaf096c562fe\",\"content\":\"\\\"\\\"\\\"Tests for flow execution module.\\n\\nTests FlowExecutionResult, extract_response_text, _run_graph_with_events,\\nexecute_flow_file, execute_flow_file_streaming, and module constants.\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nimport json\\nfrom pathlib import Path\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.agentic.services.flow_executor import (\\n    _run_graph_with_events,\\n    execute_flow_file,\\n    execute_flow_file_streaming,\\n    extract_response_text,\\n)\\nfrom langflow.agentic.services.flow_types import (\\n    FLOWS_BASE_PATH,\\n    STREAMING_EVENT_TIMEOUT_SECONDS,\\n    STREAMING_QUEUE_MAX_SIZE,\\n    FlowExecutionResult,\\n)\\nfrom langflow.agentic.services.helpers.event_consumer import parse_event_data\\nfrom lfx.utils.flow_validation import CustomComponentValidationError\\n\\nMODULE = \\\"langflow.agentic.services.flow_executor\\\"\\n\\n\\nclass TestFlowExecutionResult:\\n    \\\"\\\"\\\"Tests for FlowExecutionResult dataclass.\\\"\\\"\\\"\\n\\n    def test_should_create_with_defaults(self):\\n        \\\"\\\"\\\"Should create with default empty values.\\\"\\\"\\\"\\n        result = FlowExecutionResult()\\n\\n        assert result.result == {}\\n        assert result.error is None\\n        assert result.has_error is False\\n        assert result.has_result is False\\n\\n    def test_should_detect_error(self):\\n        \\\"\\\"\\\"Should detect when error is set.\\\"\\\"\\\"\\n        result = FlowExecutionResult(error=ValueError(\\\"test\\\"))\\n\\n        assert result.has_error is True\\n        assert result.has_result is False\\n\\n    def test_should_detect_result(self):\\n        \\\"\\\"\\\"Should detect when result is set.\\\"\\\"\\\"\\n        result = FlowExecutionResult(result={\\\"key\\\": \\\"value\\\"})\\n\\n        assert result.has_result is True\\n        assert result.has_error is False\\n\\n    def test_should_allow_both_result_and_error(self):\\n        \\\"\\\"\\\"Should allow both result and error to be set.\\\"\\\"\\\"\\n        result = FlowExecutionResult(result={\\\"partial\\\": \\\"data\\\"}, error=ValueError(\\\"partial failure\\\"))\\n\\n        assert result.has_result is True\\n        assert result.has_error is True\\n\\n\\nclass TestExtractResponseText:\\n    \\\"\\\"\\\"Tests for extract_response_text function.\\\"\\\"\\\"\\n\\n    def test_should_extract_from_result_key(self):\\n        \\\"\\\"\\\"Should extract text from 'result' key.\\\"\\\"\\\"\\n        data = {\\\"result\\\": \\\"Hello, world!\\\"}\\n        result = extract_response_text(data)\\n        assert result == \\\"Hello, world!\\\"\\n\\n    def test_should_extract_from_text_key(self):\\n        \\\"\\\"\\\"Should extract text from 'text' key when result not present.\\\"\\\"\\\"\\n        data = {\\\"text\\\": \\\"Hello from text key\\\"}\\n        result = extract_response_text(data)\\n        assert result == \\\"Hello from text key\\\"\\n\\n    def test_should_extract_from_exception_message(self):\\n        \\\"\\\"\\\"Should extract exception message.\\\"\\\"\\\"\\n        data = {\\\"exception_message\\\": \\\"Error occurred\\\"}\\n        result = extract_response_text(data)\\n        assert result == \\\"Error occurred\\\"\\n\\n    def test_should_prefer_result_over_text(self):\\n        \\\"\\\"\\\"Should prefer 'result' key over 'text' key.\\\"\\\"\\\"\\n        data = {\\\"result\\\": \\\"From result\\\", \\\"text\\\": \\\"From text\\\"}\\n        result = extract_response_text(data)\\n        assert result == \\\"From result\\\"\\n\\n    def test_should_return_string_representation_for_unknown_structure(self):\\n        \\\"\\\"\\\"Should return string representation for unknown structure.\\\"\\\"\\\"\\n        data = {\\\"custom_key\\\": \\\"custom_value\\\", \\\"another\\\": 123}\\n        result = extract_response_text(data)\\n        assert \\\"custom_key\\\" in result or \\\"custom_value\\\" in result\\n\\n    def test_should_handle_empty_dict(self):\\n        \\\"\\\"\\\"Should handle empty dictionary.\\\"\\\"\\\"\\n        result = extract_response_text({})\\n        assert result == \\\"{}\\\"\\n\\n\\nclass TestConstants:\\n    \\\"\\\"\\\"Tests for module constants.\\\"\\\"\\\"\\n\\n    def test_flows_base_path_should_point_to_flows_directory(self):\\n        \\\"\\\"\\\"FLOWS_BASE_PATH should point to the flows directory.\\\"\\\"\\\"\\n        assert FLOWS_BASE_PATH.name == \\\"flows\\\"\\n        assert FLOWS_BASE_PATH.parent.name == \\\"agentic\\\"\\n\\n    def test_streaming_queue_max_size_should_be_reasonable(self):\\n        \\\"\\\"\\\"STREAMING_QUEUE_MAX_SIZE should be reasonable.\\\"\\\"\\\"\\n        assert STREAMING_QUEUE_MAX_SIZE > 100\\n        assert STREAMING_QUEUE_MAX_SIZE <= 10000\\n\\n    def test_streaming_timeout_should_be_reasonable(self):\\n        \\\"\\\"\\\"STREAMING_EVENT_TIMEOUT_SECONDS should be reasonable.\\\"\\\"\\\"\\n        assert STREAMING_EVENT_TIMEOUT_SECONDS > 30\\n        assert STREAMING_EVENT_TIMEOUT_SECONDS <= 600\\n\\n\\nclass TestRunGraphWithEvents:\\n    \\\"\\\"\\\"Tests for _run_graph_with_events function.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_set_user_and_session_on_graph(self):\\n        \\\"\\\"\\\"Should set user_id and session_id on graph when provided.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        event_queue: asyncio.Queue[str] = asyncio.Queue()\\n        event_manager = MagicMock()\\n        execution_result = FlowExecutionResult()\\n\\n        await _run_graph_with_events(\\n            graph=mock_graph,\\n            input_value=\\\"test\\\",\\n            global_variables=None,\\n            user_id=\\\"user-1\\\",\\n            session_id=\\\"session-1\\\",\\n            event_manager=event_manager,\\n            event_queue=event_queue,\\n            execution_result=execution_result,\\n        )\\n\\n        assert mock_graph.user_id == \\\"user-1\\\"\\n        assert mock_graph.session_id == \\\"session-1\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_inject_global_variables_into_context(self):\\n        \\\"\\\"\\\"Should merge global_variables into graph.context['request_variables'].\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        event_queue: asyncio.Queue[str] = asyncio.Queue()\\n        execution_result = FlowExecutionResult()\\n\\n        await _run_graph_with_events(\\n            graph=mock_graph,\\n            input_value=\\\"test\\\",\\n            global_variables={\\\"KEY\\\": \\\"value\\\"},\\n            user_id=None,\\n            session_id=None,\\n            event_manager=MagicMock(),\\n            event_queue=event_queue,\\n            execution_result=execution_result,\\n        )\\n\\n        assert mock_graph.context[\\\"request_variables\\\"][\\\"KEY\\\"] == \\\"value\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_store_error_on_exception(self):\\n        \\\"\\\"\\\"Should store exception in execution_result.error.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            msg = \\\"execution failed\\\"\\n            raise RuntimeError(msg)\\n            yield\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        event_queue: asyncio.Queue[str] = asyncio.Queue()\\n        execution_result = FlowExecutionResult()\\n\\n        await _run_graph_with_events(\\n            graph=mock_graph,\\n            input_value=\\\"test\\\",\\n            global_variables=None,\\n            user_id=None,\\n            session_id=None,\\n            event_manager=MagicMock(),\\n            event_queue=event_queue,\\n            execution_result=execution_result,\\n        )\\n\\n        assert execution_result.has_error is True\\n        assert isinstance(execution_result.error, RuntimeError)\\n\\n    @pytest.mark.asyncio\\n    async def test_should_signal_completion_via_queue(self):\\n        \\\"\\\"\\\"Should always put None on event_queue, even on error.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            msg = \\\"fail\\\"\\n            raise ValueError(msg)\\n            yield\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        event_queue: asyncio.Queue[str] = asyncio.Queue()\\n        execution_result = FlowExecutionResult()\\n\\n        await _run_graph_with_events(\\n            graph=mock_graph,\\n            input_value=\\\"test\\\",\\n            global_variables=None,\\n            user_id=None,\\n            session_id=None,\\n            event_manager=MagicMock(),\\n            event_queue=event_queue,\\n            execution_result=execution_result,\\n        )\\n\\n        item = await event_queue.get()\\n        assert item is None\\n\\n\\nclass TestExecuteFlowFile:\\n    \\\"\\\"\\\"Tests for execute_flow_file function.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_raise_404_for_missing_flow_file(self):\\n        \\\"\\\"\\\"Should raise HTTPException 404 for missing flow file.\\\"\\\"\\\"\\n        with pytest.raises(HTTPException) as exc_info:\\n            await execute_flow_file(\\\"nonexistent_flow.json\\\")\\n\\n        assert exc_info.value.status_code == 404\\n        assert \\\"not found\\\" in exc_info.value.detail.lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_should_execute_flow_with_model_injection(self):\\n        \\\"\\\"\\\"Should execute flow with model preparation when provider and model specified.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(*_args, **_kwargs):\\n            yield {\\\"result\\\": \\\"success\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/path/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph) as mock_load,\\n        ):\\n            result = await execute_flow_file(\\n                \\\"test.json\\\",\\n                input_value=\\\"test\\\",\\n                provider=\\\"OpenAI\\\",\\n                model_name=\\\"gpt-4\\\",\\n            )\\n\\n        mock_load.assert_called_once()\\n        assert result is not None\\n\\n    @pytest.mark.asyncio\\n    async def test_should_raise_500_on_execution_error(self):\\n        \\\"\\\"\\\"Should raise HTTPException 500 on execution error.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(*_args, **_kwargs):\\n            msg = \\\"Execution failed\\\"\\n            raise RuntimeError(msg)\\n            yield\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/path/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n            pytest.raises(HTTPException) as exc_info,\\n        ):\\n            await execute_flow_file(\\\"test.json\\\")\\n\\n        assert exc_info.value.status_code == 500\\n\\n    @pytest.mark.asyncio\\n    async def test_should_raise_400_for_custom_component_validation_error(self):\\n        \\\"\\\"\\\"Should return 400 when custom components are blocked during flow loading.\\\"\\\"\\\"\\n        validation_error = \\\"Flow build blocked: custom components are not allowed: Bad (node)\\\"\\n\\n        with (\\n            patch(\\n                \\\"langflow.agentic.services.flow_executor.resolve_flow_path\\\",\\n                return_value=(Path(\\\"/fake/path/test.py\\\"), \\\"python\\\"),\\n            ),\\n            patch(\\n                \\\"langflow.agentic.services.flow_executor.load_graph_for_execution\\\",\\n                new_callable=AsyncMock,\\n                side_effect=CustomComponentValidationError(validation_error),\\n            ),\\n            pytest.raises(HTTPException) as exc_info,\\n        ):\\n            await execute_flow_file(\\\"test.py\\\")\\n\\n        assert exc_info.value.status_code == 400\\n        assert exc_info.value.detail == validation_error\\n\\n    @pytest.mark.asyncio\\n    async def test_should_set_user_and_session_on_loaded_graph(self):\\n        \\\"\\\"\\\"Should set user_id and session_id on the loaded graph.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/path/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n        ):\\n            await execute_flow_file(\\\"test.json\\\", input_value=\\\"test\\\", user_id=\\\"user-1\\\", session_id=\\\"session-1\\\")\\n\\n        assert mock_graph.user_id == \\\"user-1\\\"\\n        assert mock_graph.session_id == \\\"session-1\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_inject_global_variables(self):\\n        \\\"\\\"\\\"Should inject global_variables into graph context.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/path/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n        ):\\n            await execute_flow_file(\\\"test.json\\\", input_value=\\\"test\\\", global_variables={\\\"API_KEY\\\": \\\"secret\\\"})\\n\\n        assert mock_graph.context[\\\"request_variables\\\"][\\\"API_KEY\\\"] == \\\"secret\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_reraise_http_exception_as_is(self):\\n        \\\"\\\"\\\"Should re-raise HTTPException without wrapping in 500.\\\"\\\"\\\"\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/path/test.json\\\"), \\\"json\\\")),\\n            patch(\\n                f\\\"{MODULE}.load_graph_for_execution\\\",\\n                new_callable=AsyncMock,\\n                side_effect=HTTPException(status_code=404, detail=\\\"Flow not found\\\"),\\n            ),\\n            pytest.raises(HTTPException) as exc_info,\\n        ):\\n            await execute_flow_file(\\\"test.json\\\")\\n\\n        assert exc_info.value.status_code == 404\\n        assert \\\"Flow not found\\\" in exc_info.value.detail\\n\\n\\nclass TestParseEventData:\\n    \\\"\\\"\\\"Tests for parse_event_data function.\\\"\\\"\\\"\\n\\n    def test_should_parse_valid_event(self):\\n        \\\"\\\"\\\"Should parse valid event data.\\\"\\\"\\\"\\n        data = b'{\\\"event\\\": \\\"token\\\", \\\"data\\\": {\\\"chunk\\\": \\\"Hello\\\"}}'\\n        event_type, event_data = parse_event_data(data)\\n        assert event_type == \\\"token\\\"\\n        assert event_data == {\\\"chunk\\\": \\\"Hello\\\"}\\n\\n    def test_should_return_none_for_empty_data(self):\\n        \\\"\\\"\\\"Should return None event type for empty data.\\\"\\\"\\\"\\n        event_type, event_data = parse_event_data(b\\\"\\\")\\n        assert event_type is None\\n        assert event_data == {}\\n\\n    def test_should_return_none_for_whitespace_only(self):\\n        \\\"\\\"\\\"Should return None for whitespace-only data.\\\"\\\"\\\"\\n        event_type, event_data = parse_event_data(b\\\"   \\\\n\\\\t  \\\")\\n        assert event_type is None\\n        assert event_data == {}\\n\\n    def test_should_handle_event_without_data(self):\\n        \\\"\\\"\\\"Should handle event without data field.\\\"\\\"\\\"\\n        data = b'{\\\"event\\\": \\\"end\\\"}'\\n        event_type, event_data = parse_event_data(data)\\n        assert event_type == \\\"end\\\"\\n        assert event_data == {}\\n\\n\\nclass TestExecuteFlowFileStreaming:\\n    \\\"\\\"\\\"Tests for execute_flow_file_streaming function.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_raise_404_for_missing_flow_file(self):\\n        \\\"\\\"\\\"Should raise HTTPException 404 for missing flow file.\\\"\\\"\\\"\\n        with pytest.raises(HTTPException) as exc_info:\\n            async for _ in execute_flow_file_streaming(\\\"nonexistent_flow.json\\\"):\\n                pass\\n        assert exc_info.value.status_code == 404\\n\\n\\nclass TestExecuteFlowFileStreamingEvents:\\n    \\\"\\\"\\\"Tests for execute_flow_file_streaming event handling.\\n\\n    Note: These tests use 5+ mocks because the streaming architecture requires\\n    coordinating multiple subsystems (graph loading, event management, background\\n    task execution, and event consumption). This is inherent to the source code\\n    architecture, not a test design issue.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_yield_end_event_on_success(self):\\n        \\\"\\\"\\\"Should yield end event with result on successful execution.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_consume(*_args, **_kwargs):\\n            yield (\\\"token\\\", \\\"chunk1\\\")\\n            yield (\\\"end\\\", None)\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n            patch(f\\\"{MODULE}.create_default_event_manager\\\"),\\n            patch(f\\\"{MODULE}.consume_streaming_events\\\", side_effect=mock_consume),\\n            patch(f\\\"{MODULE}._run_graph_with_events\\\", new_callable=AsyncMock),\\n        ):\\n            events = [event async for event in execute_flow_file_streaming(\\\"test.json\\\", input_value=\\\"hello\\\")]\\n            event_types = [e[0] for e in events]\\n            assert \\\"token\\\" in event_types or \\\"end\\\" in event_types\\n\\n    @pytest.mark.asyncio\\n    async def test_should_yield_cancelled_on_disconnect(self):\\n        \\\"\\\"\\\"Should yield cancelled event when client disconnects.\\\"\\\"\\\"\\n\\n        async def mock_consume(*_args, **_kwargs):\\n            yield (\\\"cancelled\\\", None)\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=MagicMock(context={})),\\n            patch(f\\\"{MODULE}.create_default_event_manager\\\"),\\n            patch(f\\\"{MODULE}.consume_streaming_events\\\", side_effect=mock_consume),\\n            patch(f\\\"{MODULE}._run_graph_with_events\\\", new_callable=AsyncMock),\\n        ):\\n            events = [event async for event in execute_flow_file_streaming(\\\"test.json\\\")]\\n            assert (\\\"cancelled\\\", {}) in events\\n\\n    @pytest.mark.asyncio\\n    async def test_should_raise_http_on_execution_error(self):\\n        \\\"\\\"\\\"Should raise HTTPException when execution result has error.\\\"\\\"\\\"\\n\\n        async def mock_consume(*_args, **_kwargs):\\n            yield (\\\"end\\\", None)\\n\\n        mock_result = MagicMock()\\n        mock_result.has_error = True\\n        mock_result.has_result = False\\n        mock_result.error = RuntimeError(\\\"flow error\\\")\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=MagicMock(context={})),\\n            patch(f\\\"{MODULE}.create_default_event_manager\\\"),\\n            patch(f\\\"{MODULE}.consume_streaming_events\\\", side_effect=mock_consume),\\n            patch(f\\\"{MODULE}._run_graph_with_events\\\", new_callable=AsyncMock),\\n            patch(f\\\"{MODULE}.FlowExecutionResult\\\", return_value=mock_result),\\n        ):\\n            with pytest.raises(HTTPException) as exc_info:\\n                async for _ in execute_flow_file_streaming(\\\"test.json\\\"):\\n                    pass\\n            assert exc_info.value.status_code == 500\\n\\n    @pytest.mark.asyncio\\n    async def test_should_carry_original_error_internally_without_leaking_in_http_detail(self):\\n        \\\"\\\"\\\"Bug: streaming execution wrapped any error as a generic 'An internal error occurred'.\\n\\n        That hid the root cause (e.g. pydantic InputSchema validation failures from a\\n        weak model emitting malformed tool calls) from the upstream friendly-error\\n        mapper, so the user always saw the same generic message instead of an\\n        actionable one.\\n\\n        Fix: raise FlowExecutionError \u2014 a custom HTTPException that keeps the public\\n        ``detail`` generic (no stack traces leak to HTTP clients) while exposing\\n        ``original_error_message`` for internal callers (the assistant retry loop)\\n        to feed into extract_friendly_error.\\n        \\\"\\\"\\\"\\n        from langflow.agentic.services.flow_types import FlowExecutionError\\n\\n        async def mock_consume(*_args, **_kwargs):\\n            yield (\\\"end\\\", None)\\n\\n        raw_error_text = \\\"1 validation error for InputSchema\\\\ninput_value\\\\n  Input should be a valid string\\\"\\n        mock_result = MagicMock()\\n        mock_result.has_error = True\\n        mock_result.has_result = False\\n        mock_result.error = RuntimeError(raw_error_text)\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=MagicMock(context={})),\\n            patch(f\\\"{MODULE}.create_default_event_manager\\\"),\\n            patch(f\\\"{MODULE}.consume_streaming_events\\\", side_effect=mock_consume),\\n            patch(f\\\"{MODULE}._run_graph_with_events\\\", new_callable=AsyncMock),\\n            patch(f\\\"{MODULE}.FlowExecutionResult\\\", return_value=mock_result),\\n        ):\\n            with pytest.raises(FlowExecutionError) as exc_info:\\n                async for _ in execute_flow_file_streaming(\\\"test.json\\\"):\\n                    pass\\n\\n            # Public HTTP detail MUST be generic \u2014 no raw error text leaked\\n            assert exc_info.value.status_code == 500\\n            detail = str(exc_info.value.detail)\\n            assert \\\"InputSchema\\\" not in detail, f\\\"Raw error text leaked in public detail: {detail!r}\\\"\\n            assert \\\"Input should be a valid string\\\" not in detail, f\\\"Raw error text leaked in public detail: {detail!r}\\\"\\n\\n            # Internal original_error_message MUST carry the raw error so the\\n            # friendly-error mapper in assistant_service can pattern-match on it\\n            original = exc_info.value.original_error_message\\n            assert \\\"InputSchema\\\" in original or \\\"Input should be a valid string\\\" in original, (\\n                f\\\"Expected original error text in FlowExecutionError.original_error_message, got: {original!r}\\\"\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_should_handle_preparation_error(self):\\n        \\\"\\\"\\\"Should raise HTTPException on JSONDecodeError/OSError/ValueError.\\\"\\\"\\\"\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(\\n                f\\\"{MODULE}.load_graph_for_execution\\\",\\n                new_callable=AsyncMock,\\n                side_effect=json.JSONDecodeError(\\\"err\\\", \\\"doc\\\", 0),\\n            ),\\n            pytest.raises(HTTPException) as exc_info,\\n        ):\\n            async for _ in execute_flow_file_streaming(\\\"test.json\\\"):\\n                pass\\n        assert exc_info.value.status_code == 500\\n\\n\\nclass TestTracingIntegration:\\n    \\\"\\\"\\\"Tests for flow_id and flow_name propagation to enable tracing.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_run_graph_should_set_flow_id_from_global_variables(self):\\n        \\\"\\\"\\\"Should set graph.flow_id from FLOW_ID in global_variables.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.flow_name = None\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        event_queue: asyncio.Queue[str] = asyncio.Queue()\\n        execution_result = FlowExecutionResult()\\n\\n        await _run_graph_with_events(\\n            graph=mock_graph,\\n            input_value=\\\"test\\\",\\n            global_variables={\\\"FLOW_ID\\\": \\\"abc-123\\\"},\\n            user_id=None,\\n            session_id=None,\\n            event_manager=MagicMock(),\\n            event_queue=event_queue,\\n            execution_result=execution_result,\\n        )\\n\\n        assert mock_graph.flow_id == \\\"abc-123\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_run_graph_should_set_flow_name_when_missing(self):\\n        \\\"\\\"\\\"Should set graph.flow_name to 'Assistant Flow' when not already set.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.flow_name = None\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        event_queue: asyncio.Queue[str] = asyncio.Queue()\\n        execution_result = FlowExecutionResult()\\n\\n        await _run_graph_with_events(\\n            graph=mock_graph,\\n            input_value=\\\"test\\\",\\n            global_variables=None,\\n            user_id=None,\\n            session_id=None,\\n            event_manager=MagicMock(),\\n            event_queue=event_queue,\\n            execution_result=execution_result,\\n        )\\n\\n        assert mock_graph.flow_name == \\\"Assistant Flow\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_run_graph_should_preserve_existing_flow_name(self):\\n        \\\"\\\"\\\"Should not overwrite flow_name if already set on graph.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.flow_name = \\\"My Custom Flow\\\"\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        event_queue: asyncio.Queue[str] = asyncio.Queue()\\n        execution_result = FlowExecutionResult()\\n\\n        await _run_graph_with_events(\\n            graph=mock_graph,\\n            input_value=\\\"test\\\",\\n            global_variables={\\\"FLOW_ID\\\": \\\"abc\\\"},\\n            user_id=None,\\n            session_id=None,\\n            event_manager=MagicMock(),\\n            event_queue=event_queue,\\n            execution_result=execution_result,\\n        )\\n\\n        assert mock_graph.flow_name == \\\"My Custom Flow\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_run_graph_should_not_set_flow_id_when_missing(self):\\n        \\\"\\\"\\\"Should not set flow_id when FLOW_ID not in global_variables.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.flow_name = None\\n        mock_graph.flow_id = None\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        event_queue: asyncio.Queue[str] = asyncio.Queue()\\n        execution_result = FlowExecutionResult()\\n\\n        await _run_graph_with_events(\\n            graph=mock_graph,\\n            input_value=\\\"test\\\",\\n            global_variables={\\\"OTHER_KEY\\\": \\\"value\\\"},\\n            user_id=None,\\n            session_id=None,\\n            event_manager=MagicMock(),\\n            event_queue=event_queue,\\n            execution_result=execution_result,\\n        )\\n\\n        assert mock_graph.flow_id is None\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_flow_file_should_set_flow_id_from_global_variables(self):\\n        \\\"\\\"\\\"Should set graph.flow_id from FLOW_ID in global_variables.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.flow_name = None\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n        ):\\n            await execute_flow_file(\\n                \\\"test.json\\\",\\n                input_value=\\\"test\\\",\\n                global_variables={\\\"FLOW_ID\\\": \\\"flow-uuid-456\\\"},\\n            )\\n\\n        assert mock_graph.flow_id == \\\"flow-uuid-456\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_flow_file_should_set_flow_name_to_filename(self):\\n        \\\"\\\"\\\"Should set graph.flow_name to flow_filename when not already set.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.flow_name = None\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/MyFlow.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n        ):\\n            await execute_flow_file(\\n                \\\"MyFlow.json\\\",\\n                input_value=\\\"test\\\",\\n                global_variables=None,\\n            )\\n\\n        assert mock_graph.flow_name == \\\"MyFlow.json\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_flow_file_should_preserve_existing_flow_name(self):\\n        \\\"\\\"\\\"Should not overwrite flow_name if already set on graph.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.flow_name = \\\"Existing Name\\\"\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n        ):\\n            await execute_flow_file(\\\"test.json\\\", input_value=\\\"test\\\", global_variables={\\\"FLOW_ID\\\": \\\"id\\\"})\\n\\n        assert mock_graph.flow_name == \\\"Existing Name\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_flow_file_should_not_set_flow_id_when_global_vars_none(self):\\n        \\\"\\\"\\\"Should not crash or set flow_id when global_variables is None.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.flow_name = None\\n        mock_graph.flow_id = None\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(**_kwargs):\\n            yield {\\\"result\\\": \\\"ok\\\"}\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n        ):\\n            await execute_flow_file(\\\"test.json\\\", input_value=\\\"test\\\", global_variables=None)\\n\\n        assert mock_graph.flow_id is None\\n\\n    @pytest.mark.asyncio\\n    async def test_should_raise_400_for_custom_component_validation_error(self):\\n        \\\"\\\"\\\"Should return 400 when custom components are blocked before streaming starts.\\\"\\\"\\\"\\n        validation_error = \\\"Flow build blocked: custom components are not allowed: Bad (node)\\\"\\n\\n        with (\\n            patch(\\n                \\\"langflow.agentic.services.flow_executor.resolve_flow_path\\\",\\n                return_value=(Path(\\\"/fake/path/test.py\\\"), \\\"python\\\"),\\n            ),\\n            patch(\\n                \\\"langflow.agentic.services.flow_executor.load_graph_for_execution\\\",\\n                new_callable=AsyncMock,\\n                side_effect=CustomComponentValidationError(validation_error),\\n            ),\\n            pytest.raises(HTTPException) as exc_info,\\n        ):\\n            async for _ in execute_flow_file_streaming(\\\"test.py\\\"):\\n                pass\\n\\n        assert exc_info.value.status_code == 400\\n        assert exc_info.value.detail == validation_error\\n\\n\\nclass TestBugsAndEdgeCases:\\n    \\\"\\\"\\\"Tests that challenge the code \u2014 exposing real bugs and untested edge cases.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.xfail(\\n        reason=\\\"BUG: L47 graph.context['request_variables'] crashes with TypeError when context is None\\\",\\n        strict=True,\\n    )\\n    async def test_run_graph_context_none_crashes(self):\\n        \\\"\\\"\\\"_run_graph_with_events should handle graph.context being None.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = None\\n        mock_graph.prepare = MagicMock()\\n\\n        async def empty_gen(*_args, **_kwargs):\\n            return\\n            yield\\n\\n        mock_graph.async_start = empty_gen\\n\\n        event_queue: asyncio.Queue[str] = asyncio.Queue()\\n        execution_result = FlowExecutionResult()\\n\\n        await _run_graph_with_events(\\n            graph=mock_graph,\\n            input_value=None,\\n            global_variables={\\\"KEY\\\": \\\"value\\\"},\\n            user_id=None,\\n            session_id=None,\\n            event_manager=MagicMock(),\\n            event_queue=event_queue,\\n            execution_result=execution_result,\\n        )\\n\\n        assert execution_result.error is None\\n\\n    @pytest.mark.asyncio\\n    async def test_run_graph_global_vars_overwrite_existing(self):\\n        \\\"\\\"\\\"L49: .update(global_variables) silently overwrites existing request_variables.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = {\\\"request_variables\\\": {\\\"EXISTING_KEY\\\": \\\"original\\\"}}\\n        mock_graph.prepare = MagicMock()\\n\\n        async def empty_gen(*_args, **_kwargs):\\n            return\\n            yield\\n\\n        mock_graph.async_start = empty_gen\\n\\n        event_queue: asyncio.Queue[str] = asyncio.Queue()\\n        execution_result = FlowExecutionResult()\\n\\n        with patch(f\\\"{MODULE}.extract_structured_result\\\", return_value={}):\\n            await _run_graph_with_events(\\n                graph=mock_graph,\\n                input_value=None,\\n                global_variables={\\\"EXISTING_KEY\\\": \\\"overwritten\\\"},\\n                user_id=None,\\n                session_id=None,\\n                event_manager=MagicMock(),\\n                event_queue=event_queue,\\n                execution_result=execution_result,\\n            )\\n\\n        assert mock_graph.context[\\\"request_variables\\\"][\\\"EXISTING_KEY\\\"] == \\\"overwritten\\\"\\n\\n    def test_extract_response_text_empty_dict(self):\\n        \\\"\\\"\\\"extract_response_text({}) returns stringified '{}' \u2014 no special handling.\\\"\\\"\\\"\\n        result = extract_response_text({})\\n        assert result == \\\"{}\\\"\\n\\n    def test_extract_response_text_with_none_crashes(self):\\n        \\\"\\\"\\\"extract_response_text(None) crashes \u2014 no None check.\\\"\\\"\\\"\\n        with pytest.raises(TypeError):\\n            extract_response_text(None)\\n\\n    @pytest.mark.xfail(\\n        reason=\\\"BUG: FlowExecutionResult(result={}).has_result is False \u2014 empty dict is falsy\\\",\\n        strict=True,\\n    )\\n    def test_execution_result_empty_dict_should_have_result(self):\\n        \\\"\\\"\\\"A flow returning {} legitimately should still report has_result=True.\\\"\\\"\\\"\\n        result = FlowExecutionResult(result={})\\n        assert result.has_result is True\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.xfail(\\n        reason=\\\"BUG: L107 same context None crash \u2014 duplicated code, duplicated bug\\\",\\n        strict=True,\\n    )\\n    async def test_execute_flow_file_context_none_crashes(self):\\n        \\\"\\\"\\\"execute_flow_file should handle graph.context being None.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.context = None\\n\\n        async def empty_gen(*_args, **_kwargs):\\n            return\\n            yield\\n\\n        mock_graph.async_start = empty_gen\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n            patch(f\\\"{MODULE}.extract_structured_result\\\", return_value={}),\\n        ):\\n            result = await execute_flow_file(\\\"test.json\\\", global_variables={\\\"KEY\\\": \\\"val\\\"})\\n\\n        assert isinstance(result, dict)\\n\\n\\nclass TestExecuteFlowFileTokenMetrics:\\n    \\\"\\\"\\\"Token usage must be attached to flow execution results.\\n\\n    The executor owns the graph object after the run completes; it is the only\\n    place from which token usage can be summed by walking ``graph.vertices``\\n    (the engine's run_outputs carry only OUTPUT vertices, whose ``token_usage``\\n    is ``None`` by design \u2014 see ``extract_graph_token_usage`` docstring).\\n\\n    These tests pin the wiring between the executor and ``flow_run.extract_graph_token_usage``\\n    so the assistant turn can surface its real LLM cost to the user.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_attach_metrics_to_end_event_when_streaming_succeeds(self):\\n        mock_graph = MagicMock(context={})\\n        expected_metrics = {\\\"input_tokens\\\": 12, \\\"output_tokens\\\": 7, \\\"total_tokens\\\": 19}\\n\\n        async def mock_consume(*_args, **_kwargs):\\n            yield (\\\"end\\\", None)\\n\\n        mock_result = MagicMock()\\n        mock_result.has_error = False\\n        mock_result.has_result = True\\n        mock_result.result = {\\\"text\\\": \\\"ok\\\"}\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n            patch(f\\\"{MODULE}.create_default_event_manager\\\"),\\n            patch(f\\\"{MODULE}.consume_streaming_events\\\", side_effect=mock_consume),\\n            patch(f\\\"{MODULE}._run_graph_with_events\\\", new_callable=AsyncMock),\\n            patch(f\\\"{MODULE}.FlowExecutionResult\\\", return_value=mock_result),\\n            patch(f\\\"{MODULE}.extract_graph_token_usage\\\", return_value=expected_metrics),\\n        ):\\n            events = [event async for event in execute_flow_file_streaming(\\\"test.json\\\", input_value=\\\"hi\\\")]\\n\\n        end_payloads = [payload for kind, payload in events if kind == \\\"end\\\"]\\n        assert len(end_payloads) == 1\\n        assert end_payloads[0][\\\"_metrics\\\"] == expected_metrics\\n        # Pre-existing keys must not be lost.\\n        assert end_payloads[0][\\\"text\\\"] == \\\"ok\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_attach_zero_metrics_when_graph_has_no_token_usage(self):\\n        \\\"\\\"\\\"A flow without an LLM/Agent vertex must still emit zero-tokens metrics \u2014 never crash.\\\"\\\"\\\"\\n        mock_graph = MagicMock(context={})\\n        zero_metrics = {\\\"input_tokens\\\": 0, \\\"output_tokens\\\": 0, \\\"total_tokens\\\": 0}\\n\\n        async def mock_consume(*_args, **_kwargs):\\n            yield (\\\"end\\\", None)\\n\\n        mock_result = MagicMock()\\n        mock_result.has_error = False\\n        mock_result.has_result = True\\n        mock_result.result = {}\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n            patch(f\\\"{MODULE}.create_default_event_manager\\\"),\\n            patch(f\\\"{MODULE}.consume_streaming_events\\\", side_effect=mock_consume),\\n            patch(f\\\"{MODULE}._run_graph_with_events\\\", new_callable=AsyncMock),\\n            patch(f\\\"{MODULE}.FlowExecutionResult\\\", return_value=mock_result),\\n            patch(f\\\"{MODULE}.extract_graph_token_usage\\\", return_value=zero_metrics),\\n        ):\\n            events = [event async for event in execute_flow_file_streaming(\\\"test.json\\\", input_value=\\\"hi\\\")]\\n\\n        end_payloads = [payload for kind, payload in events if kind == \\\"end\\\"]\\n        assert len(end_payloads) == 1\\n        assert end_payloads[0][\\\"_metrics\\\"] == zero_metrics\\n\\n    @pytest.mark.asyncio\\n    async def test_should_attach_metrics_to_execute_flow_file_result(self):\\n        \\\"\\\"\\\"Non-streaming execution must return ``_metrics`` so classify_intent can read it.\\\"\\\"\\\"\\n        mock_graph = MagicMock(context={})\\n        mock_graph.prepare = MagicMock()\\n        expected_metrics = {\\\"input_tokens\\\": 4, \\\"output_tokens\\\": 2, \\\"total_tokens\\\": 6}\\n\\n        async def mock_async_start(*_args, **_kwargs):\\n            return\\n            yield  # pragma: no cover\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n            patch(f\\\"{MODULE}.extract_structured_result\\\", return_value={\\\"text\\\": \\\"ok\\\"}),\\n            patch(f\\\"{MODULE}.extract_graph_token_usage\\\", return_value=expected_metrics),\\n        ):\\n            result = await execute_flow_file(\\\"test.json\\\", input_value=\\\"hi\\\")\\n\\n        assert result[\\\"_metrics\\\"] == expected_metrics\\n        assert result[\\\"text\\\"] == \\\"ok\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_not_attach_metrics_when_execute_flow_file_result_is_non_dict(self):\\n        \\\"\\\"\\\"Defensive: a non-dict result (rare engine fallback) must not crash the executor.\\\"\\\"\\\"\\n        mock_graph = MagicMock(context={})\\n        mock_graph.prepare = MagicMock()\\n\\n        async def mock_async_start(*_args, **_kwargs):\\n            return\\n            yield  # pragma: no cover\\n\\n        mock_graph.async_start = mock_async_start\\n\\n        with (\\n            patch(f\\\"{MODULE}.resolve_flow_path\\\", return_value=(Path(\\\"/fake/test.json\\\"), \\\"json\\\")),\\n            patch(f\\\"{MODULE}.load_graph_for_execution\\\", new_callable=AsyncMock, return_value=mock_graph),\\n            patch(f\\\"{MODULE}.extract_structured_result\\\", return_value=\\\"plain-text\\\"),\\n            patch(\\n                f\\\"{MODULE}.extract_graph_token_usage\\\",\\n                return_value={\\\"input_tokens\\\": 1, \\\"output_tokens\\\": 1, \\\"total_tokens\\\": 2},\\n            ),\\n        ):\\n            result = await execute_flow_file(\\\"test.json\\\", input_value=\\\"hi\\\")\\n\\n        # Either the function wraps the primitive in a dict carrying _metrics,\\n        # or it returns the primitive untouched \u2014 never raise.\\n        assert result == \\\"plain-text\\\" or (\\n            isinstance(result, dict) and result.get(\\\"_metrics\\\", {}).get(\\\"total_tokens\\\") == 2\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_executor_uses_coordinator.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f25e8ba35c7d411e03836c82070765d0f026e7244dca5612395675ad795d91ed\",\"content\":\"\\\"\\\"\\\"Verify flow_executor.py routes through the executor coordinator.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nfrom typing import Any\\n\\nimport pytest\\nfrom lfx.execution import (\\n    Coordinator,\\n    ExecutorRegistry,\\n    reset_default_coordinator,\\n    set_default_coordinator,\\n)\\nfrom lfx.execution.executor import Executor\\nfrom lfx.execution.types import RunComplete, StepResult\\n\\n\\nclass _Recording(Executor):\\n    kind = \\\"in-process\\\"\\n\\n    def __init__(self) -> None:\\n        self.units_seen: list[Any] = []\\n\\n    async def execute(self, unit):\\n        self.units_seen.append(unit)\\n        yield StepResult(payload=object())\\n        yield RunComplete(outputs=[])\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _reset_singleton():\\n    reset_default_coordinator()\\n    yield\\n    reset_default_coordinator()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_run_graph_uses_default_coordinator():\\n    from dataclasses import dataclass, field\\n\\n    from langflow.agentic.services.flow_executor import _run_graph_with_events\\n    from langflow.agentic.services.flow_types import FlowExecutionResult\\n\\n    recording = _Recording()\\n    registry = ExecutorRegistry()\\n    registry.register(recording)\\n    set_default_coordinator(Coordinator(registry=registry))\\n\\n    @dataclass\\n    class _FakeGraph:\\n        flow_id: str | None = None\\n        flow_name: str | None = None\\n        user_id: str | None = None\\n        session_id: str | None = None\\n        context: dict = field(default_factory=dict)\\n\\n        def prepare(self):\\n            pass\\n\\n        @contextlib.contextmanager\\n        def flow_execution_span(self, *, make_current: bool = True):\\n            \\\"\\\"\\\"The caller opens the flow span now, so a stand-in graph has to offer one.\\n\\n            Without it the AttributeError is swallowed by the broad except in\\n            _run_graph_with_events and the coordinator is never reached, which reads as \\\"the\\n            coordinator was not used\\\" rather than \\\"the fake is missing a method\\\".\\n            \\\"\\\"\\\"\\n            _ = make_current\\n            yield\\n\\n    queue: asyncio.Queue = asyncio.Queue()\\n    execution_result = FlowExecutionResult()\\n\\n    from lfx.events.event_manager import create_default_event_manager\\n\\n    em = create_default_event_manager(asyncio.Queue())\\n    await _run_graph_with_events(\\n        graph=_FakeGraph(),\\n        input_value=\\\"hi\\\",\\n        global_variables=None,\\n        user_id=None,\\n        session_id=None,\\n        event_manager=em,\\n        event_queue=queue,\\n        execution_result=execution_result,\\n    )\\n\\n    assert len(recording.units_seen) == 1\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_graph_build_check.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1a0575d99fa22bbc135ac8c64b63f455700b4ef4736bef03fb2181fb7eb4c0d0\",\"content\":\"\\\"\\\"\\\"build_check \u2014 Tier-2: construct the graph WITHOUT running it.\\n\\n`build_graph_from_data` \u2192 `Graph.from_payload` instantiates every\\ncomponent, resolves params and validates wiring/handles at BUILD time;\\nthe LLM only runs later in `vertex.build()`, which we never trigger. So\\nawaiting the build alone is a deterministic, zero-LLM-token check that\\ncatches \\\"Attribute build_output not found\\\", bad imports, type-mismatched\\nedges (Edge.__init__ raises) and invalid config.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import AsyncMock, patch\\n\\nimport pytest\\nfrom langflow.agentic.services.flow_graph_build_check import BuildCheckResult, build_check\\n\\nMODULE = \\\"langflow.agentic.services.flow_graph_build_check\\\"\\n_FLOW = {\\\"id\\\": \\\"f\\\", \\\"name\\\": \\\"f\\\", \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"A\\\"}], \\\"edges\\\": []}}\\n\\n\\nclass TestBuildCheck:\\n    @pytest.mark.asyncio\\n    async def test_should_be_ok_when_the_graph_builds(self):\\n        with patch(f\\\"{MODULE}.build_graph_from_data\\\", new_callable=AsyncMock, return_value=object()) as bg:\\n            result = await build_check(flow=_FLOW, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        assert isinstance(result, BuildCheckResult)\\n        assert result.ok is True\\n        assert result.error is None\\n        # Delegates the flow's data + ids to the real builder.\\n        bg.assert_awaited_once()\\n        assert bg.await_args.args[0] == \\\"flow-1\\\"\\n        assert bg.await_args.args[1] == _FLOW[\\\"data\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_should_report_the_deterministic_build_error_when_construction_raises(self):\\n        with patch(\\n            f\\\"{MODULE}.build_graph_from_data\\\",\\n            new_callable=AsyncMock,\\n            side_effect=ValueError(\\\"Attribute build_output not found in PrimeChecker\\\"),\\n        ):\\n            result = await build_check(flow=_FLOW, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        assert result.ok is False\\n        assert result.error is not None\\n        assert \\\"build_output not found\\\" in result.error\\n\\n    @pytest.mark.asyncio\\n    async def test_should_not_crash_on_an_unexpected_error(self):\\n        with patch(\\n            f\\\"{MODULE}.build_graph_from_data\\\",\\n            new_callable=AsyncMock,\\n            side_effect=RuntimeError(\\\"boom deep in graph\\\"),\\n        ):\\n            result = await build_check(flow=_FLOW, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        assert result.ok is False\\n        assert \\\"boom deep in graph\\\" in (result.error or \\\"\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_preparation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9fd7422ca5a8a6f5eb33f4f51acfde9cc282e63edece2354254ac91e52a9186d\",\"content\":\"\\\"\\\"\\\"Tests for flow data preparation and model injection.\\n\\nTests the inject_model_into_flow and load_and_prepare_flow\\nfunctions used to configure AI models in assistant flows.\\n\\\"\\\"\\\"\\n\\nimport json\\nfrom pathlib import Path\\nfrom unittest.mock import patch\\n\\nfrom langflow.agentic.services.flow_preparation import (\\n    LFX_COMPONENTS_PATH_SENTINEL,\\n    available_model_providers,\\n    inject_assistant_fs_root,\\n    inject_lfx_components_path,\\n    inject_model_into_flow,\\n    load_and_prepare_flow,\\n)\\n\\nimport lfx\\n\\nMODULE = \\\"langflow.agentic.services.flow_preparation\\\"\\n\\nOPENAI_CONFIG = {\\n    \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n    \\\"api_key_param\\\": \\\"api_key\\\",\\n    \\\"model_name_param\\\": \\\"model\\\",\\n    \\\"variable_name\\\": \\\"OPENAI_API_KEY\\\",\\n    \\\"icon\\\": \\\"OpenAI\\\",\\n}\\n\\n\\nclass TestAvailableModelProviders:\\n    \\\"\\\"\\\"Provider-agnostic detection of which providers have credentials.\\n\\n    No OpenAI bias \u2014 whatever keys the user actually has in the\\n    (env-built) global variables.\\n    \\\"\\\"\\\"\\n\\n    def test_detects_only_providers_with_a_configured_key(self):\\n        assert available_model_providers({\\\"ANTHROPIC_API_KEY\\\": \\\"sk-x\\\"}) == [\\\"Anthropic\\\"]\\n        result = available_model_providers({\\\"OPENAI_API_KEY\\\": \\\"a\\\", \\\"GROQ_API_KEY\\\": \\\"b\\\"})\\n        assert \\\"OpenAI\\\" in result\\n        assert \\\"Groq\\\" in result\\n        assert \\\"Anthropic\\\" not in result\\n\\n    def test_empty_or_blank_keys_yield_no_providers(self):\\n        assert available_model_providers({}) == []\\n        assert available_model_providers(None) == []\\n        assert available_model_providers({\\\"OPENAI_API_KEY\\\": \\\"\\\"}) == []\\n        # A whitespace-only key is NOT a configured key \u2014 the provider\\n        # would otherwise be picked and fail at run with an auth error.\\n        assert available_model_providers({\\\"OPENAI_API_KEY\\\": \\\"   \\\"}) == []\\n        assert available_model_providers({\\\"ANTHROPIC_API_KEY\\\": \\\"\\\\t\\\\n\\\"}) == []\\n\\n    def test_does_not_hardcode_openai(self):\\n        # Only Google configured \u2192 OpenAI must NOT appear.\\n        result = available_model_providers({\\\"GOOGLE_API_KEY\\\": \\\"k\\\"})\\n        assert \\\"Google Generative AI\\\" in result\\n        assert \\\"OpenAI\\\" not in result\\n\\n\\ndef _make_flow_data(node_types=None):\\n    \\\"\\\"\\\"Create minimal flow data with nodes of given types.\\\"\\\"\\\"\\n    if node_types is None:\\n        node_types = [\\\"Agent\\\"]\\n    nodes = []\\n    for i, ntype in enumerate(node_types):\\n        node = {\\n            \\\"id\\\": f\\\"node-{i}\\\",\\n            \\\"data\\\": {\\n                \\\"type\\\": ntype,\\n                \\\"node\\\": {\\n                    \\\"template\\\": {\\n                        \\\"model\\\": {\\\"value\\\": []},\\n                    },\\n                },\\n            },\\n        }\\n        nodes.append(node)\\n    return {\\\"data\\\": {\\\"nodes\\\": nodes}}\\n\\n\\nclass TestInjectModelIntoFlow:\\n    \\\"\\\"\\\"Tests for inject_model_into_flow.\\\"\\\"\\\"\\n\\n    def test_should_inject_model_into_agent_nodes(self):\\n        \\\"\\\"\\\"Should set model value on Agent-type nodes.\\\"\\\"\\\"\\n        flow_data = _make_flow_data([\\\"Agent\\\"])\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG):\\n            result = inject_model_into_flow(flow_data, \\\"OpenAI\\\", \\\"gpt-4o\\\")\\n\\n        model_val = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"]\\n        assert len(model_val) == 1\\n        assert model_val[0][\\\"name\\\"] == \\\"gpt-4o\\\"\\n        assert model_val[0][\\\"provider\\\"] == \\\"OpenAI\\\"\\n\\n    def test_should_not_modify_non_agent_nodes(self):\\n        \\\"\\\"\\\"Non-Agent nodes should remain unchanged.\\\"\\\"\\\"\\n        flow_data = _make_flow_data([\\\"ChatInput\\\", \\\"Agent\\\"])\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG):\\n            result = inject_model_into_flow(flow_data, \\\"OpenAI\\\", \\\"gpt-4o\\\")\\n\\n        # ChatInput node should still have empty model\\n        chat_input = result[\\\"data\\\"][\\\"nodes\\\"][0]\\n        assert chat_input[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"] == []\\n\\n        # Agent node should have the injected model\\n        agent = result[\\\"data\\\"][\\\"nodes\\\"][1]\\n        assert agent[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"][0][\\\"name\\\"] == \\\"gpt-4o\\\"\\n\\n    def test_should_use_provided_api_key_var(self):\\n        \\\"\\\"\\\"Should use provided api_key_var instead of provider default.\\\"\\\"\\\"\\n        flow_data = _make_flow_data([\\\"Agent\\\"])\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG):\\n            inject_model_into_flow(flow_data, \\\"OpenAI\\\", \\\"gpt-4o\\\", api_key_var=\\\"MY_KEY\\\")\\n\\n        # The function doesn't set api_key on nodes directly, but api_key_var\\n        # is used internally. We verify it doesn't error with a custom key.\\n\\n    def test_should_use_provider_default_api_key_var(self):\\n        \\\"\\\"\\\"Should use provider's variable_name when api_key_var is None.\\\"\\\"\\\"\\n        flow_data = _make_flow_data([\\\"Agent\\\"])\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG):\\n            inject_model_into_flow(flow_data, \\\"OpenAI\\\", \\\"gpt-4o\\\", api_key_var=None)\\n\\n        # Should not raise \u2014 uses OPENAI_CONFIG[\\\"variable_name\\\"]\\n\\n    def test_should_include_extra_params_from_config(self):\\n        \\\"\\\"\\\"Should include url_param, project_id_param when present in config.\\\"\\\"\\\"\\n        config_with_extras = {\\n            **OPENAI_CONFIG,\\n            \\\"url_param\\\": \\\"azure_endpoint\\\",\\n            \\\"base_url_param\\\": \\\"base_url\\\",\\n        }\\n        flow_data = _make_flow_data([\\\"Agent\\\"])\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=config_with_extras):\\n            result = inject_model_into_flow(flow_data, \\\"Azure\\\", \\\"gpt-4o\\\")\\n\\n        metadata = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"][0][\\\"metadata\\\"]\\n        assert metadata[\\\"url_param\\\"] == \\\"azure_endpoint\\\"\\n        assert metadata[\\\"base_url_param\\\"] == \\\"base_url\\\"\\n\\n    def test_should_use_model_id_param_for_watsonx(self):\\n        \\\"\\\"\\\"WatsonX must inject model_id, not the generic model (GitHub #13735).\\n\\n        inject_model_into_flow read the non-existent key model_name_param from\\n        get_provider_param_mapping (which emits model_param), defaulting to \\\"model\\\".\\n        For WatsonX that sets ChatWatsonx.model, routing to the OpenAI-compatible AI\\n        Gateway (400 \\\"model not found\\\") instead of native ModelInference (model_id).\\n        Uses the real WatsonX provider mapping (no mock) so the key drift is exercised.\\n        \\\"\\\"\\\"\\n        flow_data = _make_flow_data([\\\"Agent\\\"])\\n\\n        result = inject_model_into_flow(\\n            flow_data,\\n            \\\"IBM WatsonX\\\",\\n            \\\"openai/gpt-oss-120b\\\",\\n            provider_vars={\\n                \\\"WATSONX_URL\\\": \\\"https://us-south.ml.cloud.ibm.com\\\",\\n                \\\"WATSONX_PROJECT_ID\\\": \\\"pid\\\",\\n            },\\n        )\\n\\n        metadata = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"][0][\\\"metadata\\\"]\\n        assert metadata[\\\"model_name_param\\\"] == \\\"model_id\\\"\\n\\n    def test_should_handle_flow_without_agent_nodes(self):\\n        \\\"\\\"\\\"Flow with no Agent nodes should return data without modification.\\\"\\\"\\\"\\n        flow_data = _make_flow_data([\\\"ChatInput\\\", \\\"ChatOutput\\\"])\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG):\\n            result = inject_model_into_flow(flow_data, \\\"OpenAI\\\", \\\"gpt-4o\\\")\\n\\n        # Both nodes should still have empty model arrays\\n        for node in result[\\\"data\\\"][\\\"nodes\\\"]:\\n            assert node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"] == []\\n\\n    def test_should_handle_flow_without_model_in_template(self):\\n        \\\"\\\"\\\"Agent node without 'model' key in template should not error.\\\"\\\"\\\"\\n        flow_data = {\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"id\\\": \\\"node-0\\\",\\n                        \\\"data\\\": {\\n                            \\\"type\\\": \\\"Agent\\\",\\n                            \\\"node\\\": {\\\"template\\\": {}},\\n                        },\\n                    }\\n                ]\\n            }\\n        }\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG):\\n            result = inject_model_into_flow(flow_data, \\\"OpenAI\\\", \\\"gpt-4o\\\")\\n\\n        # Should not raise, template remains without model\\n        assert \\\"model\\\" not in result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n    def test_should_warn_when_an_agent_node_has_no_model_field(self, caplog):\\n        # Bug: injection was silently skipped for an Agent whose template\\n        # lacked 'model' (older serialized flow), and the function still\\n        # reported success \u2014 the run then failed with an opaque\\n        # \\\"No model selected\\\". It must at least leave a diagnostic.\\n        flow_data = {\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\\"id\\\": \\\"agent-7\\\", \\\"data\\\": {\\\"type\\\": \\\"Agent\\\", \\\"node\\\": {\\\"template\\\": {}}}},\\n                ]\\n            }\\n        }\\n        with (\\n            patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG),\\n            caplog.at_level(\\\"WARNING\\\"),\\n        ):\\n            inject_model_into_flow(flow_data, \\\"OpenAI\\\", \\\"gpt-4o\\\")\\n\\n        assert \\\"agent_missing_model_field\\\" in caplog.text\\n        assert \\\"agent-7\\\" in caplog.text\\n\\n    def test_should_not_warn_on_the_normal_agent_path(self, caplog):\\n        flow_data = _make_flow_data([\\\"Agent\\\"])\\n        with (\\n            patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG),\\n            caplog.at_level(\\\"WARNING\\\"),\\n        ):\\n            inject_model_into_flow(flow_data, \\\"OpenAI\\\", \\\"gpt-4o\\\")\\n\\n        assert \\\"agent_missing_model_field\\\" not in caplog.text\\n\\n\\ndef _agent_flow_with_model(provider: str, name: str) -> dict:\\n    \\\"\\\"\\\"A flow whose Agent already has an explicit model + api_key field set.\\\"\\\"\\\"\\n    return {\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": \\\"Agent-x\\\",\\n                    \\\"data\\\": {\\n                        \\\"type\\\": \\\"Agent\\\",\\n                        \\\"node\\\": {\\n                            \\\"template\\\": {\\n                                \\\"model\\\": {\\\"value\\\": [{\\\"provider\\\": provider, \\\"name\\\": name}]},\\n                                \\\"api_key\\\": {\\\"value\\\": \\\"\\\"},\\n                            }\\n                        },\\n                    },\\n                }\\n            ]\\n        }\\n    }\\n\\n\\nclass TestInjectModelPreservesExplicitModel:\\n    \\\"\\\"\\\"``overwrite_existing_model=False`` must never silently swap a user-set model.\\n\\n    Reproduces the production bug: the user asked for OpenAI gpt-5.4, but the\\n    end-of-turn RunFlow injection overwrote the Agent with the assistant's own\\n    verified model (gpt-5.5) and PERSISTED it on the canvas.\\n    \\\"\\\"\\\"\\n\\n    def test_keeps_existing_same_provider_model_and_injects_only_the_key(self):\\n        flow_data = _agent_flow_with_model(\\\"OpenAI\\\", \\\"gpt-5.4\\\")\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG):\\n            inject_model_into_flow(\\n                flow_data, \\\"OpenAI\\\", \\\"gpt-5.5\\\", api_key_var=\\\"OPENAI_API_KEY\\\", overwrite_existing_model=False\\n            )\\n\\n        template = flow_data[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        entry = template[\\\"model\\\"][\\\"value\\\"][0]\\n        # The user's model NAME is preserved \u2014 NOT swapped to gpt-5.5.\\n        assert entry[\\\"name\\\"] == \\\"gpt-5.4\\\"\\n        assert entry[\\\"provider\\\"] == \\\"OpenAI\\\"\\n        # ...and it is rebuilt as a COMPLETE value (metadata/icon) so the run\\n        # resolves it exactly like a normal selection \u2014 a bare {provider,name}\\n        # the agent set would otherwise lack these and fail to run.\\n        assert \\\"metadata\\\" in entry\\n        assert entry[\\\"metadata\\\"].get(\\\"model_class\\\") == \\\"ChatOpenAI\\\"\\n        assert entry.get(\\\"icon\\\") == \\\"OpenAI\\\"\\n        # ...and the credential was topped up so the same-provider run authenticates.\\n        assert template[\\\"api_key\\\"][\\\"value\\\"] == \\\"OPENAI_API_KEY\\\"\\n\\n    def test_does_not_touch_a_cross_provider_model(self):\\n        flow_data = _agent_flow_with_model(\\\"Anthropic\\\", \\\"claude-sonnet-4-5\\\")\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG):\\n            inject_model_into_flow(\\n                flow_data, \\\"OpenAI\\\", \\\"gpt-5.5\\\", api_key_var=\\\"OPENAI_API_KEY\\\", overwrite_existing_model=False\\n            )\\n\\n        template = flow_data[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        # Cross-provider model is left fully untouched (we don't hold its key).\\n        assert template[\\\"model\\\"][\\\"value\\\"][0][\\\"name\\\"] == \\\"claude-sonnet-4-5\\\"\\n        assert template[\\\"model\\\"][\\\"value\\\"][0][\\\"provider\\\"] == \\\"Anthropic\\\"\\n        # The OpenAI key must NOT be injected onto an Anthropic agent.\\n        assert template[\\\"api_key\\\"][\\\"value\\\"] == \\\"\\\"\\n\\n    def test_fills_in_an_empty_model_even_when_not_overwriting(self):\\n        flow_data = _make_flow_data([\\\"Agent\\\"])  # model value: []\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG):\\n            inject_model_into_flow(\\n                flow_data, \\\"OpenAI\\\", \\\"gpt-5.5\\\", api_key_var=\\\"OPENAI_API_KEY\\\", overwrite_existing_model=False\\n            )\\n\\n        # An Agent with NO model still gets one (run would otherwise break).\\n        model_val = flow_data[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"]\\n        assert model_val[0][\\\"name\\\"] == \\\"gpt-5.5\\\"\\n\\n    def test_overwrite_default_still_swaps_the_model(self):\\n        # Back-compat: the default (template prep / missing-model fill) still\\n        # overwrites, so other callers are unaffected.\\n        flow_data = _agent_flow_with_model(\\\"OpenAI\\\", \\\"gpt-5.4\\\")\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG):\\n            inject_model_into_flow(flow_data, \\\"OpenAI\\\", \\\"gpt-5.5\\\")\\n\\n        model_val = flow_data[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"]\\n        assert model_val[0][\\\"name\\\"] == \\\"gpt-5.5\\\"\\n\\n\\nclass TestLoadAndPrepareFlow:\\n    \\\"\\\"\\\"Tests for load_and_prepare_flow.\\\"\\\"\\\"\\n\\n    def test_should_load_and_inject_model(self, tmp_path):\\n        \\\"\\\"\\\"Should load JSON file and inject model configuration.\\\"\\\"\\\"\\n        flow_data = _make_flow_data([\\\"Agent\\\"])\\n        flow_file = tmp_path / \\\"test.json\\\"\\n        flow_file.write_text(json.dumps(flow_data))\\n\\n        with patch(f\\\"{MODULE}.get_provider_config\\\", return_value=OPENAI_CONFIG):\\n            result_json = load_and_prepare_flow(flow_file, \\\"OpenAI\\\", \\\"gpt-4o\\\", None)\\n\\n        result = json.loads(result_json)\\n        model_val = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"]\\n        assert model_val[0][\\\"name\\\"] == \\\"gpt-4o\\\"\\n\\n    def test_should_parse_the_flow_file_once_and_reuse_it_across_requests(self, tmp_path):\\n        # Bug: load_and_prepare_flow read + json.loads the bundled flow on\\n        # EVERY request (and x4 on validation retries) on the event loop.\\n        # The raw parsed template is stable per file \u2192 parse once, cached\\n        # by (path, mtime); a genuine file change re-parses.\\n        import pathlib\\n\\n        flow_data = _make_flow_data([\\\"Agent\\\"])\\n        flow_file = tmp_path / \\\"assistant.json\\\"\\n        flow_file.write_text(json.dumps(flow_data))\\n\\n        real_read_text = pathlib.Path.read_text\\n        calls = {\\\"n\\\": 0}\\n\\n        def counting_read_text(self, *args, **kwargs):\\n            if str(self) == str(flow_file):\\n                calls[\\\"n\\\"] += 1\\n            return real_read_text(self, *args, **kwargs)\\n\\n        with patch.object(pathlib.Path, \\\"read_text\\\", counting_read_text):\\n            a = load_and_prepare_flow(flow_file, None, None, None)\\n            b = load_and_prepare_flow(flow_file, None, None, None)\\n            assert calls[\\\"n\\\"] == 1  # second call served from cache\\n\\n            # Per-call result is independent (no shared mutable cache).\\n            assert json.loads(a) == json.loads(b)\\n\\n            # A genuine file change must invalidate the cache.\\n            changed = _make_flow_data([\\\"Agent\\\", \\\"ChatInput\\\"])\\n            flow_file.write_text(json.dumps(changed))\\n            load_and_prepare_flow(flow_file, None, None, None)\\n            assert calls[\\\"n\\\"] == 2\\n\\n    def test_should_return_original_when_no_provider(self, tmp_path):\\n        \\\"\\\"\\\"Should return original JSON when provider is None.\\\"\\\"\\\"\\n        flow_data = _make_flow_data([\\\"Agent\\\"])\\n        flow_file = tmp_path / \\\"test.json\\\"\\n        flow_file.write_text(json.dumps(flow_data))\\n\\n        result_json = load_and_prepare_flow(flow_file, None, None, None)\\n        result = json.loads(result_json)\\n\\n        # Model should remain empty (no injection)\\n        assert result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"] == []\\n\\n\\ndef _make_directory_flow(path_value: str) -> dict:\\n    \\\"\\\"\\\"Build a minimal flow dict with a single Directory node using the given path value.\\\"\\\"\\\"\\n    return {\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": \\\"Directory-test\\\",\\n                    \\\"data\\\": {\\n                        \\\"type\\\": \\\"Directory\\\",\\n                        \\\"node\\\": {\\n                            \\\"template\\\": {\\n                                \\\"path\\\": {\\n                                    \\\"_input_type\\\": \\\"MessageTextInput\\\",\\n                                    \\\"name\\\": \\\"path\\\",\\n                                    \\\"type\\\": \\\"str\\\",\\n                                    \\\"value\\\": path_value,\\n                                },\\n                            },\\n                        },\\n                    },\\n                },\\n            ],\\n        },\\n    }\\n\\n\\nclass TestInjectLfxComponentsPath:\\n    \\\"\\\"\\\"Tests for inject_lfx_components_path.\\n\\n    Regression guard for the Langflow Desktop bug where the LangflowAssistant\\n    flow embedded a relative path './src/lfx/src/lfx/components/' which only\\n    resolved correctly when the sidecar CWD was the monorepo root. On Desktop\\n    the CWD is the data dir, so the Directory component raised\\n    'Path ... must exist and be a directory.'\\n    \\\"\\\"\\\"\\n\\n    def test_should_rewrite_directory_path_to_absolute_lfx_components_when_path_matches_sentinel(self):\\n        flow_data = _make_directory_flow(LFX_COMPONENTS_PATH_SENTINEL)\\n\\n        result = inject_lfx_components_path(flow_data)\\n\\n        rewritten = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"path\\\"][\\\"value\\\"]\\n        expected = str(Path(lfx.__file__).parent / \\\"components\\\")\\n        assert rewritten == expected\\n        # Must be absolute \u2014 the whole point of the fix.\\n        assert Path(rewritten).is_absolute()\\n        # The rewritten path must actually exist in the installed lfx package.\\n        assert Path(rewritten).is_dir()\\n\\n    def test_should_not_modify_directory_path_when_value_is_not_sentinel(self):\\n        flow_data = _make_directory_flow(\\\"/custom/user/path\\\")\\n\\n        result = inject_lfx_components_path(flow_data)\\n\\n        assert result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"path\\\"][\\\"value\\\"] == \\\"/custom/user/path\\\"\\n\\n    def test_should_not_modify_non_directory_nodes(self):\\n        flow_data = _make_flow_data([\\\"Agent\\\"])\\n\\n        result = inject_lfx_components_path(flow_data)\\n\\n        # Agent node template untouched.\\n        assert \\\"path\\\" not in result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n    def test_should_handle_flow_without_nodes(self):\\n        flow_data: dict = {\\\"data\\\": {\\\"nodes\\\": []}}\\n\\n        result = inject_lfx_components_path(flow_data)\\n\\n        assert result == {\\\"data\\\": {\\\"nodes\\\": []}}\\n\\n    def test_should_rewrite_sentinel_path_when_loading_assistant_flow(self, tmp_path):\\n        \\\"\\\"\\\"Rewrite the sentinel path when loading the assistant flow.\\n\\n        load_and_prepare_flow must apply the lfx path injection so that\\n        Desktop (and any non-monorepo CWD) can execute the assistant flow.\\n        \\\"\\\"\\\"\\n        flow_data = _make_directory_flow(LFX_COMPONENTS_PATH_SENTINEL)\\n        flow_file = tmp_path / \\\"LangflowAssistant.json\\\"\\n        flow_file.write_text(json.dumps(flow_data))\\n\\n        result_json = load_and_prepare_flow(flow_file, None, None, None)\\n        result = json.loads(result_json)\\n\\n        rewritten = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"path\\\"][\\\"value\\\"]\\n        expected = str(Path(lfx.__file__).parent / \\\"components\\\")\\n        assert rewritten == expected\\n\\n\\ndef _make_filesystem_flow(root_path_value: str) -> dict:\\n    \\\"\\\"\\\"Build a minimal flow with a single FileSystemTool node at the given root_path.\\\"\\\"\\\"\\n    return {\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"data\\\": {\\n                        \\\"type\\\": \\\"FileSystemTool\\\",\\n                        \\\"node\\\": {\\\"template\\\": {\\\"root_path\\\": {\\\"value\\\": root_path_value}}},\\n                    },\\n                }\\n            ],\\n        },\\n    }\\n\\n\\nclass TestInjectAssistantFsRoot:\\n    \\\"\\\"\\\"Tests for inject_assistant_fs_root.\\n\\n    The shipped LangflowAssistant flow leaves FileSystemTool.root_path empty\\n    on purpose \u2014 it must be resolved at runtime to an OS-appropriate sandbox\\n    so the flow runs portably on macOS, Linux, Windows and Docker.\\n    \\\"\\\"\\\"\\n\\n    def test_should_replace_empty_root_path_for_filesystem_tool(self, tmp_path):\\n        flow_data = _make_filesystem_flow(\\\"\\\")\\n\\n        with patch(f\\\"{MODULE}.resolve_assistant_fs_root\\\", return_value=tmp_path / \\\"ws\\\"):\\n            result = inject_assistant_fs_root(flow_data)\\n\\n        injected = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"root_path\\\"][\\\"value\\\"]\\n        assert injected == str(tmp_path / \\\"ws\\\")\\n\\n    def test_should_replace_whitespace_only_root_path(self, tmp_path):\\n        flow_data = _make_filesystem_flow(\\\"   \\\")\\n\\n        with patch(f\\\"{MODULE}.resolve_assistant_fs_root\\\", return_value=tmp_path / \\\"ws\\\"):\\n            result = inject_assistant_fs_root(flow_data)\\n\\n        injected = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"root_path\\\"][\\\"value\\\"]\\n        assert injected == str(tmp_path / \\\"ws\\\")\\n\\n    def test_should_not_overwrite_explicit_root_path(self, tmp_path):\\n        flow_data = _make_filesystem_flow(\\\"/explicit/path\\\")\\n\\n        with patch(f\\\"{MODULE}.resolve_assistant_fs_root\\\", return_value=tmp_path / \\\"ws\\\"):\\n            result = inject_assistant_fs_root(flow_data)\\n\\n        injected = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"root_path\\\"][\\\"value\\\"]\\n        assert injected == \\\"/explicit/path\\\"\\n\\n    def test_should_skip_non_filesystem_nodes(self, tmp_path):\\n        flow_data = {\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"data\\\": {\\n                            \\\"type\\\": \\\"Agent\\\",\\n                            \\\"node\\\": {\\\"template\\\": {\\\"root_path\\\": {\\\"value\\\": \\\"\\\"}}},\\n                        },\\n                    }\\n                ],\\n            },\\n        }\\n\\n        with patch(f\\\"{MODULE}.resolve_assistant_fs_root\\\", return_value=tmp_path / \\\"ws\\\"):\\n            result = inject_assistant_fs_root(flow_data)\\n\\n        # Agent node's stray root_path field is untouched.\\n        unchanged = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"root_path\\\"][\\\"value\\\"]\\n        assert unchanged == \\\"\\\"\\n\\n    def test_should_handle_flow_without_filesystem_tool(self, tmp_path):\\n        flow_data: dict = {\\\"data\\\": {\\\"nodes\\\": []}}\\n\\n        with patch(f\\\"{MODULE}.resolve_assistant_fs_root\\\", return_value=tmp_path / \\\"ws\\\"):\\n            result = inject_assistant_fs_root(flow_data)\\n\\n        assert result == {\\\"data\\\": {\\\"nodes\\\": []}}\\n\\n    def test_should_inject_root_path_when_loading_assistant_flow(self, tmp_path):\\n        \\\"\\\"\\\"End-to-end: load_and_prepare_flow must inject the resolved root_path.\\\"\\\"\\\"\\n        flow_data = _make_filesystem_flow(\\\"\\\")\\n        flow_file = tmp_path / \\\"LangflowAssistant.json\\\"\\n        flow_file.write_text(json.dumps(flow_data))\\n\\n        with patch(f\\\"{MODULE}.resolve_assistant_fs_root\\\", return_value=tmp_path / \\\"ws\\\"):\\n            result_json = load_and_prepare_flow(flow_file, None, None, None)\\n\\n        result = json.loads(result_json)\\n        injected = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"root_path\\\"][\\\"value\\\"]\\n        assert injected == str(tmp_path / \\\"ws\\\")\\n\\n    def test_should_skip_injection_when_resolver_returns_none(self):\\n        \\\"\\\"\\\"When PR #13031's isolation module is active the resolver returns None.\\n\\n        In that mode the FileSystemTool derives its own per-user namespace at\\n        runtime; any value we inject would be misread as a relative sub_path\\n        and break the per-user boundary. Skip injection entirely.\\n        \\\"\\\"\\\"\\n        flow_data = _make_filesystem_flow(\\\"\\\")\\n\\n        with patch(f\\\"{MODULE}.resolve_assistant_fs_root\\\", return_value=None):\\n            result = inject_assistant_fs_root(flow_data)\\n\\n        # Untouched \u2014 root_path stays empty so the component self-resolves.\\n        unchanged = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"root_path\\\"][\\\"value\\\"]\\n        assert unchanged == \\\"\\\"\\n\\n    def test_should_skip_injection_for_explicit_root_path_when_resolver_returns_none(self):\\n        \\\"\\\"\\\"An operator-set root_path must be preserved even in the isolation-active case.\\\"\\\"\\\"\\n        flow_data = _make_filesystem_flow(\\\"/explicit/path\\\")\\n\\n        with patch(f\\\"{MODULE}.resolve_assistant_fs_root\\\", return_value=None):\\n            result = inject_assistant_fs_root(flow_data)\\n\\n        # Operator override survives \u2014 the FileSystemTool will treat it as\\n        # sub_path under the user's namespace.\\n        unchanged = result[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"root_path\\\"][\\\"value\\\"]\\n        assert unchanged == \\\"/explicit/path\\\"\\n\\n\\nclass TestInjectHistoryLimitIntoFlow:\\n    \\\"\\\"\\\"The /history N command overrides the Agent's memory window (n_messages).\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _flow_with_agent(n_messages_value=20):\\n        return {\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\", \\\"node\\\": {\\\"template\\\": {}}}},\\n                    {\\n                        \\\"data\\\": {\\n                            \\\"type\\\": \\\"Agent\\\",\\n                            \\\"node\\\": {\\\"template\\\": {\\\"n_messages\\\": {\\\"value\\\": n_messages_value}}},\\n                        }\\n                    },\\n                ]\\n            }\\n        }\\n\\n    def test_should_set_n_messages_on_agent_nodes(self):\\n        from langflow.agentic.services.flow_preparation import inject_history_limit_into_flow\\n\\n        flow = self._flow_with_agent(20)\\n        out = inject_history_limit_into_flow(flow, 5)\\n        agent = out[\\\"data\\\"][\\\"nodes\\\"][1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        assert agent[\\\"n_messages\\\"][\\\"value\\\"] == 5\\n\\n    def test_should_leave_non_agent_nodes_untouched(self):\\n        from langflow.agentic.services.flow_preparation import inject_history_limit_into_flow\\n\\n        flow = self._flow_with_agent(20)\\n        out = inject_history_limit_into_flow(flow, 5)\\n        chat_input = out[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        assert \\\"n_messages\\\" not in chat_input\\n\\n    def test_should_be_noop_for_none_or_negative_limit(self):\\n        from langflow.agentic.services.flow_preparation import inject_history_limit_into_flow\\n\\n        flow = self._flow_with_agent(20)\\n\\n        def _n_messages(f):\\n            return f[\\\"data\\\"][\\\"nodes\\\"][1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"n_messages\\\"][\\\"value\\\"]\\n\\n        assert _n_messages(inject_history_limit_into_flow(flow, None)) == 20\\n        assert _n_messages(inject_history_limit_into_flow(flow, -1)) == 20\\n\\n    def test_should_skip_agent_without_n_messages_field(self):\\n        from langflow.agentic.services.flow_preparation import inject_history_limit_into_flow\\n\\n        flow = {\\\"data\\\": {\\\"nodes\\\": [{\\\"data\\\": {\\\"type\\\": \\\"Agent\\\", \\\"node\\\": {\\\"template\\\": {}}}}]}}\\n        # must not raise\\n        inject_history_limit_into_flow(flow, 5)\\n\\n\\nclass TestInjectIterationsIntoFlow:\\n    \\\"\\\"\\\"The /iterations N command overrides the assistant Agent's step budget (max_iterations).\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _flow_with_agent(max_iterations_value=30):\\n        return {\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\", \\\"node\\\": {\\\"template\\\": {}}}},\\n                    {\\n                        \\\"data\\\": {\\n                            \\\"type\\\": \\\"Agent\\\",\\n                            \\\"node\\\": {\\\"template\\\": {\\\"max_iterations\\\": {\\\"value\\\": max_iterations_value}}},\\n                        }\\n                    },\\n                ]\\n            }\\n        }\\n\\n    def test_should_set_max_iterations_on_agent_nodes(self):\\n        from langflow.agentic.services.flow_preparation import inject_iterations_into_flow\\n\\n        flow = self._flow_with_agent(30)\\n        out = inject_iterations_into_flow(flow, 60)\\n        agent = out[\\\"data\\\"][\\\"nodes\\\"][1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        assert agent[\\\"max_iterations\\\"][\\\"value\\\"] == 60\\n\\n    def test_should_leave_non_agent_nodes_untouched(self):\\n        from langflow.agentic.services.flow_preparation import inject_iterations_into_flow\\n\\n        flow = self._flow_with_agent(30)\\n        out = inject_iterations_into_flow(flow, 60)\\n        chat_input = out[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        assert \\\"max_iterations\\\" not in chat_input\\n\\n    def test_should_be_noop_for_none_limit(self):\\n        from langflow.agentic.services.flow_preparation import inject_iterations_into_flow\\n\\n        flow = self._flow_with_agent(30)\\n        assert (\\n            inject_iterations_into_flow(flow, None)[\\\"data\\\"][\\\"nodes\\\"][1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"max_iterations\\\"][\\n                \\\"value\\\"\\n            ]\\n            == 30\\n        )\\n\\n    def test_should_clamp_to_minimum_of_one(self):\\n        from langflow.agentic.services.flow_preparation import inject_iterations_into_flow\\n\\n        flow = self._flow_with_agent(30)\\n        out = inject_iterations_into_flow(flow, 0)\\n        assert out[\\\"data\\\"][\\\"nodes\\\"][1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"max_iterations\\\"][\\\"value\\\"] == 1\\n\\n    def test_should_clamp_to_max(self):\\n        from langflow.agentic.services.flow_preparation import MAX_ASSISTANT_ITERATIONS, inject_iterations_into_flow\\n\\n        flow = self._flow_with_agent(30)\\n        out = inject_iterations_into_flow(flow, MAX_ASSISTANT_ITERATIONS + 50)\\n        assert (\\n            out[\\\"data\\\"][\\\"nodes\\\"][1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"max_iterations\\\"][\\\"value\\\"] == MAX_ASSISTANT_ITERATIONS\\n        )\\n\\n    def test_should_skip_agent_without_max_iterations_field(self):\\n        from langflow.agentic.services.flow_preparation import inject_iterations_into_flow\\n\\n        flow = {\\\"data\\\": {\\\"nodes\\\": [{\\\"data\\\": {\\\"type\\\": \\\"Agent\\\", \\\"node\\\": {\\\"template\\\": {}}}}]}}\\n        # must not raise\\n        inject_iterations_into_flow(flow, 60)\\n\\n    def test_load_and_prepare_reads_iterations_from_provider_vars(self):\\n        from langflow.agentic.services.flow_preparation import inject_iterations_into_flow, load_and_prepare_flow\\n\\n        # Sanity: the ITERATIONS_LIMIT provider var drives inject_iterations_into_flow.\\n        flow = self._flow_with_agent(30)\\n        out = inject_iterations_into_flow(flow, 45)\\n        assert out[\\\"data\\\"][\\\"nodes\\\"][1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"max_iterations\\\"][\\\"value\\\"] == 45\\n        assert callable(load_and_prepare_flow)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_probe_input.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b57621a83b18020561ed9e5f8a6c46f73905b198b2211bbcb7ac4b4992eddc05\",\"content\":\"\\\"\\\"\\\"apply_probe_input \u2014 make an input-needing flow runnable for verification.\\n\\nA built flow with an empty ChatInput cannot produce output on a probe\\nrun. The verification loop injects a deterministic probe value so the\\ngraph can actually execute, WITHOUT clobbering a value the user/agent\\nalready set.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom langflow.agentic.services.flow_probe_input import PROBE_INPUT_TEXT, apply_probe_input\\n\\n\\ndef _flow(nodes):\\n    return {\\\"name\\\": \\\"f\\\", \\\"data\\\": {\\\"nodes\\\": nodes, \\\"edges\\\": []}}\\n\\n\\ndef _chat_input(node_id, value=\\\"\\\"):\\n    return {\\n        \\\"id\\\": node_id,\\n        \\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\", \\\"node\\\": {\\\"template\\\": {\\\"input_value\\\": {\\\"value\\\": value}}}},\\n    }\\n\\n\\nclass TestApplyProbeInput:\\n    def test_should_inject_probe_value_into_empty_chatinput_and_report_applied(self):\\n        flow = _flow([_chat_input(\\\"ChatInput-1\\\", \\\"\\\")])\\n\\n        applied = apply_probe_input(flow)\\n\\n        assert applied is True\\n        val = flow[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_value\\\"][\\\"value\\\"]\\n        assert val == PROBE_INPUT_TEXT\\n\\n    def test_should_not_overwrite_a_chatinput_that_already_has_a_value(self):\\n        flow = _flow([_chat_input(\\\"ChatInput-1\\\", \\\"real user text\\\")])\\n\\n        applied = apply_probe_input(flow)\\n\\n        assert applied is False\\n        val = flow[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_value\\\"][\\\"value\\\"]\\n        assert val == \\\"real user text\\\"\\n\\n    def test_should_return_false_when_flow_has_no_chatinput(self):\\n        flow = _flow([{\\\"id\\\": \\\"Agent-1\\\", \\\"data\\\": {\\\"type\\\": \\\"Agent\\\", \\\"node\\\": {\\\"template\\\": {}}}}])\\n\\n        assert apply_probe_input(flow) is False\\n\\n    def test_should_fill_every_empty_chatinput_when_there_are_several(self):\\n        flow = _flow([_chat_input(\\\"ChatInput-1\\\", \\\"\\\"), _chat_input(\\\"ChatInput-2\\\", \\\"\\\")])\\n\\n        applied = apply_probe_input(flow)\\n\\n        assert applied is True\\n        values = [n[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_value\\\"][\\\"value\\\"] for n in flow[\\\"data\\\"][\\\"nodes\\\"]]\\n        assert values == [PROBE_INPUT_TEXT, PROBE_INPUT_TEXT]\\n\\n    def test_should_be_resilient_to_malformed_nodes(self):\\n        flow = _flow([{\\\"id\\\": \\\"x\\\"}, {\\\"data\\\": {}}, {\\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\"}}])\\n        # No usable template anywhere \u2192 nothing to probe, must not raise.\\n        assert apply_probe_input(flow) is False\\n\\n    def test_should_handle_empty_or_missing_flow_data(self):\\n        assert apply_probe_input({}) is False\\n        assert apply_probe_input({\\\"data\\\": {}}) is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_run.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7e2a6d7bf9b4392cc425dce3eed087862310ee80351bd9a1f485154197f5b8b5\",\"content\":\"\\\"\\\"\\\"Tests for flow-run result extraction (the text the agent talks about).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom dataclasses import dataclass, field\\nfrom unittest.mock import AsyncMock, patch\\n\\nimport pytest\\nfrom langflow.agentic.services.flow_run import (\\n    MAX_RESULT_CHARS,\\n    extract_graph_token_usage,\\n    extract_run_result_text,\\n    run_working_flow,\\n)\\n\\nMODULE = \\\"langflow.agentic.services.flow_run\\\"\\n\\n\\n# Lightweight stand-ins mirroring the real shapes:\\n#   list[RunOutputs] \u2192 RunOutputs.outputs: list[ResultData|None]\\n#   ResultData.messages: list[ChatOutputResponse]; ChatOutputResponse.message: str|list\\n@dataclass\\nclass _CO:\\n    message: object\\n\\n\\n@dataclass\\nclass _Usage:\\n    input_tokens: object = None\\n    output_tokens: object = None\\n    total_tokens: object = None\\n\\n\\n@dataclass\\nclass _RD:\\n    messages: list = field(default_factory=list)\\n    results: object = None\\n    timedelta: object = None\\n    token_usage: object = None\\n\\n\\n@dataclass\\nclass _RO:\\n    outputs: list = field(default_factory=list)\\n\\n\\n@dataclass\\nclass _Vertex:\\n    result: object = None\\n\\n\\n@dataclass\\nclass _Graph:\\n    vertices: list = field(default_factory=list)\\n\\n\\nclass TestExtractRunResultText:\\n    def test_returns_chat_message_text(self):\\n        run_outputs = [_RO(outputs=[_RD(messages=[_CO(message=\\\"woof\\\")])])]\\n        assert extract_run_result_text(run_outputs) == \\\"woof\\\"\\n\\n    def test_joins_multiple_messages_in_order(self):\\n        run_outputs = [\\n            _RO(outputs=[_RD(messages=[_CO(message=\\\"a\\\"), _CO(message=\\\"b\\\")])]),\\n        ]\\n        assert extract_run_result_text(run_outputs) == \\\"a\\\\nb\\\"\\n\\n    def test_stringifies_list_message(self):\\n        run_outputs = [_RO(outputs=[_RD(messages=[_CO(message=[\\\"x\\\", \\\"y\\\"])])])]\\n        out = extract_run_result_text(run_outputs)\\n        assert \\\"x\\\" in out\\n        assert \\\"y\\\" in out\\n\\n    def test_falls_back_to_results_when_no_messages(self):\\n        run_outputs = [_RO(outputs=[_RD(messages=[], results={\\\"text\\\": \\\"fallback-42\\\"})])]\\n        assert \\\"fallback-42\\\" in extract_run_result_text(run_outputs)\\n\\n    def test_returns_sentinel_when_nothing(self):\\n        assert extract_run_result_text([]) == \\\"(no output)\\\"\\n        assert extract_run_result_text([_RO(outputs=[])]) == \\\"(no output)\\\"\\n        assert extract_run_result_text([_RO(outputs=[None])]) == \\\"(no output)\\\"\\n\\n    def test_caps_result_length(self):\\n        huge = \\\"z\\\" * (MAX_RESULT_CHARS * 3)\\n        run_outputs = [_RO(outputs=[_RD(messages=[_CO(message=huge)])])]\\n        out = extract_run_result_text(run_outputs)\\n        assert len(out) <= MAX_RESULT_CHARS\\n\\n    def test_handles_dict_shaped_outputs(self):\\n        # Real input is pydantic, but be resilient to dict-shaped data too.\\n        run_outputs = [{\\\"outputs\\\": [{\\\"messages\\\": [{\\\"message\\\": \\\"dict-woof\\\"}]}]}]\\n        assert extract_run_result_text(run_outputs) == \\\"dict-woof\\\"\\n\\n\\nclass TestExtractGraphTokenUsage:\\n    \\\"\\\"\\\"Token usage must be read by walking the graph's vertices.\\n\\n    It lives on each vertex's ``result.token_usage`` (LLM/Agent vertices),\\n    NOT on the run_outputs returned by the engine \u2014 those only carry the\\n    *output* vertices, whose token_usage is None by design.\\n    \\\"\\\"\\\"\\n\\n    def test_zeros_when_no_vertices(self):\\n        assert extract_graph_token_usage(_Graph(vertices=[])) == {\\n            \\\"input_tokens\\\": 0,\\n            \\\"output_tokens\\\": 0,\\n            \\\"total_tokens\\\": 0,\\n        }\\n\\n    def test_sums_token_usage_across_vertices(self):\\n        graph = _Graph(\\n            vertices=[\\n                _Vertex(result=_RD(token_usage=_Usage(input_tokens=10, output_tokens=5, total_tokens=15))),\\n                _Vertex(result=_RD(token_usage=_Usage(input_tokens=2, output_tokens=3, total_tokens=5))),\\n            ]\\n        )\\n        m = extract_graph_token_usage(graph)\\n        assert m[\\\"input_tokens\\\"] == 12\\n        assert m[\\\"output_tokens\\\"] == 8\\n        assert m[\\\"total_tokens\\\"] == 20\\n\\n    def test_ignores_vertices_without_result_or_usage(self):\\n        graph = _Graph(\\n            vertices=[\\n                _Vertex(result=None),\\n                _Vertex(result=_RD(token_usage=None)),\\n                _Vertex(result=_RD(token_usage=_Usage(total_tokens=7))),\\n            ]\\n        )\\n        assert extract_graph_token_usage(graph)[\\\"total_tokens\\\"] == 7\\n\\n    def test_handles_dict_shaped_graph(self):\\n        graph = {\\\"vertices\\\": [{\\\"result\\\": {\\\"token_usage\\\": {\\\"input_tokens\\\": 4, \\\"total_tokens\\\": 9}}}]}\\n        m = extract_graph_token_usage(graph)\\n        assert m[\\\"input_tokens\\\"] == 4\\n        assert m[\\\"total_tokens\\\"] == 9\\n\\n    def test_coerces_non_numeric_safely(self):\\n        graph = _Graph(vertices=[_Vertex(result=_RD(token_usage=_Usage(total_tokens=\\\"nan\\\")))])\\n        assert extract_graph_token_usage(graph)[\\\"total_tokens\\\"] == 0\\n\\n\\n_FLOW = {\\\"name\\\": \\\"F\\\", \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"ChatInput-1\\\"}], \\\"edges\\\": []}}\\n\\n\\nclass TestRunWorkingFlow:\\n    @pytest.mark.asyncio\\n    async def test_success_returns_result_text(self):\\n        # Token usage comes from the graph's LLM vertex; the ChatOutput the\\n        # engine returns has token_usage=None by design.\\n        graph = _Graph(\\n            vertices=[\\n                _Vertex(result=_RD(token_usage=_Usage(input_tokens=7, output_tokens=3, total_tokens=10))),\\n                _Vertex(result=_RD(messages=[_CO(message=\\\"woof\\\")], token_usage=None)),\\n            ]\\n        )\\n\\n        async def fake_run(_graph, _flow_id, **_kw):\\n            await asyncio.sleep(0.02)  # real elapsed time so the timer is exercised\\n            return ([_RO(outputs=[_RD(messages=[_CO(message=\\\"woof\\\")])])], \\\"sess-1\\\")\\n\\n        with (\\n            patch(f\\\"{MODULE}.build_graph_from_data\\\", new_callable=AsyncMock, return_value=graph),\\n            patch(f\\\"{MODULE}.run_graph_internal\\\", side_effect=fake_run),\\n        ):\\n            out = await run_working_flow(flow_data=_FLOW, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        assert out[\\\"result\\\"] == \\\"woof\\\"\\n        assert \\\"error\\\" not in out\\n        m = out[\\\"metrics\\\"]\\n        # Duration is the measured wall time of the run \u2014 a real run is never\\n        # 0.0 (the production \\\"0,0s\\\" bug); it must be a positive number.\\n        assert isinstance(m[\\\"duration_seconds\\\"], float)\\n        assert m[\\\"duration_seconds\\\"] > 0\\n        assert m[\\\"input_tokens\\\"] == 7\\n        assert m[\\\"output_tokens\\\"] == 3\\n        assert m[\\\"total_tokens\\\"] == 10\\n\\n    @pytest.mark.asyncio\\n    async def test_run_error_returns_error_envelope_not_exception(self):\\n        with (\\n            patch(f\\\"{MODULE}.build_graph_from_data\\\", new_callable=AsyncMock, return_value=object()),\\n            patch(f\\\"{MODULE}.run_graph_internal\\\", side_effect=RuntimeError(\\\"boom in ChatInput\\\")),\\n        ):\\n            out = await run_working_flow(flow_data=_FLOW, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        assert \\\"error\\\" in out\\n        assert \\\"result\\\" not in out\\n\\n    @pytest.mark.asyncio\\n    async def test_timeout_returns_error_not_hang(self):\\n        async def hang(*_a, **_kw):\\n            await asyncio.sleep(10)\\n\\n        with (\\n            patch(f\\\"{MODULE}.build_graph_from_data\\\", new_callable=AsyncMock, return_value=object()),\\n            patch(f\\\"{MODULE}.run_graph_internal\\\", side_effect=hang),\\n            patch(f\\\"{MODULE}.RUN_TIMEOUT_SECONDS\\\", 0.05),\\n        ):\\n            out = await run_working_flow(flow_data=_FLOW, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        assert \\\"error\\\" in out\\n        assert \\\"time\\\" in out[\\\"error\\\"].lower() or \\\"timed out\\\" in out[\\\"error\\\"].lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_timeout_still_reports_elapsed_and_partial_token_metrics(self):\\n        # Bug: a timeout returned only {\\\"error\\\": ...} \u2014 no duration, no\\n        # tokens \u2014 so the agent couldn't report the (already billed) cost\\n        # or how long it ran before timing out.\\n        graph = _Graph(\\n            vertices=[\\n                _Vertex(result=_RD(token_usage=_Usage(input_tokens=5, output_tokens=2, total_tokens=7))),\\n            ]\\n        )\\n\\n        async def hang(*_a, **_kw):\\n            await asyncio.sleep(10)\\n\\n        with (\\n            patch(f\\\"{MODULE}.build_graph_from_data\\\", new_callable=AsyncMock, return_value=graph),\\n            patch(f\\\"{MODULE}.run_graph_internal\\\", side_effect=hang),\\n            patch(f\\\"{MODULE}.RUN_TIMEOUT_SECONDS\\\", 0.05),\\n        ):\\n            out = await run_working_flow(flow_data=_FLOW, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        assert \\\"error\\\" in out\\n        m = out[\\\"metrics\\\"]\\n        assert m[\\\"duration_seconds\\\"] > 0\\n        assert m[\\\"total_tokens\\\"] == 7\\n        assert m[\\\"input_tokens\\\"] == 5\\n\\n\\nclass TestRunWorkingFlowSecurityGate:\\n    \\\"\\\"\\\"Refuse to RUN component code that fails the security scan.\\n\\n    The generation pipeline scans LLM code, but a flow reaching the run\\n    engine can carry code that bypassed it (build_flow inline code, an\\n    overlay .components/*.py, an imported flow). The engine exec's it, so\\n    run_working_flow must scan first and refuse on any violation \u2014\\n    deterministic, never reaching build/exec.\\n    \\\"\\\"\\\"\\n\\n    def _flow_with_code(self, code: str) -> dict:\\n        return {\\n            \\\"name\\\": \\\"Evil\\\",\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"id\\\": \\\"Custom-1\\\",\\n                        \\\"data\\\": {\\\"type\\\": \\\"Custom\\\", \\\"node\\\": {\\\"template\\\": {\\\"code\\\": {\\\"value\\\": code}}}},\\n                    }\\n                ],\\n                \\\"edges\\\": [],\\n            },\\n        }\\n\\n    @pytest.mark.asyncio\\n    async def test_should_refuse_to_run_when_a_node_has_unsafe_code(self):\\n        evil = self._flow_with_code('import os\\\\nos.system(\\\"rm -rf /\\\")')\\n        with patch(f\\\"{MODULE}.build_graph_from_data\\\", new_callable=AsyncMock) as bg:\\n            out = await run_working_flow(flow_data=evil, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        assert \\\"error\\\" in out\\n        assert \\\"result\\\" not in out\\n        assert \\\"unsafe\\\" in out[\\\"error\\\"].lower()\\n        bg.assert_not_awaited()  # never reached the graph build / exec\\n\\n    @pytest.mark.asyncio\\n    async def test_should_refuse_on_secret_exfiltration_code(self):\\n        evil = self._flow_with_code('import os\\\\nk = os.environ[\\\"OPENAI_API_KEY\\\"]')\\n        with patch(f\\\"{MODULE}.build_graph_from_data\\\", new_callable=AsyncMock) as bg:\\n            out = await run_working_flow(flow_data=evil, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        assert \\\"error\\\" in out\\n        bg.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    async def test_should_refuse_indirect_module_call_before_graph_build(self):\\n        evil = self._flow_with_code(\\\"import os\\\\ndef run(module):\\\\n    module.system('id')\\\\nrun(os)\\\")\\n        with patch(f\\\"{MODULE}.build_graph_from_data\\\", new_callable=AsyncMock) as bg:\\n            out = await run_working_flow(flow_data=evil, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        assert \\\"error\\\" in out\\n        assert \\\"unsafe\\\" in out[\\\"error\\\"].lower()\\n        bg.assert_not_awaited()\\n\\n    @pytest.mark.parametrize(\\\"code\\\", [\\\"import _ctypes\\\", \\\"from cffi import FFI\\\"], ids=[\\\"ctypes\\\", \\\"cffi\\\"])\\n    @pytest.mark.asyncio\\n    async def test_should_refuse_native_ffi_imports_before_graph_build(self, code: str):\\n        evil = self._flow_with_code(code)\\n        with patch(f\\\"{MODULE}.build_graph_from_data\\\", new_callable=AsyncMock) as bg:\\n            out = await run_working_flow(flow_data=evil, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        assert \\\"error\\\" in out\\n        assert \\\"unsafe\\\" in out[\\\"error\\\"].lower()\\n        bg.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    async def test_should_run_normally_when_code_is_safe(self):\\n        safe = self._flow_with_code(\\\"from math import isqrt\\\\n\\\\nclass C:\\\\n    pass\\\")\\n\\n        async def fake_run(_g, _f, **_kw):\\n            return ([], \\\"sess\\\")\\n\\n        with (\\n            patch(f\\\"{MODULE}.build_graph_from_data\\\", new_callable=AsyncMock, return_value=object()) as bg,\\n            patch(f\\\"{MODULE}.run_graph_internal\\\", side_effect=fake_run),\\n        ):\\n            out = await run_working_flow(flow_data=safe, flow_id=\\\"flow-1\\\", user_id=\\\"u1\\\")\\n\\n        bg.assert_awaited_once()  # no false positive \u2014 safe code still runs\\n        assert \\\"error\\\" not in out\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_run_builtin_exemption.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6e1521f83fd334d84e26e5b423c9c83ea6390bbf9cf2f421c381965ba360a418\",\"content\":\"\\\"\\\"\\\"Tests for the built-in component exemption in ``_scan_flow_component_code``.\\n\\nContext: the agent's run-time security scanner refuses to ``exec`` any flow whose\\nnode ``code`` field has forbidden imports/calls. The scanner was designed to\\ncatch LLM-generated component code, but it was also flagging *built-in* Langflow\\ncomponents (e.g., ``URLComponent`` uses ``importlib.util.find_spec`` for optional\\ndependency detection and ``os.environ.get`` for proxy config). Those built-ins\\nare part of the trusted code surface \u2014 the assistant adds them via the\\n``add_component`` tool which copies the registry's canonical template verbatim.\\n\\nRule: when a node's ``code`` is byte-identical to the registry's canonical\\ntemplate for that component ``type``, skip the scan. If the code differs (user\\nor LLM modified it), scan as before. Registry-lookup failure must fall back to\\nscan-all (never trust unverified code).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import patch\\n\\nfrom langflow.agentic.services.flow_run import _scan_flow_component_code\\n\\n\\ndef _node(*, node_id: str, component_type: str, code: str) -> dict:\\n    \\\"\\\"\\\"Shape a flow node the way the canvas serializer emits it.\\\"\\\"\\\"\\n    return {\\n        \\\"id\\\": node_id,\\n        \\\"type\\\": \\\"genericNode\\\",\\n        \\\"data\\\": {\\n            \\\"id\\\": node_id,\\n            \\\"type\\\": component_type,\\n            \\\"node\\\": {\\\"template\\\": {\\\"code\\\": {\\\"value\\\": code}}},\\n        },\\n    }\\n\\n\\n_BUILTIN_URL_CODE = \\\"\\\"\\\"import importlib\\nimport os\\n\\n# Built-in URLComponent uses importlib.util.find_spec for optional langflow\\n# detection and os.environ.get for proxy env vars \u2014 both safe in trusted code.\\nif importlib.util.find_spec(\\\"langflow\\\"):\\n    pass\\n\\nhas_proxy = any((os.environ.get(key) or \\\"\\\").strip() for key in (\\\"HTTPS_PROXY\\\",))\\n\\\"\\\"\\\"\\n\\n_MODIFIED_URL_CODE = (\\n    _BUILTIN_URL_CODE\\n    + \\\"\\\"\\\"\\n# An LLM- or user-injected line that should still trigger the scanner.\\nimport subprocess\\nsubprocess.run([\\\"echo\\\", \\\"bad\\\"])\\n\\\"\\\"\\\"\\n)\\n\\n\\nclass TestBuiltinExemption:\\n    def test_should_pass_when_node_code_is_byte_identical_to_canonical(self):\\n        # Arrange \u2014 registry exposes the canonical URLComponent code; the node\\n        # carries exactly that code (the agent's add_component tool copies it\\n        # verbatim).\\n        registry = {\\\"URLComponent\\\": {\\\"template\\\": {\\\"code\\\": {\\\"value\\\": _BUILTIN_URL_CODE}}}}\\n        payload = {\\n            \\\"nodes\\\": [_node(node_id=\\\"URLComponent-abc12\\\", component_type=\\\"URLComponent\\\", code=_BUILTIN_URL_CODE)]\\n        }\\n\\n        with patch(\\n            \\\"lfx.mcp.flow_builder_tools._state._load_registry_user_aware\\\",\\n            return_value=registry,\\n        ):\\n            violations = _scan_flow_component_code(payload)\\n\\n        # Built-in canonical code must not raise a violation, even though its\\n        # AST contains importlib + os.environ \u2014 those patterns are safe in\\n        # trusted built-in code.\\n        assert violations == []\\n\\n    def test_should_block_when_node_code_diverges_from_canonical(self):\\n        # Arrange \u2014 registry says URLComponent is the safe built-in; the node\\n        # carries modified code that adds a forbidden subprocess call.\\n        registry = {\\\"URLComponent\\\": {\\\"template\\\": {\\\"code\\\": {\\\"value\\\": _BUILTIN_URL_CODE}}}}\\n        payload = {\\n            \\\"nodes\\\": [_node(node_id=\\\"URLComponent-xyz99\\\", component_type=\\\"URLComponent\\\", code=_MODIFIED_URL_CODE)],\\n        }\\n\\n        with patch(\\n            \\\"lfx.mcp.flow_builder_tools._state._load_registry_user_aware\\\",\\n            return_value=registry,\\n        ):\\n            violations = _scan_flow_component_code(payload)\\n\\n        # The modification (subprocess import + run) must surface so we never\\n        # exec code an attacker added under cover of a trusted type name.\\n        assert len(violations) == 1\\n        assert \\\"URLComponent-xyz99\\\" in violations[0]\\n        assert \\\"subprocess\\\" in violations[0]\\n\\n    def test_should_block_unknown_component_type_when_code_has_violations(self):\\n        # Arrange \u2014 no registry entry for this type, so canonical lookup is\\n        # None and the scanner runs unchanged (treat-as-untrusted fallback).\\n        registry: dict = {}\\n        payload = {\\n            \\\"nodes\\\": [\\n                _node(\\n                    node_id=\\\"MysteryComp-1\\\",\\n                    component_type=\\\"MysteryComp\\\",\\n                    code=\\\"import subprocess\\\\nsubprocess.run(['rm', '-rf', '/'])\\\",\\n                ),\\n            ],\\n        }\\n\\n        with patch(\\n            \\\"lfx.mcp.flow_builder_tools._state._load_registry_user_aware\\\",\\n            return_value=registry,\\n        ):\\n            violations = _scan_flow_component_code(payload)\\n\\n        assert len(violations) == 1\\n        assert \\\"subprocess\\\" in violations[0]\\n\\n    def test_should_fall_back_to_scan_all_when_registry_lookup_raises(self):\\n        # Arrange \u2014 registry loader explodes (ImportError, DB outage, anything).\\n        # The scanner must default to current behavior (scan every node) so the\\n        # registry-unavailable degraded path never lets unverified code through.\\n        payload = {\\n            \\\"nodes\\\": [\\n                _node(\\n                    node_id=\\\"URLComponent-degraded\\\",\\n                    component_type=\\\"URLComponent\\\",\\n                    code=_BUILTIN_URL_CODE,\\n                ),\\n            ],\\n        }\\n\\n        with patch(\\n            \\\"lfx.mcp.flow_builder_tools._state._load_registry_user_aware\\\",\\n            side_effect=RuntimeError(\\\"registry not loaded\\\"),\\n        ):\\n            violations = _scan_flow_component_code(payload)\\n\\n        # With the registry unavailable we cannot prove the code is canonical,\\n        # so the safer choice is to scan \u2014 the built-in's importlib/os.environ\\n        # surfaces here. This is the degraded path, expected to be loud.\\n        assert len(violations) == 1\\n        assert \\\"URLComponent-degraded\\\" in violations[0]\\n\\n    def test_should_treat_trivial_whitespace_drift_as_identical(self):\\n        # Arrange \u2014 the registry's canonical code and the node's code differ\\n        # only by trailing whitespace / line endings (a common serialization\\n        # round-trip artifact). They must compare as identical.\\n        registry = {\\\"URLComponent\\\": {\\\"template\\\": {\\\"code\\\": {\\\"value\\\": _BUILTIN_URL_CODE}}}}\\n        node_code_with_trailing = _BUILTIN_URL_CODE + \\\"\\\\n\\\\n\\\"  # extra blan";
